[9180] = { ["id"] = 9180, ["name"] = "Journey to Undercity", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9180 }, ["series"] = { 9175 }, ["description"] = "This is quite extraordinary! It appears to be a gift to Lady Sylvanas Windrunner from her sister, Alleria! You must take it to her in the Undercity at once! The lady holds court in the Royal Quarter. To get there, use the orb of translocation in the Inner Sanctum of Sunfury Spire in Silvermoon City to cross over to the Undercity . Once there, take the elevator ride down into the city proper. Use your maps if you need help finding the Royal Quarter.", ["objectivesText"] = "Take The Lady's Necklace to Lady Sylvanas Windrunner at the Royal Quarter in Undercity . Progress: And you are? What's that you have there? That necklace looks somehow familiar. Give it here!", ["rewardXP"] = 250, ["rewardItems"] = { 22627, 30632, 52253 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16252, ["x"] = 0.448, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 10181, ["x"] = 0.599429, ["y"] = 0.807143 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 90, 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard" },
[9463] = { ["id"] = 9463, ["name"] = "Medicinal Purpose", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["description"] = "I have found that lashers milling about on the island hold restorative medicinal properties in their vines. Through proper treatment, the vines can be broken down into a powerful healing ointment. Unfortunately, with so many injured draenei passing through Azure Watch, we are always in short supply. Our delicate guest was found injured and unconscious by the Crystalbrook only yesterday. If you bring me vines, we may be able to save her. You will find root trappers both south and east of Azure Watch.", ["objectivesText"] = "Anchorite Fateema at Azure Watch wants you to bring her 8 Root Trapper Vines . Progress: I fear that her health is in steady decline.", ["rewardXP"] = 200, ["rewardItems"] = { 23685 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17214, ["x"] = 0.484667, ["y"] = 0.516667 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17214, ["x"] = 0.484667, ["y"] = 0.516667 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.484667, ["y"] = 0.516667 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 20, ["flags"] = 0 } } },
[9487] = { ["id"] = 9487, ["name"] = "Arcane Reavers", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 8 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9487 }, ["series"] = { 9488 }, ["description"] = "Arcane reavers are magical creations of brute strength. They are heavily armored and deliver stunning blows. You, however, can bypass their defenses and avoid their attacks. Your spellcraft is not without many advantages, <name>. Travel to Dawnstar Spire and blast apart the arcane reavers. From their remains, collect the crystallized fragments of magical energy and return to me. Dawnstar Spire is found to the east, across the lake.", ["objectivesText"] = "Arcanist Vandril wants you to collect 10 Arcane Fragments for him. Progress: Didn't get too close to the brutes, I hope?", ["rewardXP"] = 200, ["rewardItems"] = { 23706 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16197, ["x"] = 0.465, ["y"] = 0.2855 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16197, ["x"] = 0.465, ["y"] = 0.2855 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.2855 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard" },
[9603] = { ["id"] = 9603, ["name"] = "Beds, Bandages, and Beyond", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 3525, ["mapID"] = 97, ["storyline"] = { 9603 }, ["series"] = { 9604, 9605, 9606 }, ["description"] = "Welcome to Azure Watch, <class>. Please excuse the disorder you see around you. It's easy to take simple things for granted, like a fully furnished and stocked inn, until you're forced to build one from nothing. We've managed to salvage this pod for a building, but without the proper furnishings and first aid supplies, the inn is little more than a glorified tent. Nurguni at the Exodar has offered to put together a package to help with our most immediate needs, but I need someone to deliver this list to him.", ["objectivesText"] = "Take Chellan's List to the hippogryph master Zaldaan at Azure Watch. Progress: Good day, <name>. Are you interested in renting a hippogryph?", ["rewardXP"] = 100, ["rewardItems"] = { 23902 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16553, ["x"] = 0.484, ["y"] = 0.492 }, { ["mapID"] = 106, ["npcID"] = 17553, ["x"] = 0.556, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17554, ["x"] = 0.575, ["y"] = 0.54 }, { ["mapID"] = 97, ["npcID"] = 43991, ["x"] = 0.496, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 97, 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9621] = { ["id"] = 9621, ["name"] = "Envoy to the Horde", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 3487, ["mapID"] = 110, ["storyline"] = { 9621 }, ["series"] = { 9328, 9626, 9627 }, ["description"] = "There were doubts about our capabilities among our potential new allies. Of what use could we be to them when perceived as unable to deal with our problems at home? This changes everything. No longer will our power be questioned. We'll be able to join the Horde as equals. Take this letter to Sylvanas, ruler of the Forsaken. She's already on our side but the news of Dar'Khan's death will be music to her ears. Prepare for a long trip, <name>. If all goes well she will send you to Orgrimmar.", ["objectivesText"] = "Bring the Letter from Lor'themar Theron to Lady Sylvanas Windrunner in Undercity , the Forsaken capital in Tirisfal Glades. Progress: Ah, a visitor from Quel'Thalas! What news do you bring?", ["rewardXP"] = 100, ["rewardItems"] = { 23929 }, ["starts"] = { { ["mapID"] = 110, ["npcID"] = 16802, ["x"] = 0.618667, ["y"] = 0.301 } }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 10181, ["x"] = 0.599429, ["y"] = 0.807143 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.618667, ["y"] = 0.301 }, ["mapCandidates"] = { ["npc"] = { 90, 110 }, ["zone"] = { 3487 } }, ["questType"] = "standard" },
[10166] = { ["id"] = 10166, ["name"] = "Whitebark's Memory", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 10166 }, ["series"] = { 8474 }, ["description"] = "This pendant brings back memories of a different time. A better time. Unfortunately, memories are the last thing I need right now. I want you to bury this by the runestone in the Scorched Grove. It was there that I first met the treant elder. Put my old friend's memory to rest.", ["objectivesText"] = "Larianna Riverwind wants you to place Old Whitebark's Pendant by the runestone at the Scorched Grove. Progress: You've returned, <name>. Haven't you done enough?", ["rewardXP"] = 200, ["rewardItems"] = { 28209 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15398, ["x"] = 0.34, ["y"] = 0.8 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 19456, ["x"] = 0.375, ["y"] = 0.864 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.8 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[13148] = { ["id"] = 13148, ["name"] = "Necklace Repair", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 210, ["storyline"] = { 13148 }, ["description"] = "This damaged necklace has an invoice with it that reads \"Property of Timothy Jones - Cartier and Co Fine Jewelry - Magus Commerce Exhange - Dalaran\". Perhaps you should repair it and return it to him.", ["objectivesText"] = "Repair the necklace with a single Chalcedony and return it to Timothy Jones in at the Jewelcrafters Shop in the Magus Commerce Exchange in Dalaran. Progress: What brings you here?", ["rewardGold"] = 105000, ["rewardItems"] = { 36923, 43297, 43298, 43299 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 210 } }, ["questType"] = "standard", ["startItems"] = { 43297 } },
[13206] = { ["id"] = 13206, ["name"] = "Disarmament", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 206, ["mapID"] = 117, ["storyline"] = { 13206 }, ["description"] = "We must discover the secret to these savages' weapons! If you'd have seen how easily they cut through my companions, you'd understand my sense of urgency. Scour the place. Gather all of their arms that you can carry.", ["objectivesText"] = "Dark Ranger Marrah wants you to steal 5 Vrykul Weapons from Utgarde Keep and bring them to her inside Utgarde Keep . Progress: What have you got there, <class>?", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["rewardItems"] = { 43513, 44374, 44375, 44376, 44377, 44400, 44401, 44402, 44403 }, ["ends"] = { { ["mapID"] = 117, ["npcID"] = 23780, ["x"] = 0.785, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 117, ["source"] = "quest_giver", ["x"] = 0.785, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 117 }, ["zone"] = { 206 } }, ["questType"] = "dungeon" },
