[24441] = { ["id"] = 24441, ["name"] = "Thunderhorn Totem", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1638, ["mapID"] = 7, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["series"] = { 20441, 24440, 24456, 24457, 24523, 24524, 24540, 24550, 44498 }, ["description"] = "There is more work to be done. We must create a new totem to cleanse the Thunderhorn Well. You must gather the claws of the predators of the Mulgore plains. Hunt prairie stalkers for their stalker claws and flatland cougars for their cougar claws , then return to me. You will find the prairie stalkers and flatland cougars to the east and west.", ["objectivesText"] = "Collect 6 Stalker Claws and 6 Cougar Claws . Progress: <name>, do you have the claws I sent you to gather? The Thunderhorn Water Well grows more tainted with each passing hour!", ["rewardXP"] = 200, ["rewardItems"] = { 4801, 4802 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 2948, ["x"] = 0.485, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 2948, ["x"] = 0.485, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 1638 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7, ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 8, ["flags"] = 0 } } },
[24523] = { ["id"] = 24523, ["name"] = "Wildmane Totem", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1, ["mapID"] = 7, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["series"] = { 20441, 24440, 24441, 24456, 24457, 24524, 24540, 24550, 44498 }, ["description"] = "There is but one water well left to cleanse, named after the Wildmane clan. For this well to be pure, the land must offer the teeth of a fierce predator, the prairie wolf alpha. Find the alphas to the north, then return to me when your hunt is finished. Alphas often wander around the base of our mighty city, Thunder Bluff.", ["objectivesText"] = "Collect 4 Prairie Alpha Teeth from Prairie Wolf Alphas. Progress: <name>. Do you have the teeth I asked for?", ["rewardXP"] = 200, ["rewardItems"] = { 4803 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 37024, ["x"] = 0.494, ["y"] = 0.174 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 37024, ["x"] = 0.494, ["y"] = 0.174 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.174 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 18, ["flags"] = 0 } } },
[25377] = { ["id"] = 25377, ["name"] = "The Horde's Hoard", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 4815, ["storyline"] = { 25377 }, ["description"] = "It is unclear what manner of creature scrawled the seemingly random markings on this piece of parchment, but upon close inspection, some of the obscure shapes begin to look like landmarks. Scanning the sea floor, you think you recognize a few points of reference, one being a nearby sunken ship. If your guess is correct, there appears to be treasure of some kind near the wreck. You cannot help but wonder what the scaly, serpentine figure on the map might represent....", ["objectivesText"] = "You must defeat Akasha to obtain the Horde Chest Key which you must then use to open the Sunken Horde Chest . Progress: This slightly encrusted lock might still be functional.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 53053, 53054, 54345, 54639, 55186, 59788 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4815 } }, ["questType"] = "standard", ["startItems"] = { 53053 } },
[25419] = { ["id"] = 25419, ["name"] = "Lady La-La's Medallion", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 4815, ["storyline"] = { 25419 }, ["description"] = "Dozens of crude gold links make up this heavy chain. Dangling from the center link is an opalescent fragment of what must have once been a large shell-shaped medallion. You wonder if the other fragments might be nearby, and if the medallion might be reassembled into its original state.", ["objectivesText"] = "Collect the 5 Medallion Fragments from Gilblin Collectors and combine them to create Lady La-La's Medallion .", ["rewardXP"] = 4115, ["rewardItems"] = { 53053, 54345, 54639, 55186, 55187, 55188, 59782, 59783, 59784 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4815 } }, ["questType"] = "standard", ["startItems"] = { 55186 } },
[25467] = { ["id"] = 25467, ["name"] = "Kliklak's Craw", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 4815, ["storyline"] = { 25467 }, ["description"] = "You are pleasantly surprised to find that after being mangled and masticated by a sea crab, this map is still quite legible. It clearly indicates that a footlocker was buried in the Kelp'thar Forest behind a gigantic mollusk. A well-drawn sketch on the back of the map shows that the owner, along with his key, was eaten by an overgrown crustacean named Kliklak.", ["objectivesText"] = "Obtain the Corroded Key from Kliklak to unlock the Half-buried Footlocker in the Kelp'thar Forest . Progress: The footlocker's keyhole is encrusted with barnacles, but may still be operable.", ["rewardGold"] = 561800, ["rewardXP"] = 4115, ["rewardItems"] = { 54344, 54345, 55186, 59798 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4815 } }, ["questType"] = "standard", ["startItems"] = { 54345 } },
[25503] = { ["id"] = 25503, ["name"] = "Blackfin's Booty", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 4815, ["storyline"] = { 25503 }, ["description"] = "<A torn page precedes the latest entry, which reads:> Our self-proclaimed king will stop at nothing to acquire my family fortune. He has threatened and harassed me to no end. I can't take it anymore! I've buried the treasure and fed the map to Blackfin. That should keep my cousin's grubby little mitts off of our precious heirlooms!", ["objectivesText"] = "You must slay the orca, Blackfin, to retrieve Gilblingle's Map . Progress: You've discovered Gilblingle's family treasure!", ["rewardXP"] = 4115, ["rewardItems"] = { 53053, 54345, 54639, 54640, 55186, 59779, 59780, 59781 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4815 } }, ["questType"] = "standard", ["startItems"] = { 54639 } },
[26394] = { ["id"] = 26394, ["name"] = "Continue to Stormwind", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 26394 }, ["series"] = { 26393, 26395, 26396 }, ["description"] = "For a small fee, you can take a gryphon to Stormwind, so you can deliver Argus' note to Osric. You won't get there faster any other way. If that sounds acceptable, then just speak to me again when you're ready for the ride. I'll charge you a little, but trust me; it'll be worth it!", ["objectivesText"] = "Buy a gryphon ride from the gryphon master Bartlett the Brave , then bring Argus' Note to Osric Strang , in the shop Limited Immunity, in the Old Town of Stormwind. Progress: You've been traveling, eh? Have you been anywhere interesting?", ["rewardGold"] = 140450, ["rewardXP"] = 100, ["rewardItems"] = { 58364 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 42983, ["x"] = 0.417, ["y"] = 0.645 }, { ["mapID"] = 37, ["npcID"] = 43000, ["x"] = 0.818, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 1323, ["x"] = 0.77, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.417, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 37, 84 }, ["zone"] = { 12 } }, ["questType"] = "standard" },
[26395] = { ["id"] = 26395, ["name"] = "Dungar Longdrink", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 26395 }, ["series"] = { 26393, 26394, 26396 }, ["description"] = "<name>, I gathered into this crate everything Argus asked for. Can you take it to him? If you've already spoken to Bartlett at Goldshire, then you can take a gryphon back to him. Dungar Longdrink is our gryphon master, over in the trade district. Speak with Dungar, then get this crate to Argus as fast as you can. We don't want our fighting men and women in Goldshire to go without fresh equipment!", ["objectivesText"] = "Bring Osric's Crate to Dungar Longdrink the gryphon master. Progress: Is that sweat on your brow, lad? You've been running too much. Next time, take a gryphon!", ["rewardXP"] = 50, ["rewardItems"] = { 16115 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 1323, ["x"] = 0.77, ["y"] = 0.612 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 352, ["x"] = 0.618, ["y"] = 0.728667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.77, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[27047] = { ["id"] = 27047, ["name"] = "Motes", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27047 }, ["description"] = "Some of the rarest crystals form in the most dangerous places. In the Crumbling Depths, you will find painite formations - much better than the gold that your races cherish so much. As a being of flesh and a being of small stature, you can enter the Crumbling Depths to retrieve motes of painite for me. Would you undergo that danger on my behalf?", ["objectivesText"] = "Recover 10 Motes of Painite. Progress: Painite is one of the most valuable materials to us, particularly due to our inability to reach most of the deposits on our own.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 60791, 177698, 178874, 178880, 178881, 178882, 178883, 185717, 189544, 190189, 190341, 190343, 190344, 190345, 190346, 190348, 190351, 190352, 190353, 190354, 190355, 190356, 190358, 190359, 190360, 190361, 190363, 190364, 190366, 190368, 190369, 190371, 190372, 190605, 190632, 190633, 190634, 192423, 192424, 192425, 192427, 192429, 192430, 192440, 192450, 192451, 195210 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43805, ["x"] = 0.56, ["y"] = 0.144 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43805, ["x"] = 0.56, ["y"] = 0.144 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.144 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27048] = { ["id"] = 27048, ["name"] = "Underground Economy", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27048 }, ["description"] = "Hey! I need some help gatherin' crystals. The elementals trade top dollar for these things... if you help me gather all the different kinds, I'll cut you in on the profits. Use these bombs to blow out chunks from the bigger formations. I've got a nasty habit of packin' the explosives a bit thick. Mind the kick.", ["objectivesText"] = "Use Ricket's Tickers to gather 3 Deep Alabaster Crystals , 3 Deep Celestite Crystals , 3 Deep Amethyst Crystals , and 3 Deep Garget Crystals. Progress: Boom?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 65504, 65507, 65508, 65510, 65514 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44968, ["x"] = 0.612, ["y"] = 0.262 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 44968, ["x"] = 0.612, ["y"] = 0.262 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.262 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27051] = { ["id"] = 27051, ["name"] = "Through Persistence", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 27051 }, ["description"] = "The troggs did not disperse after you killed Glop. His servants recovered the growth agent that was left behind and continue to sow the seeds of corruption across the Crimson Expanse. Hunt them down and recover any of the remaining Verlock Miracle-Grow that you find. It must be disposed of.", ["objectivesText"] = "Retrieve a Bag of Verlok Miracle-Grow from the Verloks upon the Crimson Expanse. Progress: Have you done as I've asked of you? We must weed out the whatever growth agent remains within their possession.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 38626, 60767, 60768 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44973, ["x"] = 0.595, ["y"] = 0.14 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 44973, ["x"] = 0.595, ["y"] = 0.14 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.14 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[27839] = { ["id"] = 27839, ["name"] = "Ancient Weapons", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 27839 }, ["series"] = { 28201 }, ["description"] = "Though we aren't formally at war yet, the Neferset do not hesitate to imprison or kill all who trespass upon their territories. King Phaoris refuses to reciprocate, even when they use our lands to smuggle stolen relics from the tombs of our ancestors. My scouts report that the Neferset are about to move a major shipment of looted weapons south of here. I've instructed the laborers you recruited to assist you. Call upon them with this horn when you find the smugglers and recover the weapons.", ["objectivesText"] = "Retrieve the Ancient Tol'vir Armaments . Progress: You've returned, <name>. How did the operation go?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 62533, 62534, 65834, 65835, 65836, 237812 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 46134, ["x"] = 0.373, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 46134, ["x"] = 0.373, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.373, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard" },
[28141] = { ["id"] = 28141, ["name"] = "Relics of the Sun King", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 28141 }, ["description"] = "The Seal of the Sun King serves as a defense mechanism for Ramkahen. When the barrier around Uldum fell, we began to see Wastewander outriders from Tanaris filter into our borders. They attacked this holy site on their way west and robbed it of the relics which once provided its power. Recover the relics for us. Without them we are powerless to defend against attacks from the desert.", ["objectivesText"] = "Obtain 4 Relics of the Sun King . Progress: Did you succeed?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 63081 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 47715, ["x"] = 0.53, ["y"] = 0.276 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 47715, ["x"] = 0.53, ["y"] = 0.276 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.276 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard" },
[28200] = { ["id"] = 28200, ["name"] = "The Element of Supplies", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 28200 }, ["description"] = "You'll notice that we're slightly ill prepared for battle. The tol'vir tribes had never seen any sort of major confrontation for thousands of years. All the combat protocols that the titans programmed into our ancestors are still there, though. Some are part of our instincts, some get passed on as tradition. But none of this can compensate for lack of supplies. We need weapons. We need armor. The best armor is lined with the skin of the riverbed crocolisks nearby. Help us gather some.", ["objectivesText"] = "Collect 20 Hardened Crocolisk Hides . Progress: I am glad to see you don't think you're above this sort of task.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 63256, 65837, 65838, 65839, 65840 }, ["starts"] = { { ["mapID"] = 249, ["npcID"] = 48012, ["x"] = 0.373, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 48012, ["x"] = 0.373, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.373, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard" },
[28488] = { ["id"] = 28488, ["name"] = "Beneath the Surface", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 28488 }, ["description"] = "Among the other precious gemstones hidden deep out of our reach in the Crumbling Depths, there are enormous ruby crystal clusters . They are infused with terrible energy. It will not be easy to obtain such a thing, for they are well guarded. But you, you are stubborn and brave. I think this is something you can do. Within the Crumbling Depths, look to where the tunnels end abruptly in stone. The clusters are found in those passages when they are to be found at all. Should you find one, return to me.", ["objectivesText"] = "Recover an Enormous Ruby Crystal Cluster . Progress: These crystals are of great value, particularly to Gorsik. I shall have a heavy sway over him if I come into possession of one. I wish this to be so.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 64404, 64494 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 43805, ["x"] = 0.56, ["y"] = 0.144 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43805, ["x"] = 0.56, ["y"] = 0.144 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.144 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[28779] = { ["id"] = 28779, ["name"] = "A Long Way from Home", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5035, ["storyline"] = { 28779 }, ["description"] = "I've a feeling I was able to escape my captors because, frankly, there is nowhere to go. Stranded on these platforms, they are bound to find me sooner or later. Unless... It is said that the heart of an elemental noble can grant whoever holds it the characteristics of that element. Which, in the case of air, would be most useful during a downward trip. Bring me Grand Vizier Ertan's heart so I can use its magic to land safely on the shoreline of Uldum.", ["objectivesText"] = "Obtain Grand Vizier Ertan's Heart . Progress: You'd best not suggest I ride with you on... whatever that thing is you flew in on.", ["rewardGold"] = 137400, ["rewardXP"] = 4115, ["rewardItems"] = { 65660, 66898, 66899, 66900 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5035 } }, ["questType"] = "dungeon" },
[28815] = { ["id"] = 28815, ["name"] = "Twilight Documents", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5088, ["storyline"] = { 28815 }, ["series"] = { 28814 }, ["description"] = "We've tailed one of the Twilight's Hammer operatives here. He goes by the name of Millhouse Manastorm. We have reason to believe he's carrying important documents. This is as far as we can safely go, however, without neglecting our duty to defend the Temple of Earth's inner perimeter. Track down Manastorm and retrieve the documents from him.", ["objectivesText"] = "Obtain the Twilight Documents . Progress: These appear to be the right documents.", ["rewardGold"] = 137400, ["rewardXP"] = 8230, ["rewardItems"] = { 65734 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5088 } }, ["questType"] = "dungeon" },
[28853] = { ["id"] = 28853, ["name"] = "Kill the Courier", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4950, ["storyline"] = { 28853 }, ["description"] = "Thank you, <class>, for braving the horrors of this dark and terrible place. The bowels of Grim Batol are the heart of Cho'gall's war machine. If we are to stop his machinations throughout the Highlands, we must learn all we can from these depths. Seek out Drahga Shadowburner within. He is Cho'gall's runner, the link between here and the Bastion of Twilight. We must learn the secrets he carries.", ["objectivesText"] = "Kill Drahga Shadowburner and grab his Missive to Cho'gall . Progress: What have you discovered, <class>?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 66927, 66936, 66937, 66938 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4950 } }, ["questType"] = "dungeon" },
[29246] = { ["id"] = 29246, ["name"] = "Relieving the Pain", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29246 }, ["description"] = "The Arch Druid has an immense tolerance for pain. I've treated burn victims that spend twenty-two hours a day screaming in pain, and their burns weren't even half as bad as what Hamuul has suffered. Nevertheless, I can sense that he is in greater discomfort than normal today. Bring me the hearts of the large fire elementals to the southeast. I can use them to prepare a soothing salve for our patient.", ["objectivesText"] = "Obtain 4 Flame-Wreathed Hearts from Seething Firelords. Progress: These hearts will give us exactly what Hamuul needs to rest.", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["rewardItems"] = { 69678 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52986, ["x"] = 0.275, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52986, ["x"] = 0.275, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29247] = { ["id"] = 29247, ["name"] = "Treating the Wounds", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29247 }, ["description"] = "We have an ample supply of medical supplies here at the Sanctuary, but we mustn't lose sight of the fact that we are at war. Hamuul isn't the only person who has need of bandages. The fiery behemoths that roam Sethria's Roost wear flame-resistant wrappings that will serve Hamuul as ably as any bandage. Bring me those wrappings, and I will prepare them for use on the Arch Druid.", ["objectivesText"] = "Obtain 4 Sulfur-Laced Wrappings from Fiery Behemoths in Sethria's Roost. Progress: There are some who say that the sulfur in those wrappings has curative properties. Personally, I am unconvinced, but I am willing to endure the smell on the off-chance that it does.", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["rewardItems"] = { 69677 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52986, ["x"] = 0.275, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52986, ["x"] = 0.275, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29248] = { ["id"] = 29248, ["name"] = "Releasing the Pressure", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 616, ["mapID"] = 198, ["storyline"] = { 29248 }, ["description"] = "Having been burned so badly, Arch Druid Hamuul is suffering from edema - swelling of the body's tissues. It takes a great deal of his attendants' effort to keep his swelling down enough for him to breathe. Normally, to reduce this swelling, we make cuts in his flesh, but he is weak, <name>. I cannot cut him today. I need your help. Flamewaker scales will aid with the swelling, but you need a lot of them.", ["objectivesText"] = "Obtain 100 Flamewaker Scales . Progress: Do you have the scales? I hesitate to cut the Arch Druid again, but we must relieve the swelling somehow.", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["rewardItems"] = { 69679 }, ["starts"] = { { ["mapID"] = 198, ["npcID"] = 52986, ["x"] = 0.275, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 198, ["npcID"] = 52986, ["x"] = 0.275, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 198, ["source"] = "quest_giver", ["x"] = 0.275, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 198 }, ["zone"] = { 616 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Engine of Innovation" },
[29274] = { ["id"] = 29274, ["name"] = "Hounds of Shannox", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5733, ["storyline"] = { 29274 }, ["description"] = "On the Firelands' largest island, our troops have been having trouble against Shannox, the flamewaker hunter. Not only does he have impeccable aim, but he keeps trained hounds that give our troops no end of trouble. Tholo, in all his wisdom, thinks it would be a good idea to study the biology of these hounds. I, of course, agree with Tholo. You will find several hounds in the Molten Flow, beneath the Furnace. We will need their ashes to study.", ["objectivesText"] = "Obtain 6 small piles of Houndbone Ash . Progress: Any information we can get will be instrumental in helping our men defeat Shannox.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69816 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29288] = { ["id"] = 29288, ["name"] = "Starting Young", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5733, ["storyline"] = { 29288 }, ["description"] = "Our scouts are bringing back reports of fire hawk hatchlings all over the peak... their eggs must have hatched very recently. Better yet, it seems that they're extremely docile. I know it may sound a strange and perhaps unsavory request, but if you were able to bring some of those hatchlings back to me, I might be able to train them to aid us in our war efforts. Are you willing?", ["objectivesText"] = "Recover 5 Fire Hawk Hatchlings . Progress: I can't make up my mind on how to regard these creatures. They act like much like other avians, but they are very obviously native to this fiery place. I wonder why Ragnaros and his minions have not made attempts to rally them against us...", ["rewardGold"] = 280900, ["rewardXP"] = 4385, ["rewardItems"] = { 60854, 69845 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[33336] = { ["id"] = 33336, ["name"] = "The Essence of Time", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6757, ["storyline"] = { 33336 }, ["series"] = { 33161, 33337, 33338, 33375, 33376, 33377, 33378, 33379 }, ["description"] = "It is about time that I revealed to you my purpose on this island. The bronze dragonflight's powers have diminished greatly - we can now only catch furtive glimpses through time. It is... quite frustrating. But we are not entirely without means. I hold in my hand the Vision of Time, an artifact of my own creation. The creatures of this isle have passed through time, and may carry with them some of its essence. With it, we will fill the hourglass, granting us a window into the timeways once more.", ["objectivesText"] = "Obtain an Epoch Stone from one of the creatures on the Timeless Isle . Progress: Have you found anything?", ["rewardGold"] = 28090, ["rewardXP"] = 4115, ["rewardItems"] = { 105715, 211279, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard" },
[33338] = { ["id"] = 33338, ["name"] = "Empowering the Hourglass", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6757, ["storyline"] = { 33338 }, ["series"] = { 33161, 33336, 33337, 33375, 33376, 33377, 33378, 33379 }, ["description"] = "The hourglass gives us glimpses into the streams of time we once walked as easily as a well-worn path. Gather additional epoch stones , so that we may continue to use the power of the hourglass to delve into the mysteries of the timeways. The future depends on it.", ["objectivesText"] = "Collect Epoch Stones from creatures on the Timeless Isle . Progress: Epoch stones are rare, crystallized temporal essence.", ["rewardXP"] = 4115, ["rewardItems"] = { 105715, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6757 } }, ["questType"] = "standard" },
[33450] = { ["id"] = 33450, ["name"] = "The Warlord's Guard", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 33450 }, ["series"] = { 33412, 33454 }, ["description"] = "I don't know what you are accustomed to, traveler, but these lands devour the weak. Perhaps Durotan wishes to rid himself of you. We shall see. You must kill the Warlord of the Circle of Blood. Do this and the ogres here will be defeated. But first, you must find him. I have located his bodyguards nearby. Slay them and bring me their heads. With them, we shall lure the Warlord into the open.", ["objectivesText"] = "Gather the Head of Thunk , the Head of Gullok , and the Head of Splorg . Progress: You still draw breath, hmm? Have you dealt with the warlord's underlings?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 106134, 106145, 106158, 106177, 106942, 106943, 106944 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 74635, ["x"] = 0.244, ["y"] = 0.287 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 74635, ["x"] = 0.244, ["y"] = 0.287 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.244, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[33462] = { ["id"] = 33462, ["name"] = "Thunderlord for a Day", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6720, ["storyline"] = { 33462 }, ["description"] = "Pieces of a Thunderlord chain lay on the ground. It is of a very simple design, but effective. With enough parts, even the most unskilled person could assemble a chain and grapple as effective as those used by the Thunderlord Grapplers.", ["objectivesText"] = "Build a Thunderlord Grapple . Progress: This shoddy, beaten anvil is used mostly for crafting chains and what little other metal working the Thunderlord require.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 101677, 101690, 101691 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[33684] = { ["id"] = 33684, ["name"] = "The Inkmasters of the Arboretum", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 33684 }, ["description"] = "I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill. You should speak with Inkmaster Wei, if you wish to help.", ["objectivesText"] = "Speak with Inkmaster Wei at the Arboretum in the Jade Forest.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[34691] = { ["id"] = 34691, ["name"] = "Just the Beginning", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 34691 }, ["description"] = "I forgive Orgrim. He acted as well all must - we do what our hearts tell us is right. We should return to your outpost and discuss our next course of action. There is nothing left for us here. I will ask the human to open a portal for us. We shall speak again there.", ["objectivesText"] = "Speak to Durotan in Talador .", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[36262] = { ["id"] = 36262, ["name"] = "Ameeka, Master Tailor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7078, ["mapID"] = 539, ["storyline"] = { 36262 }, ["series"] = { 36236, 36266, 36269 }, ["description"] = "Ameeka created this book to document and pass down our most cherished crafting techniques to our children. She must have dropped it while traveling. She will be relieved to see her book. From what I have heard from other villagers, she was last seen on the road to Elodor. Perhaps you can find her there.", ["objectivesText"] = "Speak to Ameeka in Elodor. Progress: Hello, traveler! Is there something that I can help you with?", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 115454 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84523, ["x"] = 0.582, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36646] = { ["id"] = 36646, ["name"] = "Your First Engineering Work Order", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7078, ["storyline"] = { 36646 }, ["description"] = "Now that the engineering works is complete, we can start producing gearspring parts for you. When you have the ingredients, please speak with my assistant to start the first work order.", ["objectivesText"] = "Start and collect your first Engineering work order at the Engineering Works. Progress: Yes?", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 109118, 109119, 111366, 116845 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
