[37568] = { ["id"] = 37568, ["name"] = "Your First Alchemy Work Order", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7004, ["storyline"] = { 37568 }, ["description"] = "Now that the alchemy lab is complete, we can start producing alchemical catalysts for you. When you have the ingredients, please speak with my assistant to start the first work order.", ["objectivesText"] = "Start and collect your first Alchemy work order at the Alchemy Lab. Progress: Yes?", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 108996, 116842 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37570] = { ["id"] = 37570, ["name"] = "Your First Enchanting Work Order", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7004, ["storyline"] = { 37570 }, ["description"] = "Now that the enchanter's study is complete, we can start producing draenic dust for you. When you have the ingredients, please speak with my assistant to start the first work order.", ["objectivesText"] = "Start and collect your first Enchanting work order at the Enchanter's Study. Progress: Yes?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 115504, 116844 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37574] = { ["id"] = 37574, ["name"] = "Your First Leatherworking Work Order", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7004, ["storyline"] = { 37574 }, ["description"] = "Now that the tannery is complete, we can start producing burnished leather for you. When you have the ingredients, please speak with my assistant to start the first work order.", ["objectivesText"] = "Start and collect your first Leatherworking work order at the Tannery. Progress: Yes?", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 110611, 116840 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[37930] = { ["id"] = 37930, ["name"] = "Whelp? That Happened.", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 37930 }, ["rewardGold"] = 15, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[38219] = { ["id"] = 38219, ["name"] = "Defending The Grove", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["storyline"] = { 38219 }, ["series"] = { 38225 }, ["description"] = "The harpies have had a presence in Val'Sharah for hundreds of years. They have never been much more than an occasional nuisance; thus we have tolerated their presence here within these woods. However, something has emboldened them... it feels as though the forest is weakening... they must sense it as well. The opportunistic harpies have broken the peace and attacked us in a time of weakness. Help us defend Thas'talah by slaying the invaders.", ["objectivesText"] = "Slay 12 Harpies involved in the attack on Thas'talah.", ["rewardGold"] = 158000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard" },
[38285] = { ["id"] = 38285, ["name"] = "Menacing Sprites", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 38285 }, ["description"] = "The local sprites are running amok and causing all sorts of problems! Val'sharah is home to a variety of forest and pond sprites will take any opportunity to spread mischief and chaos. It seems as though an especially wicked group of sprites have descended upon Thas'talah in the wake of the harpy invasion. They are attacking the local wildlife and bullying the nearby faerie dragons. If you aid the local woodland creatures by taking care of the sprite menace, you will have our thanks.", ["objectivesText"] = "Slay 10 sprites in Thas'talah.", ["rewardGold"] = 170000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[38308] = { ["id"] = 38308, ["name"] = "Eyes in the Overlook", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["storyline"] = { 38308 }, ["series"] = { 38317 }, ["description"] = "Alliance personnel from the Skyfire were spotted parachuting into Blackbeak Overlook. I was unable to confirm numbers or positions during my flyover, but I did see parachutes tangled in treetops and a LOT of ravenbears on the ground. If anyone is up there, they must be laying low and keeping an eye on us. I have posted a rider at the top of the overlook to keep watch while I press forward into Stormheim . - Liza Cullen, Dread-Rider - 1st Wing", ["objectivesText"] = "Recover the SI:7 Intel from Spymaster Knockwhistle in Blackbeak Overlook.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 122581, 129093 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard" },
[38317] = { ["id"] = 38317, ["name"] = "Masters of Disguise", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 38317 }, ["series"] = { 38308 }, ["description"] = "<You scan over Knockwhistle's report.> \"My chute caught a piece of shrapnel. Made a rough landing in a ravenbear nest. Luckily, a bunch of eggs broke my fall. Lost sight of Illandris and Shwayder. Both are masters of disguise, and I am confident they can remain undetected. Will continue to monitor the enemy's activity. Just need to clean all the yolk off my cloaking device. Hope the mother's not around...", ["objectivesText"] = "Slay Spymaster Illandris and Spymaster Shwayder . Progress: We cannot speak freely - the Alliance have eyes and ears in the hills.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129093, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 113911, ["x"] = 0.332, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97250, ["x"] = 0.364, ["y"] = 0.365 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard" },
[38341] = { ["id"] = 38341, ["name"] = "Halting the Nightmare", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 38341 }, ["description"] = "The corruption of the vale is the work of satyrs. The new power they wield is unlike any I've seen... it is dark, seething and terrible. Nefarious demon totems help spread their taint upon the land. The Nghtmare totems must be destroyed if we are to hold back the tide of corruption.", ["objectivesText"] = "Destroy 3 Nightmare Totems in the Moonclaw Vale.", ["rewardGold"] = 170000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[38343] = { ["id"] = 38343, ["name"] = "Raze Hel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7588, ["mapID"] = 634, ["storyline"] = { 38343 }, ["objectivesText"] = "Hel-Raiser", ["rewardGold"] = 404400, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Hel-Raiser", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[38353] = { ["id"] = 38353, ["name"] = "Rescued From Darkness", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 38353 }, ["description"] = "Midnight Vale is home to a unique breed of Nightsaber known as the Vale Prowler. For centuries, our clan has lived in harmony with these great feline hunters. However, even as we speak satyrs are twisting and corrupting the vale into a place of death and nightmare. Even the forest itself lashes out in torment against the living, causing many of the forest creatures to flee the vale. I fear for the safety of the youngest nightsabers, who may yet be caught in the twisting chaos, unable to escape.", ["objectivesText"] = "Save 7 Prowler Cubs in The Midnight Vale.", ["rewardGold"] = 162000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
