[38607] = { ["id"] = 38607, ["name"] = "Gates of Valhallas", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 38607 }, ["description"] = "Escaping the grasp of Helya is no small feat. You may prove to be a worthy warrior after all. Skovald has entered Valhallas; you are running out of time. Legion has corrupted the minds of the Skovald's men. A battalion of unworthy vrykul is attempting to enter the portal to Valhallas. The giants that protect the gates are fighting a losing battle. There is no end to Legion's onslaught. Speak with the dragon, Vehdir, inside the gates near the portal. He will aid you on your next task.", ["objectivesText"] = "Speak with Vedhir.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
