[38648] = { ["id"] = 38648, ["name"] = "Black Rook Orders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 38648 }, ["description"] = "The letter is written in midnight ink: \"A demon invasion is imminent, but as long as the fires of Black Rook Hold blaze, we shall protect kaldorei lands. Kill any intruders who stand in our way.\" - K.R.\" Perhaps Jarod Shadowsong will want to see this.", ["objectivesText"] = "Return to Commander Jarod Shadowsong at Bradensbrook.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[38668] = { ["id"] = 38668, ["name"] = "Our Last Hope", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 38668 }, ["series"] = { 38669, 38672 }, ["description"] = "Your jailor, Maiev Shadowsong, stands outside the open door to your cell. The leader of the Wardens has just finished removing your bonds. In the distance, you can hear sounds of battle. The unmistakable stench of the Burning Legion wafts through the air.", ["objectivesText"] = "Speak with Maiev Shadowsong in the Illidari Cellblock.", ["rewardGold"] = 78750, ["rewardXP"] = 25, ["rewardItems"] = { 13444, 13446, 140244, 194338, 194381, 194382, 194383, 237812, 246863 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[38669] = { ["id"] = 38669, ["name"] = "Our Last Hope", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 38669 }, ["series"] = { 38668, 38672 }, ["description"] = "The Vault has fallen to the Burning Legion. It pains me to say it, but all is lost, but for one glimmer of hope... YOU. Believe me when I say, I did NOT want to have to do this. However, it would seem I have no choice. Help me, demon hunter, and I will grant you your freedom.", ["objectivesText"] = "Retrieve your new warglaives.", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 13444, 13446, 140244, 194338, 194381, 194382, 194383, 237812, 246863 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[38673] = { ["id"] = 38673, ["name"] = "The Wormtalon Crone", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["storyline"] = { 38673 }, ["description"] = "A wicked coven of harpies have overtaken our village. It was the twisting of the forest that forced us out of our village, but now that the harpies have moved in I fear that we may never be able to return. The Wormtalon coven are led by a witch called Grelda the Crone. She has made her nest in a cave near our village. If their leader is defeated, the remaining harpies will surely flee. Slay Grelda the Crone and we will be forever in your debt, <class>.", ["objectivesText"] = "Slay Grelda the Crone.", ["rewardGold"] = 170000, ["rewardXP"] = 200, ["rewardItems"] = { 130122 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard" },
