[38681] = { ["id"] = 38681, ["name"] = "7.0 Stormheim - Treasure 028 - Mountain Cave - ZTO", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 38681 }, ["rewardGold"] = 231000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2VignetteID"] = 839, ["db2VignetteName"] = "Treasure Chest" },
[38697] = { ["id"] = 38697, ["name"] = "The Sword of Truth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 38697 }, ["description"] = "Lord Ravencrest's army rises from the dead, but I believe they are controlled by Gul'dan's will. Take this - Lord Ravencrest's blade, Fal'shathil. It was known for a unique, magical quality. Those who gazed upon its mirrored blade found themselves unable to deny the truth. Take the blade and plant it in the ground. Attack the night elven ghosts near its light. Once they are weakened in its presence, perhaps they will regain their senses.", ["objectivesText"] = "Place Fal'shathil on the ground, then defeat Black Rook night elves within its holy light.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127897 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[38699] = { ["id"] = 38699, ["name"] = "Competitive Exorcise", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 40, ["storyline"] = { 38699 }, ["description"] = "Think you're good at sending demons back to the hell from whence they came? Show me! I once bagged 15 in under 10 minutes. Do better than that and there'll be brew money waitin' for ya.", ["objectivesText"] = "Kill 15 Burning Legion invaders in 10 minutes or less.", ["rewardXP"] = 50, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 40 } }, ["questType"] = "standard" },
[38737] = { ["id"] = 38737, ["name"] = "An End To War", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["storyline"] = { 38737 }, ["description"] = "It appears that the great Ancient of War, Ironbranch , has fallen to the Nightmare. It pains me greatly to ask this of you, but Ironbranch must be put to rest. In life, he once stood vigil in Shala'nir as a protector of the world tree. In death, my dear friend is no more than a destructive weapon that will be used to cause even more violence. He must be slain before he does more harm to Val'sharah . In my heart, I know that he would thank you for this mercy...", ["objectivesText"] = "Defeat Ironbranch .", ["rewardGold"] = 17000, ["rewardXP"] = 25, ["rewardItems"] = { 141618, 141619 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard" },
[38738] = { ["id"] = 38738, ["name"] = "7.0 Stormheim - Treasure 029 - Waterfall - ZTO", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 38738 }, ["rewardGold"] = 231000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2VignetteID"] = 854, ["db2VignetteName"] = "Treasure Chest" },
[38744] = { ["id"] = 38744, ["name"] = "7.0 Stormheim - Treasure 030 - Statue - ZTO", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 38744 }, ["rewardGold"] = 231000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2VignetteID"] = 855, ["db2VignetteName"] = "Small Treasure Chest" },
[38745] = { ["id"] = 38745, ["name"] = "Hard Lessons", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["storyline"] = { 38745 }, ["description"] = "Please understand, stranger, that I am a being of peace. I have discarded any vengeful nature long, long ago. In my youth, however, many hard lessons were learned through discipline. When applied wisely and properly, discipline can be a great teacher and shaper of character. It is in the spirit of wisdom and guidance that I would have you teach these harpies a memorable lesson.", ["objectivesText"] = "Burn 5 Harpy Nests and Break 5 Harpy Eggs in the Wretched Grove.", ["rewardGold"] = 158000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard" },
[38777] = { ["id"] = 38777, ["name"] = "Leystone Deposit Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 38777, 38784, 38785, 38786, 38787, 38789, 38790, 38791, 38792, 38793, 38794, 38888 }, ["description"] = "This ore looks like nothing you've seen before. A mystical sheen moves through the metal in complex, unpredictable patterns. Your trainer in Dalaran would certainly like to see this.", ["objectivesText"] = "Bring the Leystone Deposit Sample to Mama Diggs in Dalaran. Progress: What's that you've got there, boy?", ["rewardXP"] = 1415, ["rewardItems"] = { 124489 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 95, ["name"] = "Legion Mining", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 124489 } },
[38784] = { ["id"] = 38784, ["name"] = "Leystone Seam Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 38777, 38784, 38785, 38786, 38787, 38789, 38790, 38791, 38792, 38793, 38794, 38888 }, ["description"] = "This ore has clearly absorbed some of the latent ley energies within the Broken Isles. It is cool to the touch, and reflects light in odd, playful angles. Your trainer in Dalaran should analyze this.", ["objectivesText"] = "Bring the Leystone Seam Sample to Mama Diggs in Dalaran. Progress: What've ye brought me now?", ["rewardXP"] = 1415, ["rewardItems"] = { 124490 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 95, ["name"] = "Legion Mining", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 124490 } },
[38785] = { ["id"] = 38785, ["name"] = "Living Leystone Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 38777, 38784, 38785, 38786, 38787, 38789, 38790, 38791, 38792, 38793, 38794, 38888 }, ["description"] = "This is no normal leystone. It is much livelier, shimmering in complex, enthralling patterns. It is easy to stare at. Your trainer in Dalaran would certainly like to have a look at this.", ["objectivesText"] = "Bring the Living Leystone Sample to Mama Diggs in Dalaran. Progress: Oh, my...", ["rewardXP"] = 1415, ["rewardItems"] = { 124491 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 95, ["name"] = "Legion Mining", ["orderIndex"] = 2, ["flags"] = 0 } }, ["startItems"] = { 124491 } },
[38786] = { ["id"] = 38786, ["name"] = "Where Respect is Due", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38777, 38784, 38785, 38786, 38787, 38789, 38790, 38791, 38792, 38793, 38794, 38888 }, ["series"] = { 38787, 38888 }, ["description"] = "Leystone is a sensitive ore. Our smiths can coax great power out of it, but as miners, we must treat it with respect, or else its power will retreat inward. <The tauren hands you what appears to be a GLASS mining pick.> The next time you mine some leystone ore, use this pick. It will break if you strike too hard. THIS is the respect that leystone requires.", ["objectivesText"] = "Mine for leystone 35 times while using Ronos's Glass Pick. Progress: You haven't broken my pick, have you?", ["rewardXP"] = 1415, ["rewardItems"] = { 123918, 128767, 128769 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93691, ["x"] = 0.55, ["y"] = 0.84 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93691, ["x"] = 0.55, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 95, ["name"] = "Legion Mining", ["orderIndex"] = 4, ["flags"] = 0 } } },
[38787] = { ["id"] = 38787, ["name"] = "The Legend of Rethu Ironhorn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38777, 38784, 38785, 38786, 38787, 38789, 38790, 38791, 38792, 38793, 38794, 38888 }, ["series"] = { 38786, 38888 }, ["description"] = "A long, long time ago, a tauren by the name of Rethu entered this land. His exploits paved the road that all miners walk. If you wish to learn more about mining, you must first learn about Rethu.", ["objectivesText"] = "Speak with Ronos Ironhorn to learn the tale of Rethu Ironhorn. Progress: Listen well, <name>.", ["rewardXP"] = 1415, ["rewardItems"] = { 124492, 124493, 124494 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 93691, ["x"] = 0.55, ["y"] = 0.84 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93691, ["x"] = 0.55, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 95, ["name"] = "Legion Mining", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38789] = { ["id"] = 38789, ["name"] = "Rethu's Journal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38777, 38784, 38785, 38786, 38787, 38789, 38790, 38791, 38792, 38793, 38794, 38888 }, ["description"] = "Tucked in between a few pieces of rubble, a scrap of paper catches your eye. Mining carefully, you uncover the tattered remains of an old scroll. The tauren handwriting is archaic, but one word catches your eye: \"Rethu\".", ["objectivesText"] = "Bring the Torn Journal Page to Ronos Ironhorn in Highmountain. Progress: Greetings, miner. What have you here?", ["rewardXP"] = 1415, ["rewardItems"] = { 124492, 124493, 124494 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93691, ["x"] = 0.55, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 95, ["name"] = "Legion Mining", ["orderIndex"] = 6, ["flags"] = 0 } }, ["startItems"] = { 124492 } },
[38790] = { ["id"] = 38790, ["name"] = "Rethu's Pick", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38777, 38784, 38785, 38786, 38787, 38789, 38790, 38791, 38792, 38793, 38794, 38888 }, ["description"] = "This seam has been mined before - it bears the telltale diagonal ruts of a miner's pick. Looking down, that pick now lays on the ground - handle broken, pick-point dulled with use and years. Carved into the haft is a familiar name: \"Rethu\"", ["objectivesText"] = "Bring the Battered Mining Pick to Ronos Ironhorn in Highmountain. Progress: What is that you hold, miner?", ["rewardXP"] = 1415, ["rewardItems"] = { 124492, 124493, 124494 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93691, ["x"] = 0.55, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 95, ["name"] = "Legion Mining", ["orderIndex"] = 7, ["flags"] = 0 } }, ["startItems"] = { 124493 } },
[38791] = { ["id"] = 38791, ["name"] = "Rethu's Horn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38777, 38784, 38785, 38786, 38787, 38789, 38790, 38791, 38792, 38793, 38794, 38888 }, ["description"] = "The corpse of the rocky beast yielded an unusual treasure: a battered chunk of tauren's horn. It is clearly very, very old, but something about its color and curve reminds you of Ronos Ironhorn at the Ironhorn Enclave.", ["objectivesText"] = "Bring the Chunk of Horn to Ronos Ironhorn in Highmountain. Progress: What... what is that, miner?", ["rewardXP"] = 1415, ["rewardItems"] = { 124492, 124493, 124494 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93691, ["x"] = 0.55, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 95, ["name"] = "Legion Mining", ["orderIndex"] = 8, ["flags"] = 0 } }, ["startItems"] = { 124494 } },
[38792] = { ["id"] = 38792, ["name"] = "Rethu's Lesson", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 630, ["storyline"] = { 38777, 38784, 38785, 38786, 38787, 38789, 38790, 38791, 38792, 38793, 38794, 38888 }, ["description"] = "You... miner... let me see your pick a moment. <The tauren spirit eyes your mining equipment.> You remind me of myself, when I once walked this land. Savor these moments, miner. They cannot last forever. <With a bow, the spirit disappears.>", ["objectivesText"] = "Report your encounter to Ronos Ironhorn in Highmountain.", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93735, ["x"] = 0.487429, ["y"] = 0.539714 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93691, ["x"] = 0.55, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.487429, ["y"] = 0.539714 }, ["mapCandidates"] = { ["npc"] = { 630, 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 95, ["name"] = "Legion Mining", ["orderIndex"] = 9, ["flags"] = 0 } } },
[38793] = { ["id"] = 38793, ["name"] = "Rethu's Experience", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 630, ["storyline"] = { 38777, 38784, 38785, 38786, 38787, 38789, 38790, 38791, 38792, 38793, 38794, 38888 }, ["description"] = "Miner... you... you know who I am? I see. That is good. My tribe continues to honor its roots. If you return to the land of the Ironhorn tribe... let them know that they are looked upon with pride.", ["objectivesText"] = "Report your encounter to Ronos Ironhorn in Highmountain.", ["rewardXP"] = 1415, ["rewardItems"] = { 123918, 123919 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93743, ["x"] = 0.526667, ["y"] = 0.485333 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93691, ["x"] = 0.55, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.526667, ["y"] = 0.485333 }, ["mapCandidates"] = { ["npc"] = { 630, 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 95, ["name"] = "Legion Mining", ["orderIndex"] = 10, ["flags"] = 0 } } },
[38794] = { ["id"] = 38794, ["name"] = "Rethu's Sacrifice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 630, ["storyline"] = { 38777, 38784, 38785, 38786, 38787, 38789, 38790, 38791, 38792, 38793, 38794, 38888 }, ["description"] = "Miner... speak with me a moment. I haven't much time in this place. I see you fight for your ore. I believe that is the most noble way to obtain your stone. It gives the land a fighting chance. Still, one mustn't be callous with their own life. Dig too deep, and the land will overcome you. No stone is worth the price I paid. But that is a tale for another day...", ["objectivesText"] = "Report your encounter to Ronos Ironhorn in Highmountain.", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93744, ["x"] = 0.471692, ["y"] = 0.542462 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93691, ["x"] = 0.55, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.471692, ["y"] = 0.542462 }, ["mapCandidates"] = { ["npc"] = { 630, 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 95, ["name"] = "Legion Mining", ["orderIndex"] = 11, ["flags"] = 0 } } },
[38795] = { ["id"] = 38795, ["name"] = "Felslate Deposit Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 38795, 38796, 38797, 38798, 38799, 38800, 38801, 38802, 38803, 38804, 38805, 38901 }, ["description"] = "This is one nasty-looking stone. Your trainer in Dalaran should see this.", ["objectivesText"] = "Bring the Felslate Deposit Sample to Mama Diggs in Dalaran. Progress: You bring me somethin' new?", ["rewardXP"] = 1415, ["rewardItems"] = { 124496 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 249, ["name"] = "Legion Mining", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 124496 } },
[38796] = { ["id"] = 38796, ["name"] = "Felslate Seam Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 38795, 38796, 38797, 38798, 38799, 38800, 38801, 38802, 38803, 38804, 38805, 38901 }, ["description"] = "This ore is remarkably heavy. More disturbingly, it seems to darken and hiss at your touch. Perhaps your mining trainer in Dalaran has some insights.", ["objectivesText"] = "Bring the Felslate Seam Sample to Mama Diggs in Dalaran. Progress: Looks like you've been busy down there, miner.", ["rewardXP"] = 1415, ["rewardItems"] = { 124497 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 249, ["name"] = "Legion Mining", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 124497 } },
[38797] = { ["id"] = 38797, ["name"] = "Living Felslate Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 680, ["storyline"] = { 38795, 38796, 38797, 38798, 38799, 38800, 38801, 38802, 38803, 38804, 38805, 38901 }, ["description"] = "Your miner's instinct is kicking in. Chunks of the infernal's corpse appear to be usable. Still, there must be a way to extract more ore from the demon's body. Perhaps your mining trainer in Dalaran will know how.", ["objectivesText"] = "Bring the Living Felslate Sample to Mama Diggs in Dalaran. Progress: What's that?", ["rewardXP"] = 1415, ["rewardItems"] = { 124498 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 249, ["name"] = "Legion Mining", ["orderIndex"] = 2, ["flags"] = 0 } }, ["startItems"] = { 124498 } },
[38798] = { ["id"] = 38798, ["name"] = "A Shred of Your Humanity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38795, 38796, 38797, 38798, 38799, 38800, 38801, 38802, 38803, 38804, 38805, 38901 }, ["series"] = { 38901 }, ["description"] = "To mine for felslate is to seek the very blood of demons. To improve at it, you must become part demon yourself. Why the dirty look? You said it yourself: you're willing to make sacrifices. Luckily for you, I'm an expert in this area. I won't put you in any danger, as long as you trust me. Are you ready?", ["objectivesText"] = "Allow Felsmith Nal'ryssa to place three shards of felslate in your body. Progress: Don't waste my time, miner.", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.299, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 249, ["name"] = "Legion Mining", ["orderIndex"] = 4, ["flags"] = 0 } } },
[38799] = { ["id"] = 38799, ["name"] = "Darkheart Thicket: Nal'ryssa's Sisters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38795, 38796, 38797, 38798, 38799, 38800, 38801, 38802, 38803, 38804, 38805, 38901 }, ["description"] = "I was not the only miner in my family. I was the youngest of four sisters. I say \"was\" because the other three are gone. Two of them went too far. They overloaded their bodies with felslate and succumbed to the will of Sargeras. They are more demon than elf, now. The third, I have not heard from in quite some time. The last I heard, she was investigating the Darkheart Thicket. I fear she may have fallen, too - one way or the other.", ["objectivesText"] = "Go to the Darkheart Thicket and find Lyrelle's Signet Ring . Progress: Any sign of my sister?", ["rewardXP"] = 1415, ["rewardItems"] = { 124499, 124500, 124501, 126940, 126947 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.299, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 249, ["name"] = "Legion Mining", ["orderIndex"] = 5, ["flags"] = 0 } } },
[38800] = { ["id"] = 38800, ["name"] = "Rin'thissa's Eye", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38795, 38796, 38797, 38798, 38799, 38800, 38801, 38802, 38803, 38804, 38805, 38901 }, ["description"] = "Oddly enveloped within the felslate deposit is a humanoid eye. It quivers with life. You get the sense that it would blink at you if it had an eyelid. A mining expert should take a look at this.", ["objectivesText"] = "Bring the Ore-Bound Eye to Felsmith Nal'ryssa in Suramar. Progress: Is... is that...?", ["rewardXP"] = 1415, ["rewardItems"] = { 124499, 124500, 124501 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.299, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 249, ["name"] = "Legion Mining", ["orderIndex"] = 6, ["flags"] = 0 } }, ["startItems"] = { 124499 } },
[38801] = { ["id"] = 38801, ["name"] = "Lyrelle's Right Arm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38795, 38796, 38797, 38798, 38799, 38800, 38801, 38802, 38803, 38804, 38805, 38901 }, ["description"] = "You blink and rub your eyes, but they do not deceive you. This is a woman's arm, completely enveloped within a felslate seam. The arm is bloodless, but still twitches. Fel-colored streaks remain where veins once were. Felsmith Nal'ryssa will certainly want to see this.", ["objectivesText"] = "Bring the Severed Arm to Felsmith Nal'ryssa in Suramar. Progress: Lyrelle, no...", ["rewardXP"] = 1415, ["rewardItems"] = { 124499, 124500, 124501 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.299, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 249, ["name"] = "Legion Mining", ["orderIndex"] = 7, ["flags"] = 0 } }, ["startItems"] = { 124500 } },
[38802] = { ["id"] = 38802, ["name"] = "Ondri's Still-Beating Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38795, 38796, 38797, 38798, 38799, 38800, 38801, 38802, 38803, 38804, 38805, 38901 }, ["description"] = "What at first looked like another chunk of felslate is, in fact, a humanoid heart, encrusted in rock and filled not with blood but a vile, demonic substance. It does not appear to belong to the beast you carved it out of... it seems that the infernal was holding it like a keepsake. Luckily your mining pick didn't hit it straight on. Felsmith Nal'ryssa will want to see this.", ["objectivesText"] = "Bring the Ore-Choked Heart to Felsmith Nal'ryssa in Suramar. Progress: Ondri...", ["rewardXP"] = 1415, ["rewardItems"] = { 124499, 124500, 124501 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.299, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 249, ["name"] = "Legion Mining", ["orderIndex"] = 8, ["flags"] = 0 } }, ["startItems"] = { 124501 } },
[38803] = { ["id"] = 38803, ["name"] = "Rin'thissa", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 38795, 38796, 38797, 38798, 38799, 38800, 38801, 38802, 38803, 38804, 38805, 38901 }, ["description"] = "My sister Nal'ryssa has her claws in you, doesn't she? That weakling doesn't know the first thing about mining. She was always too afraid to take the leap. True knowledge comes only from the Great One, the God of Fel and Flame. You want to truly learn how to mine? Come to Suramar's northwestern corner, and speak my name: Rin'thissa .", ["objectivesText"] = "Summon and defeat Rin'thissa .", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93774, ["x"] = 0.509385, ["y"] = 0.397538 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.509385, ["y"] = 0.397538 }, ["mapCandidates"] = { ["npc"] = { 630, 680 }, ["zone"] = { 7637 } }, ["questType"] = "group", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 249, ["name"] = "Legion Mining", ["orderIndex"] = 9, ["flags"] = 0 } } },
[38804] = { ["id"] = 38804, ["name"] = "Lyrelle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 646, ["storyline"] = { 38795, 38796, 38797, 38798, 38799, 38800, 38801, 38802, 38803, 38804, 38805, 38901 }, ["description"] = "Look at you, miner. Still held back by the limitations of your fragile, decaying flesh. To truly become one with the demon-tinged rocks of these lands, you must shed your skin and submit to a darker power. Join us, miner. Bring your feeble body to Felsoul Hold, and speak my name: Lyrelle .", ["objectivesText"] = "Summon and defeat Lyrelle .", ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 93776, ["x"] = 0.680667, ["y"] = 0.343333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.680667, ["y"] = 0.343333 }, ["mapCandidates"] = { ["npc"] = { 646, 680 }, ["zone"] = { 7637 } }, ["questType"] = "group", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 249, ["name"] = "Legion Mining", ["orderIndex"] = 10, ["flags"] = 0 } } },
[38805] = { ["id"] = 38805, ["name"] = "Ondri", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 646, ["storyline"] = { 38795, 38796, 38797, 38798, 38799, 38800, 38801, 38802, 38803, 38804, 38805, 38901 }, ["description"] = "You are nothing compared to me. You think yourself hardened, experienced... heroic, even. Hah! You have no idea what I've been through. The tortures I've endured, the sacrifices I've made. All for the sake of my trade! Yes, I'm a miner, just like you. Want to learn what I have to teach? Come to the Crimson Thicket in Suramar, and speak my name: Ondri .", ["objectivesText"] = "Summon and defeat Ondri . Progress: Ondri has always heartless, one way or the other.", ["rewardXP"] = 1415, ["rewardItems"] = { 151564 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 93777, ["x"] = 0.484778, ["y"] = 0.380667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.484778, ["y"] = 0.380667 }, ["mapCandidates"] = { ["npc"] = { 646, 680 }, ["zone"] = { 7637 } }, ["questType"] = "group", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 249, ["name"] = "Legion Mining", ["orderIndex"] = 11, ["flags"] = 0 } } },
[38806] = { ["id"] = 38806, ["name"] = "Infernal Brimstone Sample", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 38806, 38807, 39763, 39790, 39817, 39830 }, ["description"] = "This ore. Smells. Horrible. It combines the odor of sulfur with all the worst parts of a rotting corpse. Someone will probably want it for something. Maybe your mining trainer in Dalaran will take it off of your hands.", ["objectivesText"] = "Bring the Infernal Brimstone Sample to Mama Diggs in Dalaran. Progress: Excuse me, I must have... wait, that smell is coming from YOU?", ["rewardXP"] = 6140, ["rewardItems"] = { 124502 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 250, ["name"] = "Legion Mining", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 124502 } },
[38839] = { ["id"] = 38839, ["name"] = "Done with Waiting", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 38839 }, ["series"] = { 38840 }, ["description"] = "Mom got a message and said blood called for blood. She told me to wait here while she went out, but it's been two weeks since then. I'm tired of waiting. I'll stay home if you go find her. She said she was going to the cliffs far to the south.", ["objectivesText"] = "Travel to the southern cliffs of Val'sharah and speak to Makra Knifewhisper.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[38840] = { ["id"] = 38840, ["name"] = "Fishy Business", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 38840 }, ["series"] = { 38839 }, ["description"] = "Makrura are massing down by the shore, and far too many of them seem to practice water magic. I think once they've got enough spellcasters, they're planning to summon a massive wave.", ["objectivesText"] = "Kill 3 Murktide Wavecallers on the southern coast of Val'sharah .", ["rewardGold"] = 194000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[38856] = { ["id"] = 38856, ["name"] = "Holy Retribution", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 38856 }, ["description"] = "I fell in what you now call Tirisfal Glades at the claws of two of Yogg'Saron's most powerful lieutenants... the C'Thraxi. I was able to slay one in my death throes - Az'jtal . Now, the dark forces deep beneath Azeroth have begun to usher Az'jtal once again into this world. You must go to Tyr's Fall and strike Az'jtal down again before it can fully manifest. Only once this deed is done may you receive my blessing upon the Ashbringer.", ["objectivesText"] = "Strike down Az'jtal at Tyr's Fall in Tirisfal Glades.", ["rewardGold"] = 462000, ["rewardXP"] = 300, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[38888] = { ["id"] = 38888, ["name"] = "The Highmountain Tauren", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 38777, 38784, 38785, 38786, 38787, 38789, 38790, 38791, 38792, 38793, 38794, 38888 }, ["series"] = { 38786, 38787 }, ["description"] = "Ye've brought me a bit of interesting rocks to look at, <name>. I've got a special assignment for ye, if ye're up for it. I hear stories about these tauren, up in Highmountain, who claim mastery over minin'. I don't know if they're as talented as you or me, but they've been minin' leystone longer. Pay 'em a visit. See what they have to say.", ["objectivesText"] = "Report to Ronos Ironhorn in Highmountain.", ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 93691, ["x"] = 0.55, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 95, ["name"] = "Legion Mining", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38889] = { ["id"] = 38889, ["name"] = "Adopting the Adorable", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38889 }, ["rewardGold"] = 29325, ["rewardXP"] = 355, ["rewardItems"] = { 128690, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 93677, ["x"] = 0.528, ["y"] = 0.875 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 93677, ["x"] = 0.528, ["y"] = 0.875 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.875 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2VignetteID"] = 886, ["db2VignetteName"] = "Shivering Ashmaw Cub" },
[38901] = { ["id"] = 38901, ["name"] = "The Felsmiths", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 680, ["storyline"] = { 38795, 38796, 38797, 38798, 38799, 38800, 38801, 38802, 38803, 38804, 38805, 38901 }, ["series"] = { 38798 }, ["description"] = "Ye have a knack with this felslate, <lad/lass>. Best ship ye off to someone who knows the stuff better than I. The Illidari have a knack with all things demonic, really, and I've heard about a few miners who've set up shop out near the demons in Suramar. Pay 'em a visit. See what they have to teach ye.", ["objectivesText"] = "Report to Felsmith Nal'ryssa in Suramar.", ["rewardXP"] = 175, ["rewardItems"] = { 109076 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.299, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 685, ["questLines"] = { { ["id"] = 249, ["name"] = "Legion Mining", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38914] = { ["id"] = 38914, ["name"] = "Secrets of Highmountain", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 38914 }, ["description"] = "Now that you are familiar with our greatest hero, perhaps you are willing to assist me on a very dangerous endeavor. To this end I have sent word for one of your allies to join us. When you are ready, join us in my spirit lodge. It is up the elevators and across the southwestern most bridge.", ["objectivesText"] = "Speak with Spiritwalker Ebonhorn in Thunder totem.", ["rewardGold"] = 17000, ["rewardXP"] = 25, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[38938] = { ["id"] = 38938, ["name"] = "Unbearable", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["storyline"] = { 38938 }, ["series"] = { 38885 }, ["description"] = "Not far away, a bear cub looks to be in some distress. Perhaps you should investigate?", ["objectivesText"] = "Investigate the Shivering Ashmaw Cub in southern Val'sharah .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard" },
