[39011] = { ["id"] = 39011, ["name"] = "Black Rook Invasion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["storyline"] = { 39011 }, ["description"] = "Once, this area was peaceful and prosperous. Then we saw the first bad omens: strange ailments, spoiled crops, and the like. Now ghosts attack us from that castle across the river, and undead assassins slay our fishers so as to cut off the village's food supply. We're the last family living this close to the castle, but we daren't retreat: this river is the best route for fishers to bring their hauls in to town. Please, will you take the fight to these undead?", ["objectivesText"] = "Kill 7 Black Rook Assassins in Bradensbrook.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard" },
[39017] = { ["id"] = 39017, ["name"] = "Rise to the Occasion", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["storyline"] = { 39017 }, ["description"] = "The Lich King made a wise choice in giving you that weapon, <name>. You've proven your strength and cunning on countless occasions and it is time that you have a position fitting for your accomplishments.", ["objectivesText"] = "Speak with Highlord Darion Mograine within Acherus.", ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard" },
