[39032] = { ["id"] = 39032, ["name"] = "A Summons from Saylanna", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 39032 }, ["description"] = "Sprites have always been mischievous creatures, but lately their mischief has turned to violence. One of the druids I call friend, Saylanna Riverbreeze, reports that they are assaulting the faerie dragon nesting grounds. The Lunarwing Shallows lie to the south. You will find Saylanna there.", ["objectivesText"] = "Seek out Saylanna Riverbreeze in the Lunarwing Shallows.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
