[39125] = { ["id"] = 39125, ["name"] = "Demon Destroyer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 39125 }, ["description"] = "The demons spreading this corruption must be dealt with. Kill their generals and their plans will unravel. I have a gift for you. This horn was given to me by Odyn himself, use it to strike down all that stand in your way. The gods will surely smile upon you if you thwart the advances of Legion.", ["objectivesText"] = "Slay Doomcaller , Sneermaw , and Grinchain", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 128305 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
