[39133] = { ["id"] = 39133, ["name"] = "No Time to Talk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39133, 39134 }, ["description"] = "Dargrul has sent his pets to do battle with us. We need to crush these elementals before their rage swarms into Thunder Totem.", ["objectivesText"] = "Destroy 8 Enraged Ambershard . Progress: We will all be honorary masons if this keeps up much longer.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94561, ["x"] = 0.49, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94561, ["x"] = 0.49, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5916, ["name"] = "Crystal Calamity", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39134] = { ["id"] = 39134, ["name"] = "Wrathshard", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39133, 39134 }, ["description"] = "The Underking has used the Hammer of Khaz'goroth to render the mountainside into a weapon against us. The hammer is a tool for creation, not a weapon for his amusement! Even now, his crystal servant, Wrathshard , is driving these elementals out of the mountain down upon my people. We must hold the bridge against this onslaught. Enter the cave, find Wrathshard , and send him back to his master in pieces.", ["objectivesText"] = "Slay Wrathshard . Progress: Dargrul always was a vile creature. I never realized to what extent until he got his hands on that hammer.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 121677, 121678, 121679, 121680, 130299, 130300, 130301, 130302, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94561, ["x"] = 0.49, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94561, ["x"] = 0.49, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5916, ["name"] = "Crystal Calamity", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39138] = { ["id"] = 39138, ["name"] = "March Forth and Conquer", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 39138 }, ["description"] = "You should make sure that we do not lose momentum, Highlord. There is still much to be done in Azsuna. We have a map of the island set up near the front of the sanctum. Meet me there and you can delegate your forces to handle important tasks in the area.", ["objectivesText"] = "Use the Command Map to send your followers on three missions to Azsuna.", ["rewardGold"] = 15400, ["rewardXP"] = 25, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[39151] = { ["id"] = 39151, ["name"] = "Forging the Artifact", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 39151 }, ["description"] = "We've certainly got our work cut out for us, but not to worry. There's nae weapon in existence that ye can't improve, legendary ones included! This anvil's only powerful enough to imbue your artifact once before we'll need something better, but that'll have to do fer now.", ["objectivesText"] = "Use Valgar's anvil to imbue your artifact with a new power.", ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[39190] = { ["id"] = 39190, ["name"] = "DEPRECATED", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 39190 }, ["description"] = "The Knights of the Ebon Blade are ready. Place your hand upon the Orb of Command and Acherus will move to its new resting place. We await your orders, Highlord.", ["objectivesText"] = "Christen the Order of the Silver Hand using the Libram of the Order in Light's Hope Sanctum.", ["rewardGold"] = 462000, ["rewardXP"] = 300, ["rewardItems"] = { 94219, 128823, 128868, 209353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
