[39305] = { ["id"] = 39305, ["name"] = "Empty Nest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39305, 40069, 40070, 40071, 42425 }, ["description"] = "I've taken an inventory of the eggs you recovered. Some among the bunch may still have a chance to hatch. They will need to be returned to an empty nest, and with any luck, an eagle will claim the eggs as her own and watch over them once again. There is a nest just outside the entrance, on a rocky ledge above the cave. Be careful, <name>. The eggs are very delicate.", ["objectivesText"] = "Place the eagle eggs in the empty nest above the eastern entrance to Rockcrawler Chasm. Progress: If there's any hope for those eggs hatching, they'll need to be returned to their nest.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 128757, 129277, 141605, 237812, 257723 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5923, ["name"] = "Rockcrawler Chasm", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39323] = { ["id"] = 39323, ["name"] = "Moozy's Sojourn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39323, 39572, 42590 }, ["series"] = { 39572 }, ["description"] = "My son! They took him! My wife and I split up to look for him. She went upriver and I went downriver. Leave me, please, and find Moozy... I might be okay... If you find Moozy, please bring him to my wife upriver.", ["objectivesText"] = "Find Moozy downriver in Whitewater Wash.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96083, ["x"] = 0.402, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5914, ["name"] = "Moozy's Family Reunion", ["orderIndex"] = 0, ["flags"] = 0 } } },
