[39354] = { ["id"] = 39354, ["name"] = "Wisp in the Willows", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 39354 }, ["description"] = "Wisps are the spirits of our night elven brethren who have become one with the forest. But their minds and the way they perceive things are very different than in life. You should bond with this little one. See through its eyes as it travels to the hidden pools and grows some trees.", ["objectivesText"] = "Guide the Wisp through the Hidden Pools to grow 8 trees. Progress: Any luck?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 130127, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 95202, ["x"] = 0.542, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 95202, ["x"] = 0.542, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["db2VignetteID"] = 966, ["db2VignetteName"] = "Syndrelle", ["questLines"] = { { ["id"] = 5765, ["name"] = "Wisp in the Willows", ["orderIndex"] = 0, ["flags"] = 0 } } },
