[39388] = { ["id"] = 39388, ["name"] = "Moonclaw's Wisdom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["storyline"] = { 39388 }, ["description"] = "Our quick action today has stopped this aggression and saved my valley. As you requested, I will join Malfurion in the Grove of Cenarius. Still, there is much about these satyrs that I wish to tell you. This information would be most valuable to you. Please meet me in my den before departing.", ["objectivesText"] = "Meet Thaon Moonclaw in his den.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard" },
[39419] = { ["id"] = 39419, ["name"] = "Hex-a-Gone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39419 }, ["description"] = "The harpies are relentless in their pursuit to control the basin. They are able to craft bags of foul magic as quickly as we can destroy them. The Skyhorn cannot gain the upper hand as long as their hexweaver lives. She must be stopped.", ["objectivesText"] = "Slay Hexweaver Akara . Progress: Hexweaver Akara must be slain if the Skyhorn wish to gain the upper hand.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94522, ["x"] = 0.472, ["y"] = 0.48 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94522, ["x"] = 0.472, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard" },
