[39566] = { ["id"] = 39566, ["name"] = "The Search for Knowledge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39327, 39328, 39329, 39330, 39390 }, ["description"] = "While you were out gallivanting, did you notice any lost relics around Azsuna? My sources tell me there are treasures to be found. These rumors merit investigation!", ["objectivesText"] = "Look for ancient relics on the shoreline of Azsuna.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 3, ["flags"] = 0 } } },
