[39606] = { ["id"] = 39606, ["name"] = "Treasures of Deathwing", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 39606 }, ["description"] = "Neltharion's Vault? Well why didn't that spiritwalker just say so? When we were jumpin' into the cavern I thought I saw a chamber up high that might have what we are after. Have a look around this place while I see if I can't find a way up.", ["objectivesText"] = "Defend Brann Bronzebeard.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2VignetteID"] = 1413, ["db2VignetteName"] = "Treasures of Deathwing" },
[39692] = { ["id"] = 39692, ["name"] = "The Call of War", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 39692 }, ["description"] = "The Warchief Vol'jin is expecting you. Enter Grommash Hold straight ahead, and make your introduction.", ["objectivesText"] = "Speak to the Warchief.", ["rewardGold"] = 98700, ["rewardXP"] = 1720, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[39763] = { ["id"] = 39763, ["name"] = "For Whom the Fel Tolls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredRaces"] = { 3, 9, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38806, 38807, 39763, 39790, 39817, 39830 }, ["series"] = { 38807, 39790, 39817, 39830 }, ["description"] = "<Matthew eyes you up and down, growling slightly> You wish me to help you understand this rock? First you do something for me. The legion has brought many of its fel machines to conquer this world. Those machines are powered by cores filled with fel energy. And those cores are carried by the lowliest of their minions for distribution. Bring me some cores and I'll give you the information you need.", ["objectivesText"] = "Obtain 10 Fel Energy Cores from Wyrmtongue Minions in Suramar. Bring them back to Matthew in Dalaran when you are finished. Progress: Have you acquired what I requested?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 128813 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 250, ["name"] = "Legion Mining", ["orderIndex"] = 3, ["flags"] = 0 } } },
[39764] = { ["id"] = 39764, ["name"] = "Shiny, But Deadly", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 654, ["storyline"] = { 39764, 39773, 39774 }, ["description"] = "Soulkeeper Uriah and I were transporting demon prisoners to Allari in Azsuna when our caravan was attacked by kobolds. Those mindless vermin made off with the soul chambers that house our demonic captives. The crystals may be shiny, but they're also deadly. If they are damaged in any way, the demons trapped within may escape. Head into the cave nearby and recover the soul chambers before it's too late.", ["objectivesText"] = "Collect Soul Chambers from kobolds within Mucksnout Den. Progress: Have you recovered the soul chambers yet?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128752, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 654, ["questLines"] = { { ["id"] = 5922, ["name"] = "Mucksnout Den", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39765] = { ["id"] = 39765, ["name"] = "Wax On, Wax Off", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39765, 39768, 39769, 39772, 40339, 40345 }, ["series"] = { 39768, 39769 }, ["description"] = "I've been dead for centuries without having my grave so disturbed... The leader of the local kobolds has stolen my skull from my grave and wears it upon his head! He's down in the cave below, but a gate blocks your path from retrieving it directly. Kobolds know their leadership by the skulls they wear, and they are unintelligent enough to believe you their leader if you have one yourself. Kill one of their Skullcaptains and recover his Skull of Bossing Around , and they may let you into the cave.", ["objectivesText"] = "Recover the Skull of Bossing Around from the Bluewax Skullcaptain. Progress: The desecration...", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128753, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96984, ["x"] = 0.546, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96984, ["x"] = 0.546, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5921, ["name"] = "Bluewax Boss", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39768] = { ["id"] = 39768, ["name"] = "Candle to the Grave", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39765, 39768, 39769, 39772, 40339, 40345 }, ["series"] = { 39765, 39769 }, ["description"] = "These kobolds are taking advantage of the attacks against the Skyhorn tribe. They disturb our graves and steal anything they can get their paws on. I can do nothing to stop them! Please rid this sacred burial ground of the kobold.", ["objectivesText"] = "Slay 7 Bluewax Graverobbers .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96984, ["x"] = 0.546, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96984, ["x"] = 0.546, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5921, ["name"] = "Bluewax Boss", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39769] = { ["id"] = 39769, ["name"] = "The Gates of Wax", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39765, 39768, 39769, 39772, 40339, 40345 }, ["series"] = { 39765, 39768 }, ["description"] = "Go talk to the Bluewax Gatekeeper and see if he will let you through to the Candleking. If you can get through by donning the skull, the smell will be worth it.", ["objectivesText"] = "Speak with the Bluewax Gatekeeper and see if he will let you in to meet the Candleking.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96984, ["x"] = 0.546, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 97130, ["x"] = 0.552, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5921, ["name"] = "Bluewax Boss", ["orderIndex"] = 2, ["flags"] = 0 } } },
[39772] = { ["id"] = 39772, ["name"] = "Can't Hold a Candle To You", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39765, 39768, 39769, 39772, 40339, 40345 }, ["series"] = { 39770, 40339, 40345 }, ["description"] = "Okay guess you can go say hi to Candleking now.", ["objectivesText"] = "Recover Oenia's Skull from the Candleking. Progress: Have you found my skull?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128756, 130275, 130283, 130284, 130285, 130286, 237812, 260698 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 97130, ["x"] = 0.552, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96984, ["x"] = 0.546, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5921, ["name"] = "Bluewax Boss", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39773] = { ["id"] = 39773, ["name"] = "The Soulkeeper's Fate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 654, ["storyline"] = { 39764, 39773, 39774 }, ["description"] = "Soulkeeper Uriah was injured in the kobold attack, but insisted on venturing further into the cave to recover the stolen soul shards. He told me to wait here with our remaining supplies until he returned, but I fear the worst. Please find Uriah. He is the only one who knows how to trap the demons.", ["objectivesText"] = "Find Soulkeeper Uriah within Mucksnout Den.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 654, ["questLines"] = { { ["id"] = 5922, ["name"] = "Mucksnout Den", ["orderIndex"] = 1, ["flags"] = 0 } } },
[39774] = { ["id"] = 39774, ["name"] = "Demon Detainment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39764, 39773, 39774 }, ["description"] = "The demons that escaped must be detained. Killing them is not an option. Uriah was entrusted to deliver the prisoners to Allari for interrogation, and I will not let him fail. I've seen Uriah trap many demons. It seems... complicated, but I think I can pull it off. I'll just need you to subdue them first.", ["objectivesText"] = "Weaken demons so Apprentice Rosalyn can trap them within a soul chamber. Progress: You must weaken the demons so I am able to trap them.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132087, 132088, 132089, 132090, 132091, 132092, 132093, 137663, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5922, ["name"] = "Mucksnout Den", ["orderIndex"] = 2, ["flags"] = 0 } } },
