[39790] = { ["id"] = 39790, ["name"] = "Infernal Brimstone Theory", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredRaces"] = { 2, 3, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38806, 38807, 39763, 39790, 39817, 39830 }, ["series"] = { 38807, 39763, 39817, 39830 }, ["description"] = "I've gone through all the research ye gathered for me and I've come up with a theory. As we know, the ore in this world develops over time, through pressure and environmental changes. But the Infernal Brimstone ye gave me had its growth accelerated through demonic magic, much like the saronite of Icecrown. If we're wantin' to test this out, we'll have to get the help of some magic-users. Take this brimstone back and go see Matthew Rabis . He may know how to breathe life into it.", ["objectivesText"] = "Take the brimstone sample to Matthew Rabis in the Underbelly. Provided item:", ["rewardGold"] = 221280, ["rewardXP"] = 6140, ["rewardItems"] = { 128852 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 250, ["name"] = "Legion Mining", ["orderIndex"] = 2, ["flags"] = 0 } } },
