[39817] = { ["id"] = 39817, ["name"] = "The Brimstone's Secret", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38806, 38807, 39763, 39790, 39817, 39830 }, ["series"] = { 38807, 39763, 39790, 39830 }, ["description"] = "While you were gathering what I asked of you, I did a little testing on the brimstone. It reacted rather violently when I channeled onto it. Careful casting went into making the creature from whom you took this. Unless you have a host of demon spell-casters at your disposal, recreating such a creature would be impossible. That's all I have to tell you. Go now and leave me before my hunger takes over.", ["objectivesText"] = "Tell Mama Diggs what you learned from Matthew.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 250, ["name"] = "Legion Mining", ["orderIndex"] = 4, ["flags"] = 0 } } },
[39936] = { ["id"] = 39936, ["name"] = "Inscription of the Body", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39937, 39938, 39940, 39941, 39943, 40058, 40059, 40060, 40063 }, ["description"] = "We demon hunters must keep our darkness at bay, lest we succumb to it and become demons ourselves. That is the purpose of marking our skin the way we do. Up to the north, a demon hunter by the name of Baric Stormrunner is preparing to strengthen his markings. Go to him and learn how we keep our demons at bay.", ["objectivesText"] = "Find Baric Stormrunner near the Ley-Ruins of Zarkhenar.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 97736, ["x"] = 0.54, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 6, ["flags"] = 0 } } },
[39938] = { ["id"] = 39938, ["name"] = "Containing the Demon Within", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39936, 39937, 39940, 39941, 39943, 40058, 40059, 40060, 40063 }, ["description"] = "Now that we have all the essential pieces, let's begin the ritual. I'll instruct you on how to help me. It is pivotal that you follow my instructions when I give them, or the ritual will fail.", ["objectivesText"] = "Assist Baric in completing the ritual.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 97736, ["x"] = 0.54, ["y"] = 0.154 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98026, ["x"] = 0.54, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.154 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 8, ["flags"] = 0 } } },
[39939] = { ["id"] = 39939, ["name"] = "Scribal Knowledge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["description"] = "We do not simply fight the demons, <name>. We observe them. One of my best demon hunters, Zaria Shadowheart , is currently gathering intel on the demons in Felblaze Ingress. Go to her. She will teach you what she has learned from the demons invading that region.", ["objectivesText"] = "Find Zaria Shadowheart near the Felblaze Ingress in Azsuna.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 89398, ["x"] = 0.432, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 97734, ["x"] = 0.65, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 9, ["flags"] = 0 } } },
[39941] = { ["id"] = 39941, ["name"] = "Control is Key", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39936, 39937, 39938, 39940, 39943, 40058, 40059, 40060, 40063 }, ["description"] = "We demon hunters ritualistically remove our eyes in order to see the demons more clearly. Down below, a demon commander walks amongst his troops, unseen by normal eyes. He keeps the chaos in order, as we must keep our chaos in check. Destroy his warding crystal, then slay him.", ["objectivesText"] = "Destroy the crystal protecting Overseer Felorax , then slay him.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 97734, ["x"] = 0.65, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 97734, ["x"] = 0.65, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 11, ["flags"] = 0 } } },
