[39952] = { ["id"] = 39952, ["name"] = "Sallow Essence", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["description"] = "<The felwort is reduced to a thick, clotted pigment. While all felwort-begotten pigment is somewhat offensive, this batch practically glows with a malevolent energy.> < Professor Pallin would be interested in seeing this.>", ["objectivesText"] = "Bring the Sallow Essence to Professor Pallin in Dalaran. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124101, 124102, 124103, 124104, 124105, 124106, 129032, 129034, 136909, 136912, 136915, 136916, 136917, 136918 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 39, ["flags"] = 0 } }, ["startItems"] = { 136918 } },
[39959] = { ["id"] = 39959, ["name"] = "The Plot Thickens", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 90, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39960 }, ["description"] = "Very well, I won't deny it. The Steamy Romance Novel is mine. I only read it for the penmanship, I assure you! He writes such curvy \"B\"s... and such ample \"D\"s! In fact... you might benefit from a penmanship lesson. The author of these books is one F. Serbacon. I believe he can be found in the library in Undercity. Stop reading, student. You are dismissed. And give me my book back!", ["objectivesText"] = "Go to the Undercity and look for F. Serbacon.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129032, 129034 }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 97766, ["x"] = 0.7755, ["y"] = 0.3845 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.7755, ["y"] = 0.3845 }, ["mapCandidates"] = { ["npc"] = { 90 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 90, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 30, ["flags"] = 0 } } },
[39960] = { ["id"] = 39960, ["name"] = "The Legacy Passed On", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1497, ["mapID"] = 90, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39959 }, ["description"] = "I've lost my passion, scribe. I just can't find the voice of my characters anymore. Take a look at that unfinished book over there on the table. I can't seem to finish it. Maybe you'll have an easier time with it.", ["objectivesText"] = "Complete the Unfinished Steamy Romance Novel. Progress: Confound this accursed writer's block!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 108649, 129032, 129034, 129211 }, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 97766, ["x"] = 0.7755, ["y"] = 0.3845 } }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 97766, ["x"] = 0.7755, ["y"] = 0.3845 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.7755, ["y"] = 0.3845 }, ["mapCandidates"] = { ["npc"] = { 90 }, ["zone"] = { 1497 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 90, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 32, ["flags"] = 0 } } },
[39962] = { ["id"] = 39962, ["name"] = "Trouble for Okuna", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 39962 }, ["description"] = "<You open the bottle and find a message inside.> Help! I need somebody... but not just anybody. I need a champion! I finally escaped the grasp of Prince Oceanus only to be hunted by his father, King Deepbeard. I was enjoying my freedom and decided to go fishing when that giant attacked. I've been running around these islands trying to avoid that creature ever since... if anyone gets this message, please send help!", ["objectivesText"] = "Search for Okuna Longtusk.", ["rewardGold"] = 1213200, ["rewardXP"] = 2830, ["rewardItems"] = { 129054 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "dungeon" },
[39969] = { ["id"] = 39969, ["name"] = "Kill Azshara", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8040, ["storyline"] = { 39969 }, ["description"] = "xxxxx", ["objectivesText"] = "xxxxx", ["rewardGold"] = 1164000, ["rewardXP"] = 400, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8040 } }, ["questType"] = "standard" },
[39984] = { ["id"] = 39984, ["name"] = "Remnants of the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39984, 40044, 40046, 43595, 43596 }, ["description"] = "<The journal entry appears hastily written.> I do not know what has become of my village. Ever since the mists engulfed the harbor, my kinsfolk have changed. Some have grown violent and savage, while others have fallen into madness. Many have ventured into the mists and have yet to return. In these times, we can usually turn to our leader, Jarl Tarben. Alas, the mists have taken him as well. I do not know what will become of me. For now, I can only stay at my post and remain vigilant.", ["objectivesText"] = "Locate clues to discover the fate of Tideskorn Harbor.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97973, ["x"] = 0.59, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5924, ["name"] = "The Fate of Tideskorn Harbor", ["orderIndex"] = 0, ["flags"] = 0 } } },
[39989] = { ["id"] = 39989, ["name"] = "Keepers of the Hammer", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 39989 }, ["description"] = "High Chieftain Ulan has requested your presence. We have learned that the Burning Legion has returned and know that if you are true in your purpose in facing this evil, you will need our aid. Our people have in our possession a great titan relic: the Hammer of Khaz'goroth. We intend to lend it to you for this task. When you are ready, join me at our stronghold of Thunder Totem in Highmountain .", ["objectivesText"] = "Meet the High-Chieftain at Thunder Totem in Highmountain .", ["rewardGold"] = 17000, ["rewardXP"] = 25, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[39991] = { ["id"] = 39991, ["name"] = "Blessing of Cenarius", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 39991 }, ["series"] = { 39983, 39988, 39990, 39992, 40112, 40167, 40388, 40515, 40520 }, ["description"] = "Cenarius himself has risked much in coming here, if only briefly, to bestow a blessing upon you. He has seen what you are capable of, and has chosen you as champion in this battle. Speak with him in the grove to the south.", ["objectivesText"] = "Meet with Cenarius.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[39998] = { ["id"] = 39998, ["name"] = "Drive Back the Tideskorn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39998 }, ["objectivesText"] = "Drive Back the Tideskorn", ["rewardGold"] = 404400, ["rewardXP"] = 1415, ["rewardItems"] = { 122612 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Drive Back the Tideskorn", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634 },
[40013] = { ["id"] = 40013, ["name"] = "Aethril Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 846, ["storyline"] = { 40013, 40014, 40015, 40016, 40017 }, ["series"] = { 40014 }, ["description"] = "This herb has clearly been absorbing magical energy from the land. Filaments of ley energy course from root to leaf. Your herbalism trainer in Dalaran will want to see this.", ["objectivesText"] = "Bring the Aethril Sample to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129117 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1677, ["db2PoiUiMapID"] = 846, ["questLines"] = { { ["id"] = 180, ["name"] = "Legion Herbalism", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 129117 } },
[40014] = { ["id"] = 40014, ["name"] = "Spayed by the Spade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40013, 40014, 40015, 40016, 40017 }, ["series"] = { 40013 }, ["description"] = "The stem, leaves, and petals are dazzling, to be certain... but look at the pollination filaments, here, and the reproductive organs in the center of the bloom. They contain more energy than the rest of the plant put together. I suspect that we can more responsibly and efficiently harvest aethril by focusing on these parts. Still, it looks like this bloom has been damaged. I need undamaged parts if I'm to be sure.", ["objectivesText"] = "Obtain a Pristine Pistil and a Stainless Stamen . Progress: It may seem wrong to remove these most... \"intimate\" flower parts, but do not fret. They will grow back. Much like the parts of a troll.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129128, 129131 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 180, ["name"] = "Legion Herbalism", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40015] = { ["id"] = 40015, ["name"] = "Ragged Strips of Silk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 846, ["storyline"] = { 40013, 40014, 40015, 40016, 40017 }, ["series"] = { 40016 }, ["description"] = "Finely made strips of clothing, torn, tattered, and dirty: telltale signs of the withered. The feral, degenerate outcasts of nightborne society must also be harvesting the aethril... but why?", ["objectivesText"] = "Speak with Kuhuine Tenderstride about aethril and the withered. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124101, 129117, 129135 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1677, ["db2PoiUiMapID"] = 846, ["questLines"] = { { ["id"] = 180, ["name"] = "Legion Herbalism", ["orderIndex"] = 2, ["flags"] = 0 } }, ["startItems"] = { 129135 } },
[40016] = { ["id"] = 40016, ["name"] = "Desperation Breeds Ingenuity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40013, 40014, 40015, 40016, 40017 }, ["series"] = { 40015 }, ["description"] = "I believe we may be able to use this clue to our advantage, <name>. The withered are notoriously thirsty for mana, and will stop at nothing to get it. Perhaps we can study how they use the aethril and use the results to improve our own harvesting methods.", ["objectivesText"] = "Obtain 6 Chewed Aethril Stems from Withered in Azsuna. Progress: I am glad you continue to come to my shop, <name>. I am useless with a weapon. We need adventurers like you to solve cases like this.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124101, 129135, 129153 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 180, ["name"] = "Legion Herbalism", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40017] = { ["id"] = 40017, ["name"] = "A Slip of the Hand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40013, 40014, 40015, 40016, 40017 }, ["description"] = "As you harvest the aethril, your hand brushes the flower's pollinating organs against one another, creating a reaction. You may have discovered a new herbalism technique. Your trainer in Dalaran would be a good person to discuss this with.", ["objectivesText"] = "Speak with Kuhuine Tenderstride about the quick-reproducing property of aethril.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124101, 129135 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 180, ["name"] = "Legion Herbalism", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40018] = { ["id"] = 40018, ["name"] = "Dreamleaf Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40018, 40019, 40020, 40021, 40022, 40023 }, ["series"] = { 40019 }, ["description"] = "The herb is brilliantly green, paper-thin, and somewhat sticky. Your herbalism trainer in Dalaran will want to see this.", ["objectivesText"] = "Bring the Dreamleaf Sample to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129118 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 253, ["name"] = "Legion Herbalism", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 129118 } },
[40019] = { ["id"] = 40019, ["name"] = "An Empathetic Herb", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40018, 40019, 40020, 40021, 40022, 40023 }, ["series"] = { 40018 }, ["description"] = "Something is different about this dreamleaf, though. It is less than pure. I have a theory. The wilds of Val'sharah have been blighted by a nightmarish curse. Sensitive herbs like this may be susceptible to such a blight. I need more information before I can draw any conclusions. Find me some healthy samples and some blight-infested samples, and we can continue.", ["objectivesText"] = "Obtain 15 Healthy Dreamleaf and 5 Blight-Infested Dreamleaf . Progress: Those poor plants...", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 129150, 129151, 136708 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 253, ["name"] = "Legion Herbalism", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40020] = { ["id"] = 40020, ["name"] = "Twisted to Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40018, 40019, 40020, 40021, 40022, 40023 }, ["series"] = { 40021 }, ["description"] = "The corruption has completely taken this herb. This blight is a mysterious force whose complexities transcend the teachings of simple herbalism. An expert in such infestation will need to tell you what's really going on here.", ["objectivesText"] = "Find someone in Lorlathil to teach you about the blight's effects on herbs. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129136 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 98135, ["x"] = 0.544, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 253, ["name"] = "Legion Herbalism", ["orderIndex"] = 2, ["flags"] = 0 } }, ["startItems"] = { 129136 } },
[40021] = { ["id"] = 40021, ["name"] = "One Dead Plant is One Too Many", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40018, 40019, 40020, 40021, 40022, 40023 }, ["series"] = { 40020 }, ["description"] = "We must exact VENGEANCE for this. While I understand the importance of the balance between the Emerald Dream and the Nightmare, this time it's corruption has gone TOO FAR! Satyrs. I blame the satyrs for this. Make them pay! Make them pay, and Elune will reward you with her bounty!", ["objectivesText"] = "Slay 20 satyrs within Val'sharah. Progress: Exact your bloody vengeance, <class>. Show them the might of an herbalist.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129136 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 98135, ["x"] = 0.544, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 98135, ["x"] = 0.544, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 253, ["name"] = "Legion Herbalism", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40022] = { ["id"] = 40022, ["name"] = "Choked by Nightmare", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40018, 40019, 40020, 40021, 40022, 40023 }, ["series"] = { 40023 }, ["description"] = "Another plant, killed by the blight. This one coiled so hard that it starved itself of sunlight. You should bring it to Wildcrafter Osme in Lorlathil. He won't be happy.", ["objectivesText"] = "Bring the Blight-Choked Herb to Wildcrafter Osme in Val'sharah. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 129141 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 98135, ["x"] = 0.544, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 253, ["name"] = "Legion Herbalism", ["orderIndex"] = 4, ["flags"] = 0 } }, ["startItems"] = { 129141 } },
[40023] = { ["id"] = 40023, ["name"] = "The Last Straw", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40018, 40019, 40020, 40021, 40022, 40023 }, ["series"] = { 40022 }, ["description"] = "We cannot falter in our crusade against this corruption, <name>. It is our duty as heroes. As herbalists. As hero-balists. Slaying simple satyrs will not do. We must attack their leaders. Bring this fallen herb to Shala'nir, in the northeast. Find Tur'xoran 's summoning stone, and place this herb in front of it. Then... rip off his head. Do it for the plants.", ["objectivesText"] = "Use Tur'xoran 's Summoning Stone to summon and slay Tur'xoran . Progress: <The druid seethes.>", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 98135, ["x"] = 0.544, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 98135, ["x"] = 0.544, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "group", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 253, ["name"] = "Legion Herbalism", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40024] = { ["id"] = 40024, ["name"] = "Foxflower Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 40024, 40025, 40026, 40028 }, ["description"] = "Something about this herb catches your eye... and your nose. Your herbalism trainer in Dalaran would certainly be interested in studying some samples of this piquant new flower.", ["objectivesText"] = "Obtain 20 samples of Foxflower , then bring them to Kuhuine Tenderstride in Dalaran. Progress: <The tauren sniffs the air.>", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124103, 129119 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 254, ["name"] = "Legion Herbalism", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 129119 } },
[40025] = { ["id"] = 40025, ["name"] = "Teeny Bite Marks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 40024, 40025, 40026, 40028 }, ["series"] = { 40026 }, ["description"] = "This herb has been chewed by some of the local wildlife. What kind of animal would eat foxflower? A bear? Perhaps your trainer in Dalaran will know.", ["objectivesText"] = "Bring the Nibbled Foxflower Stem to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129137 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 254, ["name"] = "Legion Herbalism", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 129137 } },
[40026] = { ["id"] = 40026, ["name"] = "Chase the Culprit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40024, 40025, 40026, 40028 }, ["series"] = { 40025 }, ["description"] = "This is a powerful herb, <name>. Creatures will occasionally snack on some simpler herbs, but usually they avoid plants of such potency. I'm intrigued. What kind of animal would eat foxflower? A moose? You should investigate further. Find out what creature has been snacking on foxflower, and then see if you can wrestle some of the flowers from its mouth, before it escapes.", ["objectivesText"] = "Find out what creature has been eating Foxflower, then chase it and catch 12 Chewed Foxflower Bits . Progress: Did you find out what was eating the foxflower? Was it a goat? A beaver? A nightsaber?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 95416, 124103, 124124, 129137, 129220, 129278 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 254, ["name"] = "Legion Herbalism", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40028] = { ["id"] = 40028, ["name"] = "The Pied Picker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 40024, 40025, 40026, 40028 }, ["description"] = "As you finish gathering the foxflower, a particular part of the bloom catches your eye. One of the leaves has a small protuberance, right where it meets the stem. Further investigation suggests that this is where the foxflower's unusual smell comes from. Your herbalism trainer would be interested in seeing this.", ["objectivesText"] = "Bring the Foxflower Scent Gland to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129278 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 254, ["name"] = "Legion Herbalism", ["orderIndex"] = 3, ["flags"] = 0 } }, ["startItems"] = { 129278 } },
[40029] = { ["id"] = 40029, ["name"] = "Fjarnskaggl Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 40029, 40030, 40031, 40032, 40033 }, ["description"] = "To one not trained in herbalism, this brambly bush might appear to be entirely useless. Your training, however, reveals this to be a very special plant indeed. Your herbalism trainer in Dalaran will want to see some more samples of this.", ["objectivesText"] = "Bring 20 Fjarnskaggl to Kuhuine Tenderstride in Dalaran. Progress: What do you have there, herbalist?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124104, 129120 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 255, ["name"] = "Legion Herbalism", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 129120 } },
[40030] = { ["id"] = 40030, ["name"] = "Ram's-Horn Trowel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 40029, 40030, 40031, 40032, 40033 }, ["series"] = { 40031 }, ["description"] = "The rune markings along the tool's grip suggest that it was left behind by a vrykul herbalist. Apparently, the vrykul are also gathering this fjarnskaggl. Your trainer, Kuhuine, mentioned that she had read about this herb in the past. Perhaps she might be interested in seeing the tools that the vrykul use to harvest it.", ["objectivesText"] = "Bring the Ram's-Horn Trowel to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129138 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 255, ["name"] = "Legion Herbalism", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 129138 } },
[40031] = { ["id"] = 40031, ["name"] = "Vrykul Herblore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40029, 40030, 40031, 40032, 40033 }, ["series"] = { 40030 }, ["description"] = "<Kuhuine studies the trowel further.> This is a standard digging tool. There is not much to be learned here, except... ...this DOES suggest that the vrykul are still actively gathering this herb. The vrykul likely know much more about this herb than we do. All we need to do is find out where their knowledge is stored.", ["objectivesText"] = "Find three vrykul Herbology books in Stormheim. Progress: Any luck finding those books, <name>?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 109076, 129138, 129200, 129201, 129202 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 255, ["name"] = "Legion Herbalism", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40032] = { ["id"] = 40032, ["name"] = "The Missing Page", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 40029, 40030, 40031, 40032, 40033 }, ["series"] = { 40033 }, ["description"] = "<The page appears to be ripped out of a larger book. It reads:> \"...the Cairn of the Sea, a place long-known to be beloved by the gods. He placed his offering of fjarnskaggl at the foot of the cairn, mouthed the words 'Herbs beget herbs', and received the blessing he desired.\" This may be related to the books you brought back to your herbalism trainer.", ["objectivesText"] = "Bring the Runed Journal Page to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124104, 129135, 129142 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 255, ["name"] = "Legion Herbalism", ["orderIndex"] = 3, ["flags"] = 0 } }, ["startItems"] = { 129142 } },
[40033] = { ["id"] = 40033, ["name"] = "Fjarnskaggl", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 634, ["storyline"] = { 40029, 40030, 40031, 40032, 40033 }, ["series"] = { 40032 }, ["description"] = "There! It seems that there was a vrykul herbalist, Torgus , who brought a gift of fjarnskaggl to a seaside cairn - presumably in Stormheim - and by doing so received a blessing from his ancestors. <Kuhuine shrugs.> It's worth a shot, though without knowing what you're getting into, you may want to bring friends with you.", ["objectivesText"] = "Bring 20 Fjarnskaggl to the Wind-Worn Cairn in Stormheim, then earn the Blessing of Fjarnskaggl.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124124, 137021 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "group", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 255, ["name"] = "Legion Herbalism", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40034] = { ["id"] = 40034, ["name"] = "Starlight Rosedust", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 846, ["storyline"] = { 40034, 40035, 40036, 40037, 40038, 40039 }, ["series"] = { 40035 }, ["description"] = "Despite all your training, the rose disintegrated in your hand. Your herbalism trainer in Dalaran will want to see this.", ["objectivesText"] = "Bring the Starlight Rosedust to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 109076, 124105, 129121, 129158 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1677, ["db2PoiUiMapID"] = 846, ["questLines"] = { { ["id"] = 256, ["name"] = "Legion Herbalism", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 129121 } },
[40035] = { ["id"] = 40035, ["name"] = "The Gentlest Touch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40034, 40035, 40036, 40037, 40038, 40039 }, ["series"] = { 40034 }, ["description"] = "Sadly, I don't have any special techniques that can help you here. You'll simply need to practice your methods. Get back out there, and focus on a gentle touch when dealing with starlight roses.", ["objectivesText"] = "Attempt to harvest 15 more Starlight Roses.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 256, ["name"] = "Legion Herbalism", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40036] = { ["id"] = 40036, ["name"] = "Jeweled Spade Handle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 846, ["storyline"] = { 40034, 40035, 40036, 40037, 40038, 40039 }, ["series"] = { 40037 }, ["description"] = "An immaculately carved spade handle lies beside the rose. Apparently the spade was more beautiful than it was durable, as the blade has completely fallen off. Your herbalism trainer may be interested in seeing this.", ["objectivesText"] = "Bring the Jeweled Spade Handle to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124105, 129140 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1677, ["db2PoiUiMapID"] = 846, ["questLines"] = { { ["id"] = 256, ["name"] = "Legion Herbalism", ["orderIndex"] = 2, ["flags"] = 0 } }, ["startItems"] = { 129140 } },
[40037] = { ["id"] = 40037, ["name"] = "The Spade's Blade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40034, 40035, 40036, 40037, 40038, 40039 }, ["series"] = { 40036 }, ["description"] = "Did you notice the script along the base of the handle, <name>? It says \"Herbalist Tharillon,\" in the writing of the nightborne. The handle does little for us, but perhaps the blade of this spade will give us some information on how to harvest the starlight rose without failing quite so often. I would start my search for it in Suramar.", ["objectivesText"] = "Find the Broken Herbalist's Blade . Progress: How goes your search?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124105, 129140, 129155 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 256, ["name"] = "Legion Herbalism", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40038] = { ["id"] = 40038, ["name"] = "Insane Ramblings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 846, ["storyline"] = { 40034, 40035, 40036, 40037, 40038, 40039 }, ["series"] = { 40039 }, ["description"] = "Scribbled, angry phrases on a dirty scrap of vellum. One part catches your eye: \"thinks <HE/SHE> knows how to gather herbs <name><name> <name><name> steal my blade slit <his/her> THROAT when I just need a bit more mana maybe aethril, yes...\" Your herbalism trainer may be interested in seeing this.", ["objectivesText"] = "Bring the Scribbled Ramblings to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 58650, ["rewardXP"] = 1415, ["rewardItems"] = { 129143 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1677, ["db2PoiUiMapID"] = 846, ["questLines"] = { { ["id"] = 256, ["name"] = "Legion Herbalism", ["orderIndex"] = 4, ["flags"] = 0 } }, ["startItems"] = { 129143 } },
[40039] = { ["id"] = 40039, ["name"] = "Tharillon's Fall", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40034, 40035, 40036, 40037, 40038, 40039 }, ["series"] = { 40038 }, ["description"] = "He mentions your name... his blade... aethril... I'd say that this is absolutely from Herbalist Tharillon, and by the look of it, he may have succumbed to the plight of the nightfallen. Furthermore, if he's looking for aethril, he's probably in Azsuna somewhere. Tharillon is currently our only hope for learning more about starlight roses. Seek him out, but you may want to bring friends... he likely won't go without a fight.", ["objectivesText"] = "Bring 20 piles of Starlight Rosedust to Azsuna, use them to taunt Herbalist Tharillon out of hiding, then search him for information about herbalism. Progress: May the Earthmother walk with you, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124105, 129143, 129158, 129209 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "group", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 256, ["name"] = "Legion Herbalism", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40040] = { ["id"] = 40040, ["name"] = "Felwort Sample", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 40040, 40041, 40042 }, ["description"] = "This herb bubbles and seethes with a foul energy. It is smooth, dry, and cool, yet somehow quite painful to touch. Your herbalism trainer in Dalaran will want to see this.", ["objectivesText"] = "Bring the Felwort Sample to Kuhuine Tenderstride in Dalaran. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 129122 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 257, ["name"] = "Legion Herbalism", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 129122 } },
[40041] = { ["id"] = 40041, ["name"] = "Felwort Analysis", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40040, 40041, 40042 }, ["description"] = "I sent felwort samples to some of my fellow herbalists, but haven't heard back from them yet. Could you please follow up with them and collect their analyses. Ryno Bloomfield is currently working in Un'goro Crater. Dani Earthtouch is researching Freya's influence in Sholazar Basin. Finally, Lohor has been working in the overgrown portion of Gorgrond.", ["objectivesText"] = "Collect Ryno Bloomfield's Analysis , Dani Earthtouch's Analysis , and Lohor's Analysis . Progress: Thank you for your willingness to travel, <name>.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 63206, 63207, 104113, 110560, 119093, 129212, 129213, 129214, 129929, 140192 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 257, ["name"] = "Legion Herbalism", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40042] = { ["id"] = 40042, ["name"] = "The Emerald Nightmare: Felwort Mastery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40040, 40041, 40042 }, ["description"] = "I have a theory on how we can better harvest this felwort, <name>. You see, sometimes in order to understand how something comes into being, you have to work backwards. I've recently heard of the corruption of one of our greatest gods, Cenarius. I have no doubt the same corruption that lives in these herbs also resides within him now. If you were able to cleanse that corruption, find a way to understand how it works and remove it, I think we can apply that to how we harvest these herbs.", ["objectivesText"] = "Travel to the Emerald Nightmare and cleanse Cenarius of his affliction. Bring back anything you discover to Kuhuine in Dalaran. Progress: I hope you bring some friends with you on this journey, for this may be your greatest lesson.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129289, 136413 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "raid", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 257, ["name"] = "Legion Herbalism", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40044] = { ["id"] = 40044, ["name"] = "Shadows in the Mists", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39984, 40044, 40046, 43595, 43596 }, ["description"] = "Many of the Kvaldir here in the bay are former denizens of this harbor, cursed by the sea-witch Helya to do her bidding for all time. The ones you read about, they still walk the stagnant waters. They could be given respite, should a kind soul bring it to them at the tip of a blade. So tell me, how kind is your soul?", ["objectivesText"] = "Defeat Captain Sten , Sigrid , Kjell and Halvir in Helmouth Shallows.", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardItems"] = { 129350, 132770, 132771, 132772, 132773, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97973, ["x"] = 0.59, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97973, ["x"] = 0.59, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5924, ["name"] = "The Fate of Tideskorn Harbor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40046] = { ["id"] = 40046, ["name"] = "Scavenging the Shallows", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39984, 40044, 40046, 43595, 43596 }, ["description"] = "The kvaldir exist to spite Odyn, and it is here their spiteful work is done. They rob the souls of the living - the souls not yet judged - thus robbing Odyn of his champions. They bring them here to transport to Helya, though the mists obscure any indications of how. You seem to fare the mists well. Perhaps if you search the wreckage in the bay, the answer may present itself. You outsiders seem to have a knack for uncovering the most hidden of secrets.", ["objectivesText"] = "Search the Shipwreck Debris in Helmouth Shallows for Havi 's clue. Progress: Have you found answers, or more questions?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 129174, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97973, ["x"] = 0.59, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97973, ["x"] = 0.59, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5924, ["name"] = "The Fate of Tideskorn Harbor", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40050] = { ["id"] = 40050, ["name"] = "Shipwreck Cove", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 40050 }, ["objectivesText"] = "Sabotage the Swamprock", ["rewardGold"] = 683200, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Sabotage the Swamprock", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650 },
[40062] = { ["id"] = 40062, ["name"] = "Bulging Nightmare Pod", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["description"] = "<The flower has folded inward, to protect itself from the nightmare energy trapped within.> < Professor Pallin would be interested in seeing this.>", ["objectivesText"] = "Bring the Bulging Nightmare Pod to Professor Pallin in Dalaran. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124101, 124102, 124103, 124104, 124105, 124106, 129032, 129034, 136909, 136912, 136915, 136916, 136917, 136918 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 35, ["flags"] = 0 } }, ["startItems"] = { 136912 } },
[40064] = { ["id"] = 40064, ["name"] = "Woody Seed Cluster", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["description"] = "<Attempting to mill this flower has proven more difficult than usual. Located in the bushy center of the bloom is a densely-packed cluster of seeds.> < Professor Pallin would be interested in seeing this.>", ["objectivesText"] = "Bring the Woody Seed Cluster to Professor Pallin in Dalaran. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124101, 124102, 124103, 124104, 124105, 124106, 129032, 129034, 136909, 136912, 136915, 136916, 136917, 136918 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 36, ["flags"] = 0 } }, ["startItems"] = { 136915 } },
[40065] = { ["id"] = 40065, ["name"] = "Fjarnsk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["description"] = "<A goopy substance seeps from the interior of the bloom. It's not ink... it is something else entirely.> < Professor Pallin would be interested in seeing this.>", ["objectivesText"] = "Bring the Fjarnsk to Professor Pallin in Dalaran. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124101, 124102, 124103, 124104, 124105, 124106, 124124, 129032, 129034, 136909, 136912, 136915, 136916, 136917, 136918 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 37, ["flags"] = 0 } }, ["startItems"] = { 136916 } },
[40069] = { ["id"] = 40069, ["name"] = "Fledgling Worm Guts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39305, 40069, 40070, 40071, 42425 }, ["description"] = "The drogbar use these caves as a place to train fledgling worms. The rockcrawlers are young and fairly weak, for now, but in time they will grow in size and strength. Without our intervention, the worms will morph into the monstrosities that the drogbar ride into battle. Their guts are also known to be quite useful, and I have need of them. Two worms, one stone.", ["objectivesText"] = "Collect Worm Guts from Fledgling Rockcrawlers within Rockcrawler Chasm. Progress: What are their guts for? Well, you'll see. You might not like it, but you will soon find out.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 137569, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5923, ["name"] = "Rockcrawler Chasm", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40070] = { ["id"] = 40070, ["name"] = "Eagle Egg Recovery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39305, 40069, 40070, 40071, 42425 }, ["description"] = "Eagles are revered by the Skyhorn tribe, but their numbers are dwindling. The drogbar feed their fledgling worms eagle eggs so they'll grow strong enough to ride into battle. If the drogbar continue to pilfer these eggs, the eagles may become extinct. Head deeper into the cave and recover any eagle eggs you can find.", ["objectivesText"] = "Head into Rockcrawler Chasm and recover eagle eggs . Progress: If the pilfered eggs are not recovered, the eagle may go extinct.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128760, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5923, ["name"] = "Rockcrawler Chasm", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40071] = { ["id"] = 40071, ["name"] = "Tamer Takedown", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39305, 40069, 40070, 40071, 42425 }, ["description"] = "The drogbar will continue to breed vicious worms as long as their tamer lives. Korgrul is responsible for turning fledgling rockcrawlers into the monstrous siege worms that are ridden into battle. Head deep into the chasm and end his life, so that we may also see the end of these unnatural creatures.", ["objectivesText"] = "Kill Tamer Korgrul within Rockcrawler Chasm. Progress: Put an end to Tamer Korgrul , so that we may also put an end to the training of siege worms.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 121681, 121682, 121683, 121684, 121721, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5923, ["name"] = "Rockcrawler Chasm", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40110] = { ["id"] = 40110, ["name"] = "Disrupt the Inkbinders", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["storyline"] = { 40110 }, ["rewardGold"] = 510000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard" },
