[40401] = { ["id"] = 40401, ["name"] = "A Way Back In", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40401, 40424, 40469, 40470 }, ["series"] = { 40424, 40469 }, ["description"] = "I must get back into Suramar . I was exiled unfairly! I cannot live out here like this. I need the Nightwell's energies... I saw a message carved into a wall a few days ago. There is someone in the Water Gardens who can smuggle people into the city. It said \"We shall drink of the Well again.\" I cannot survive a confrontation with the guards again. Will you go in my stead? Once I am back in the city I can repay you.", ["objectivesText"] = "Find the smuggler. Progress: Who are you to seek passage into Suramar ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 100185, ["x"] = 0.342, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 100192, ["x"] = 0.414, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5820, ["name"] = "A Desperate Journey", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40423] = { ["id"] = 40423, ["name"] = "Unethical Adventurers", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 40423 }, ["rewardItems"] = { 131767, 138839, 140680, 140681, 140682, 140683 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2VignetteID"] = 1158, ["db2VignetteName"] = "Unethical Adventurers" },
[40424] = { ["id"] = 40424, ["name"] = "A Desperate Journey", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40401, 40424, 40469, 40470 }, ["series"] = { 40401, 40469 }, ["description"] = "The city's entrances are under heavy guard. He must have another way. Thanks to this wine I am strong enough to make the journey to him. I fear that I will not be able to defend or run if I come under attack. You will accompany me, <race>. You and this Astoril are my only chance at surviving now. I remember when I was leaving the city that there were lamps guiding me here. We should be able to retrace our steps by following them.", ["objectivesText"] = "Follow the lamp posts to take Iadreth to Astoril . Progress: I was worried something had happened to you in the forest. I am glad that I was wrong.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140237, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 100185, ["x"] = 0.342, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 100301, ["x"] = 0.38, ["y"] = 0.69 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5820, ["name"] = "A Desperate Journey", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40470] = { ["id"] = 40470, ["name"] = "Quality of Life", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40401, 40424, 40469, 40470 }, ["description"] = "I am afraid, <name>. We're so close to home, so close to salvation... Astoril says he knows the rest of the way through and can get us there safely. I believe him, but you've come this far to see us safe. Will you see this through to the end?", ["objectivesText"] = "Follow Iadreth .", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 133760, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 100331, ["x"] = 0.379333, ["y"] = 0.662667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.379333, ["y"] = 0.662667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5820, ["name"] = "A Desperate Journey", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40501] = { ["id"] = 40501, ["name"] = "REUSEME_40501", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 40501 }, ["series"] = { 36007, 36009, 36010, 36012, 36013, 36014, 36016, 36017, 36018, 37834, 37836, 37837, 37841, 37964, 39023 }, ["description"] = "If Garona's intelligence is correct, Gul'dan will be inside this Iron Horde compound. With Garona's help, slip inside, gather any info you find, and learn what Gul'dan intends to do. The guards are on high alert. Garona can \"liquidate\" individual guards for you, but she must not be seen! You will have to choose your targets carefully and pick your way through the bastion undetected. Don't let anyone sound the alarm. If things get too hot, I'll teleport you to safety. At least... I'll try.", ["objectivesText"] = "Infiltrate Bladefury's Command with Garona's help. Use her talents to eliminate guards without being seen. Locate Iron Horde intelligence and then spy on Gul'dan.", ["rewardGold"] = 308000, ["rewardXP"] = 50, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
