[40631] = { ["id"] = 40631, ["name"] = "Basking in Glory", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 40631 }, ["description"] = "You... you glow with the radiance of Odyn himself... You must return to your people at once. Odyn's light is a gift that must be shared with all.", ["objectivesText"] = "Return to Sister Elda in the Sanctum of Light.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[40635] = { ["id"] = 40635, ["name"] = "Sashj'tar Slayer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["storyline"] = { 40635 }, ["description"] = "I cannot believe that Throndyr is gone. By the horns on my head, we shall have revenge for all of the pain that the Sashj'tar have inflicted on us! Press forward, <name>. Kill them! Kill them all!", ["objectivesText"] = "Slay 12 Sashj'tar naga in Azuregale Cove.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40637] = { ["id"] = 40637, ["name"] = "Proof of Honor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 40637 }, ["description"] = "<Brandolf breathes heavily.> This cave will be my final resting place, <name>. Find Toryl. Tell her of what happened here today. Tell all of Jandvik that I died defending our village...", ["objectivesText"] = "Return to Toryl in Jandvik.", ["rewardGold"] = 154900, ["rewardXP"] = 3070, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[40661] = { ["id"] = 40661, ["name"] = "Protect the Home Front", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 40517, 40519, 40593, 40661, 42740, 42782, 44120 }, ["description"] = "The Legion hasn't just invaded this city. Their evil is spreading across Azeroth, threatening the far corners of our world. We must seek them out and stop them, everywhere their darkness touches. We've dispatched scouts around the world to watch for Legion activity. As invasions arise, we'll mark the locations on your map. Make them suffer, <name>!", ["objectivesText"] = "Open your map to find an active Legion invasion in Kalimdor or Eastern Kingdoms. Go to the invasion site and stop the demons! Progress: Find them! Stop them! Suffer well!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 101004, ["x"] = 0.405, ["y"] = 0.779 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 101004, ["x"] = 0.405, ["y"] = 0.779 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.779 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 240, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 259, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 262, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40676] = { ["id"] = 40676, ["name"] = "You Must Make Haste", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 40676 }, ["description"] = "I suggest that you set off immediately, <name>. You have been here for far too long - the Legion's assassins could close in at any moment to make an attempt on your life. Do take caution when using the heart - even with the bindings to aid you the power within is dangerous.", ["objectivesText"] = "Return to King Magni Bronzebeard in the hills below Ironforge.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[40685] = { ["id"] = 40685, ["name"] = "Into the Mouth of the Nether", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 40685 }, ["series"] = { 40684, 40716, 40729 }, ["description"] = "With the ritual failed and the council scattered, you find yourself trapped in the prison of the pit lord, Jagganoth. The situation is grim, but with the help of the remaining council members, you may be able to escape.", ["objectivesText"] = "Escape from Dreadscar Rift.", ["rewardGold"] = 154000, ["rewardXP"] = 200, ["rewardItems"] = { 132512 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[40693] = { ["id"] = 40693, ["name"] = "Eyes of Nashal - Choice UI - Deadly Eye of Prophecy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 40693 }, ["rewardItems"] = { 130219 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[40694] = { ["id"] = 40694, ["name"] = "One Small Step for Magic", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40625, 40642, 40657, 40683, 40694, 40713, 40919, 42366 }, ["description"] = "It is time to embrace the future. I have mastered every magic known to our kind. I will master this one. By applying the principles of arcane magic it is fairly trivial to control the primitive fel energies within the material you have given me. I need to move to live prey next. Let us start with a small summoning. Defeat the creature for me and watch how a true scholar works!", ["objectivesText"] = "Speak to Kyrtos and assist him with his ritual. Progress: Ahh, this is a most interesting observation.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140238, 217930, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.268, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5818, ["name"] = "Research Gone to Fel", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40695] = { ["id"] = 40695, ["name"] = "Eyes of Nashal - Choice UI - Quick Dawnlight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 40695 }, ["rewardItems"] = { 130220 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
