[40717] = { ["id"] = 40717, ["name"] = "Calling of the Council", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 12, ["mapID"] = 42, ["storyline"] = { 40717, 40755, 42970 }, ["description"] = "<The arcane anomaly turns to address you, speaking in what is clearly Khadgar's voice.> Though I am loathe to interrupt your fight against the Legion, I must request your help in a matter of... diplomacy. We face a grave threat, and we must be at our full strength to overcome it. Some will not agree with this position. Please join me outside the Violet Citadel in Dalaran. We have repositioned the city to defend the Eastern Kingdoms. You'll find it over Deadwind Pass, above Karazhan.", ["objectivesText"] = "Meet Khadgar in Dalaran at its new location above Deadwind Pass.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 139389, 139391, 237812 }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 113637, ["x"] = 0.412, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 41, ["questLines"] = { { ["id"] = 241, ["name"] = "Legion Launch Events - Week 2", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40718] = { ["id"] = 40718, ["name"] = "Calling of the Council", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 12, ["mapID"] = 42, ["storyline"] = { 40718, 40755, 42970 }, ["description"] = "<The arcane anomaly addresses you in Khadgar's voice.> Though I am loathe to interrupt your fight against the Legion, I must request your help in a matter of... diplomacy. We face a grave threat, and we require the full might of Azeroth's people to overcome it. The Horde must become part of the Kirin Tor once again. Some will not agree with this position. Please join me outside the Violet Citadel in Dalaran. We have repositioned the city to defend the Eastern Kingdoms, above Karazhan.", ["objectivesText"] = "Meet Khadgar in Dalaran at its new location above Deadwind Pass.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 13379, 237812 }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 113637, ["x"] = 0.412, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 42, ["questLines"] = { { ["id"] = 258, ["name"] = "Legion Launch Events - Week 2", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40725] = { ["id"] = 40725, ["name"] = "Arganax", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 40725 }, ["description"] = "A satyr known as Arganax has infiltrated the village of Lorlathil in Val'sharah. I believe that Arganax has disguised himself as one of the local residents. Use the demon Eye of Azzorok on the villagers in Lorlathil. If there is a demon disguised as a local, the Eye of Azzorok will reveal their true identity. Uncover the demon infiltrator Arganax , and slay him without mercy.", ["objectivesText"] = "Find and slay Arganax in Lorlathil.", ["rewardGold"] = 194000, ["rewardXP"] = 200, ["rewardItems"] = { 132877 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[40749] = { ["id"] = 40749, ["name"] = "A Token of Remembrance", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 40749 }, ["description"] = "The flower rests peacefully in your hand, glowing softly. While it doesn't appear to be growing anywhere nearby, there are small bouquets of the flower on some of the memorials around here. Perhaps laying down some flowers on the remaining graves will ease the gloom.", ["objectivesText"] = "Place 4 Bouquets of Moon Lilies.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 132886, 132887 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 132885 } },
[40753] = { ["id"] = 40753, ["name"] = "Blingtron 6000", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 40753 }, ["rewardItems"] = { 132530, 132892 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[40755] = { ["id"] = 40755, ["name"] = "Hiding in the Stacks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40717, 40755, 42970 }, ["series"] = { 42970 }, ["description"] = "Magni's information was enlightening. It should prove handy to have a friend who has the ear of a titan. It's time to head into Karazhan . Not that I need to remind you, but it can be a dangerous place. There are countless strata of spells woven throughout the tower, and the interactions of the forces within can be... unpredictable. Be on your guard. I'll join you inside. I need a moment to... gather my thoughts. This place holds a lot of memories for me.", ["objectivesText"] = "Enter Karazhan and search for knowledge of the Pillars of Creation with Khadgar. Progress: Do you have something for me?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 139905, 139934, 139965, 140635, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 101547, ["x"] = 0.47, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 113836, ["x"] = 0.412, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 41, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 241, ["name"] = "Legion Launch Events - Week 2", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 258, ["name"] = "Legion Launch Events - Week 2", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40762] = { ["id"] = 40762, ["name"] = "Zealot's Dues", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40762 }, ["description"] = "Commander Domitille represents the very essence of the Nightborne's corruption. Abhorrent of power not their own, enamoured with their Grand Magistrix to the point of zealotry, and focused utterly on the destruction of the Moon Guard. Take her helm to Lothrius as proof of her demise.", ["objectivesText"] = "Take Commander Domitille's Helm to Lothrius Mooncaller . Provided item:", ["rewardGold"] = 561800, ["rewardXP"] = 7675, ["rewardItems"] = { 109076, 131811, 136851, 141672 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101082, ["x"] = 0.395, ["y"] = 0.328 }, { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["startItems"] = { 136851 } },
