[40776] = { ["id"] = 40776, ["name"] = "Kazok'thul", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 40776 }, ["description"] = "A rogue felhunter known as Kazok'thul has been terrorizing Azurewing Repose in Azsuna. Felhunters feed on arcane energy and it seems that Kazok'thul has been gorging itself on the mana from nearby Azurewing whelps. Travel to Azurewing Repose and speak with Ardonu to find the last known location of Kazok'thul . Slay the demon and return here when your mission is complete.", ["objectivesText"] = "Find and slay Kazok'thul in Azurewing Repose.", ["rewardGold"] = 194000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[40779] = { ["id"] = 40779, ["name"] = "We Need Even More Power!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 40779 }, ["description"] = "Good new, <race>! I have located another power orb. I last saw it down by the Nightborne encampment to the southwest. I had to get out of there before their patrols saw me, but it should be no trouble for you, now should it?", ["objectivesText"] = "Find the Charged Power Orb.", ["rewardGold"] = 232300, ["rewardXP"] = 4605, ["rewardItems"] = { 129759, 130079 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
