[40973] = { ["id"] = 40973, ["name"] = "Creating Time", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["storyline"] = { 40973 }, ["description"] = "Thanks in large part to your substantial efforts, we have discovered the whereabouts of a powerful piece of our history. It should enable us to survive whatever else the Nightborne have to throw at us, and hopefully more. However, recovering it will require a great deal of our energy and focus. We will bolster the Starweaver's scrying efforts, but the slightest disruption will ruin this delicate spellwork. See that we are not disturbed. Speak to Syrana Starweaver when you are ready to begin.", ["objectivesText"] = "Defend Syrana Starweaver .", ["rewardItems"] = { 133994 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[40974] = { ["id"] = 40974, ["name"] = "Latosius' Trial", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["storyline"] = { 40974 }, ["description"] = "I bow to Latosius' wisdom. If we are to endure, it must be you who claims the Amulet. Survive this challenge, <name>, and the might of the Moon Guard will be yours forevermore.", ["objectivesText"] = "Survive the Trial of Latosius.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
