[40988] = { ["id"] = 40988, ["name"] = "Too Many Cooks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 40988 }, ["series"] = { 40989, 40990, 40991 }, ["description"] = "Greetings. I am called Nomi . I couldn't help but notice that recipe that you just picked up and... well, you'd never guess it, but I'm a bit of a chef myself. Unfortunately, I'm not much of a fighter, and this place is dangerous. You, on the other hand, are clearly an accomplished <class>. Come find me in Dalaran. Maybe we can work together!", ["objectivesText"] = "Meet Nomi in Dalaran.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124108, 124110, 124117, 124121, 133564, 133575, 133578, 133680, 133814, 133816, 133826, 133827, 198609 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[40989] = { ["id"] = 40989, ["name"] = "The Prodigal Sous Chef", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 40989 }, ["series"] = { 40988, 40990, 40991 }, ["description"] = "<name>? Master, is that you? Don't you recognize me? It's me, Nomi ! Remember, we cooked together in Pandaria? More accurately, you cooked and I learned. I was not much more than a cub back then. Boy, am I glad to see you! I'm headed back to the Dalaran kitchens. Come find me! Maybe we can work together!", ["objectivesText"] = "Meet Nomi in Dalaran.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124108, 124110, 124117, 124121, 133564, 133575, 133578, 133680, 133816, 133826, 133827 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[40990] = { ["id"] = 40990, ["name"] = "A Good Recipe List", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 40990 }, ["series"] = { 40988, 40989, 40991 }, ["description"] = "I've tried adventuring, and it isn't for me. Cooking is my one true passion: the heat of the stove, the sizzle of bacon... nothing beats it. Let me help you, Master <name>. If you can bring me some recipes, I can work on improving them, here in Dalaran. We'll make a great team. What do you say?", ["objectivesText"] = "Learn 6 Legion cooking recipes. Progress: We need more recipes before we can do any meaningful work in this kitchen.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 124108, 124110, 124117, 124121, 133564, 133578, 133680, 133810, 133812, 133813, 133814, 133816, 133817, 133818, 133820, 133826, 133827, 133828, 141011, 141012, 142331, 152565, 194034, 194521, 194549, 194705 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
