[41027] = { ["id"] = 41027, ["name"] = "One Last Breath", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 41027 }, ["description"] = "<The parchment is soaked in seawater. A note is hastily scribbled on it.> To whomever finds this note first, Before I was cast from Suramar , I was a master alchemist. In my time, I have concocted many potions and elixirs for the benefit of the Nightborne. All of this was forgotten when the Legion came. Before I succumb to the hunger, I wanted to create one last draught to celebrate my love of sea. Drink it and explore the vast deep in my honor.", ["objectivesText"] = "Drink the Nightfallen Alchemist's Strange Draught in Azuregale Bay.", ["rewardGold"] = 154900, ["rewardXP"] = 3070, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[41031] = { ["id"] = 41031, ["name"] = "For the People", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["storyline"] = { 41031 }, ["description"] = "We have a problem, friend. Across the canal is a district not well known for affluence. Since the demons' arrival, it has been locked down. I have heard the cries of those who have been deprived of sustenance. Take this wineskin. Find an Arcwine fountain and take your fill. Find those who are suffering and offer them a drink. It is the best we can do in the present circumstances. You must not be seen doing this, <name>. It will end badly.", ["objectivesText"] = "Locate an Arcwine Fountain to fill your Empty Arcwine Skin, then offer Arcwine to Mana-Starved Nightborne.", ["rewardGold"] = 105000, ["rewardXP"] = 150, ["rewardItems"] = { 137343, 137345, 232354, 232401, 232403, 232405, 237812, 256228, 256229 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[41041] = { ["id"] = 41041, ["name"] = "Sashj'tar Allies DISBALED", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 41041 }, ["description"] = "Commander Malt'his was conferring with a sea giant? We are prepared to battle the naga, but if they have yoked the strength of the sea giants, we will have to double our efforts to save Jandvik. You must tell Toryl about this grave news right away.", ["objectivesText"] = "Speak with Toryl in Jandvik.", ["rewardGold"] = 97000, ["rewardXP"] = 100, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
