[41065] = { ["id"] = 41065, ["name"] = "Troubling News", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 41065 }, ["description"] = "Master, there is one more thing I wish to speak to you about. Below us lies an open chamber cut off from the rest of the citadel. We thought you might desire it as your personal sanctum - a place where you might gather your thoughts or scry upon your enemies. The sanctum crystal before you will transport you there - Lady S'theno has already descended to help you get acquainted.", ["objectivesText"] = "Use the Sanctum Crystal to enter the Master's Sanctum.", ["rewardGold"] = 17000, ["rewardXP"] = 25, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
