[41137] = { ["id"] = 41137, ["name"] = "Fall of the King", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["storyline"] = { 41137 }, ["description"] = "All that remains is the Sea Giant King. Place our banner upon his beach and draw him out of the sea. Once he has revealed himself, use the trident to wound him. There is a derelict boat that washed up on the shore. Use that to quickly get to the king's island. Gird your loins, <name>. This fight will not be easy.", ["objectivesText"] = "Place the Jandvik Banner on the Sea Giant King's island to draw him out and defeat him.", ["rewardGold"] = 619600, ["rewardXP"] = 7675, ["rewardItems"] = { 134836, 140384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
