[41214] = { ["id"] = 41214, ["name"] = "Parts Unknown", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["mapID"] = 680, ["storyline"] = { 41139, 41140, 41214, 41222, 41309 }, ["series"] = { 41222, 41309 }, ["description"] = "Brambley... I still canna' believe it. I canna' leave the lad here... not in this place... not like this. Help me find the rest of him, so I can take his remains back home where he belongs. We'll give him a proper burial... it's what he deserves!", ["objectivesText"] = "Collect Brambley Morrison's remains. Progress: Aye, is that all of him? We aren't missing any parts are we?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142054, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5817, ["name"] = "In Search of Brambley", ["orderIndex"] = 3, ["flags"] = 0 } } },
[41217] = { ["id"] = 41217, ["name"] = "The Future of Gnomeregan", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 3 }, ["requiredRaces"] = { 7, 37 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 6457, ["mapID"] = 27, ["storyline"] = { 26205, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 41217 }, ["series"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26421, 26422, 26423, 26424, 26425, 26566, 31135, 31137, 41218 }, ["description"] = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. <class>s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts. Muffinus Chromebrew will help oversee your training and adjustment to life on the surface. He's waiting for you on the stands across the road.", ["objectivesText"] = "Meet with Muffinus Chromebrew in New Tinkertown .", ["rewardGold"] = 1000, ["rewardXP"] = 100, ["rewardItems"] = { 59039, 59040, 59041, 59042, 59043, 134123 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 42396, ["x"] = 0.339, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 469, ["npcID"] = 103614, ["x"] = 0.42, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.339, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 27, 469 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 12, ["flags"] = 0 } } },
[41218] = { ["id"] = 41218, ["name"] = "Meet the High Tinker", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["requiredClasses"] = { 1, 3, 11 }, ["requiredRaces"] = { 6, 7, 9 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6457, ["mapID"] = 469, ["storyline"] = { 26205, 26208, 26222, 26264, 26265, 26284, 26285, 26316, 26318, 26329, 26331, 26333, 26339, 26342, 26364, 26373, 26566, 27635, 27670, 27671, 27674, 28167, 28169, 41218 }, ["series"] = { 26197, 26199, 26202, 26203, 26205, 26206, 26208, 26222, 26421, 26422, 26423, 26424, 26425, 26566, 31135, 31137, 41217 }, ["description"] = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor. Mekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", ["objectivesText"] = "Introduce yourself to High Tinker Mekkatorque in New Tinkertown .", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 469, ["npcID"] = 103614, ["x"] = 0.42, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 42317, ["x"] = 0.336, ["y"] = 0.364 } }, ["coords"] = { ["mapID"] = 469, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 27, 469 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 5398, ["name"] = "Gnomeregan", ["orderIndex"] = 19, ["flags"] = 0 } } },
