[41222] = { ["id"] = 41222, ["name"] = "Into The Pit!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["mapID"] = 680, ["storyline"] = { 41139, 41140, 41214, 41222, 41309 }, ["series"] = { 41214, 41309 }, ["description"] = "The felstalker pits?! There's no time to waste, <name>! I canna' tell ye what the Burnin' Legion has planned for ol' Brambley, but it canna' be good! Hurry! We've got to find him before the Burnin' Legion has their way with him!", ["objectivesText"] = "Escort Angus to Felmaw Cavern in Felsoul Hold. Progress: We've got to get to the felstalker pits an' save Brambley!", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 142054, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5817, ["name"] = "In Search of Brambley", ["orderIndex"] = 2, ["flags"] = 0 } } },
