[41256] = { ["id"] = 41256, ["name"] = "Blast of Spice Fish", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41107, 41256, 41258 }, ["description"] = "I have an ingredient that will make my fruit irresistible. Not many remember the delicacy of manatrout liquor. Its pungent aroma, the unctuous mouthfeel... The toads near the northern river concentrate this additive in their gizzards. Fetch some stomachs for me, and we will have plenty.", ["objectivesText"] = "Collect Toad Gizzards for Keelay. Progress: Daglir is young and foolish!", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 134549, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103131, ["x"] = 0.472, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103131, ["x"] = 0.472, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5823, ["name"] = "Fruit of the Doom", ["orderIndex"] = 1, ["flags"] = 0 } } },
