[41258] = { ["id"] = 41258, ["name"] = "Fruit of the Doom", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41107, 41256, 41258 }, ["description"] = "Now is the time to strike. Shadowbloom has... potent digestive qualities. Go sprinkle some on Daglir's fruit bowls and watch the show. Meanwhile, I will use the manatrout liquor to cement my position as the premier fruit vendor in the city.", ["objectivesText"] = "Poison 3 Bowls of Fruit. Progress: Daglir will be ruined after this.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 39563, 140246, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103131, ["x"] = 0.472, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103131, ["x"] = 0.472, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5823, ["name"] = "Fruit of the Doom", ["orderIndex"] = 2, ["flags"] = 0 } } },
