[41761] = { ["id"] = 41761, ["name"] = "Winter Moose Roundup", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["storyline"] = { 41761 }, ["description"] = "My father, Karmaan, owns this farm, and our main livestock are talbuk. One of the podlings must have opened the gate to their pen and they all escaped! The little terrors could have slaughtered them in the cage, but they like to hunt their prey. I'm afraid that if I stay out here much longer, I'll be their next meal! Will you round up the talbuk and bring them here? I can't get them myself, and I can't let my dad find out about this!", ["objectivesText"] = "Rescue 4 Talbuk at Kuuros Farm.", ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard" },
