[41802] = { ["id"] = 41802, ["name"] = "The Gates of Valor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41158, 41159, 41802 }, ["series"] = { 40857, 41157, 41158, 41159, 41161, 41162, 41163, 41164, 41165, 41166, 41167, 41168, 41169, 41170 }, ["description"] = "Ye'd not normally know it, but the terraced entrance to the vrykul's Halls o' Valor is a fine place for findin' ancient artifacts. Problem is, the place is just a big mess with demons at the time. Well, ye've not got much choice. If the disc isn't elsewhere in Stormheim, it most likely lies at the Gates of Valor. Good luck, <name>.", ["objectivesText"] = "Obtain 6 Chipped Titan Disc Fragments by surveying near the Gates of Valor in Stormheim. Progress: Ye're back in one piece. What's the news?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 131735, 134083 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 325, ["name"] = "Legion Archaeology", ["orderIndex"] = 2, ["flags"] = 0 } } },
