[42425] = { ["id"] = 42425, ["name"] = "Going Down, Going Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 39305, 40069, 40070, 40071, 42425 }, ["description"] = "Now that we have the necessary worm guts, I was able to fashion them into a special sort of rope. It will allow you to descend from the bridge into the chasm below and recover some of my possessions that were stolen and thrown in by the Deeprock.", ["objectivesText"] = "Use Oren's Rappel Point to descend into the depths and recover his lost possessions. Progress: I have never been particularly fond of heights.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 121440, 121441, 121442, 121443, 132936, 137566, 141386, 141605, 237812, 246812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 94068, ["x"] = 0.503333, ["y"] = 0.374 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.503333, ["y"] = 0.374 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 5923, ["name"] = "Rockcrawler Chasm", ["orderIndex"] = 3, ["flags"] = 0 } } },
[42429] = { ["id"] = 42429, ["name"] = "Memories of Ebonchill", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7879, ["storyline"] = { 42429 }, ["description"] = "Is that Ebonchill you've got there? Alodi's old staff? My my my... <Cough> In the days of the first guardian, all the members of the Council of Tirisfal granted their powers to the young mage in the hopes that he could overcome the Legion. <Wheeze> None of them are alive today... but that staff of yours remembers. Search the streets of Dalaran below for reflections of the former council members. Their memories may empower you as they once did Alodi. Seek them out and speak with one!", ["objectivesText"] = "Find a Reflection of the Council of Tirisfal in Dalaran City. Speak with one to receive his or her wisdom. Progress: Seek out the memories of the former Council members. None are here in the upper floors of the tower, and none would be in the sewers. <Cough> Check the public squares, the inns, the lower floors of the tower, the streets... A sharp eye is your ally.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 127857, 128820, 128862, 138783, 139506, 139749, 139751, 139754, 140517, 140927, 237812, 242558, 242582 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard" },
