[42590] = { ["id"] = 42590, ["name"] = "Moozy's Reunion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39323, 39572, 42590 }, ["description"] = "You will never know how thankful we are to you, <race>. Because of you, Moozy and my husband are safe. I won't let either of them out of my sight! I am sorry to ask one last favor of you, but do you think you could find my mother and bring her here so she can see that her grandchild is safe? Her name is Ethel, and her home is on the northern bluff of Thunder Totem.", ["objectivesText"] = "Find Ethel Waterwise and reunite her with her family at the Hammer's Cradle in Thunder Totem. Progress: Thank you for your kindness. Truly.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812, 245453 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 96084, ["x"] = 0.4, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 96084, ["x"] = 0.4, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7731 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 750, ["questLines"] = { { ["id"] = 5914, ["name"] = "Moozy's Family Reunion", ["orderIndex"] = 2, ["flags"] = 0 } } },
