[42970] = { ["id"] = 42970, ["name"] = "The Diamond King", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 40717, 40755, 42970 }, ["series"] = { 40755 }, ["description"] = "Me brother Magni, once King o' Ironforge, got changed into a diamond statue by a titan ritual. He's stood frozen in the belly o' the city fer years. But I just got word that he's up and around... sayin' he knows somethin' 'bout how to beat the Legion! Look, <name>, I dunno if Magni's crazy, or if that's even really him. But if there's even a chance he kin help us... I'm told he muttered the name Ulduar . That's where I'm headed! I'd be obliged if you an' Khadgar were ta join me.", ["objectivesText"] = "Go with Brann and Khadgar to Ulduar and hear Magni Bronzebeard's message.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 113655, ["x"] = 0.412, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 101547, ["x"] = 0.47, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 241, ["name"] = "Legion Launch Events - Week 2", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 258, ["name"] = "Legion Launch Events - Week 2", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42971] = { ["id"] = 42971, ["name"] = "Controlling the Elements", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 42971 }, ["description"] = "Come closer, <race>. Ragnaros in the Firelands, Al'Akir in his Throne of the Four Winds, and Neptulon in Throne of the Tides. They have been thorns in my hide since the world was new. Prove to me your strength over the weaker elements, and I shall teach you how to display your power for all to see.", ["objectivesText"] = "Retrieve Remnants of Fire, Water, and Air, and reach Revered status with Therazane . Progress: Prove your mastery over magic and the elements, <race>.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 60816, 65907, 133160, 138792, 138951, 138952, 138953 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42465, ["x"] = 0.563, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard" },
[42978] = { ["id"] = 42978, ["name"] = "A Royal Audience", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 42978, 42982 }, ["description"] = "<name>, My father lived by the sword, as you do. He taught me that if we truly want peace for our kingdom then we must be willing to fight to preserve it, as you have fought. You have demonstrated valor of the highest order - bravery unsurpassed in the ranks of the Alliance. Valor that must be recognized. Please join me in Stormwind Keep at once so that you can be properly rewarded for your service. - King Anduin Wrynn", ["objectivesText"] = "Report to King Anduin Wrynn in Stormwind Keep.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 138992 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 109466, ["x"] = 0.855, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.855, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 198, ["name"] = "Champion of the Alliance", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 138992 } },
[42982] = { ["id"] = 42982, ["name"] = "The Victor's Spoils", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 42978, 42982 }, ["description"] = "It takes a true hero to put their life on the line day after day in defense of their home so that others do not have to. You have dutifully safeguarded the people and interests of the Alliance, never faltering in your courage or devotion. As a small token of our appreciation for your valiance, please turn to the gathered heroes before you, raise your weapon high, and be recognized.", ["objectivesText"] = "Raise your weapon and be recognized in Stormwind Keep. Progress: Thank you, <name>. Thank you for everything.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 109466, ["x"] = 0.855, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 109466, ["x"] = 0.855, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.855, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 198, ["name"] = "Champion of the Alliance", ["orderIndex"] = 1, ["flags"] = 0 } } },
[42985] = { ["id"] = 42985, ["name"] = "A Royal Audience", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1497, ["mapID"] = 90, ["storyline"] = { 42985, 42987 }, ["description"] = "<name>, Those who do not stand with the Horde stand against it. You, champion, have cut down such enemies in droves. I admire your dedication. It is through you that we will rise up, more powerful than ever, and put the Alliance in their place once and for all. Join me in the Undercity at once. Your victories must be met with due reward. - Warchief Sylvanas Windrunner", ["objectivesText"] = "Report to Warchief Sylvanas Windrunner in the Undercity.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 138996 }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 109471, ["x"] = 0.58, ["y"] = 0.915 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.915 }, ["mapCandidates"] = { ["npc"] = { 90 }, ["zone"] = { 1497 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 90, ["questLines"] = { { ["id"] = 199, ["name"] = "Champion of the Horde", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 138996 } },
[42987] = { ["id"] = 42987, ["name"] = "The Victor's Spoils", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1497, ["mapID"] = 90, ["storyline"] = { 42985, 42987 }, ["description"] = "We will never be dominated so long as you stand at the front of our lines. Together we will slaughter anyone who stands in our way. You have sacrificed as much as any in the name of the Horde. I will not let your dedication go unnoticed. Face your fellow champions, <name>. Face them, and be recognized.", ["objectivesText"] = "Raise your weapon and be recognized in the Undercity. Progress: You have pleased me this day.", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 109471, ["x"] = 0.58, ["y"] = 0.915 } }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 109471, ["x"] = 0.58, ["y"] = 0.915 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.915 }, ["mapCandidates"] = { ["npc"] = { 90 }, ["zone"] = { 1497 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 90, ["questLines"] = { { ["id"] = 199, ["name"] = "Champion of the Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
