[43370] = { ["id"] = 43370, ["name"] = "A New Invention", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 43370 }, ["description"] = "I have been experimenting with technology that allows you to alter the structure of beasts, specifically with how they look.", ["objectivesText"] = "I should be able to create an item that allows you to change the appearance of Hati, but the components for such an item are rare. The Squallhunters from Stormheim have a Stormy Gland , and the Stoneblood Harpies near Thas'talah in Val'sharah have Pristine Harpy Feathers that I need. The Hatecoil Naga near the Ruins of Nar'thalas in Azsuna are said to have Reflective Scales , and finally I need an Essence of Pure Spirit from the Seabound Mystics in the Blind Marshlands of Highmountain. Progress: This is my most magnificent invention I have made. In the last 10 minutes.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 138393, 139349, 139384, 139385, 139386 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 110424, ["x"] = 0.4455, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 110424, ["x"] = 0.4455, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4455, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard" },
