[43461] = { ["id"] = 43461, ["name"] = "A Time to Reflect", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 43461 }, ["description"] = "It is time to reflect on the events that have brought us to this moment. A celebration of our great history and the events that shape it.", ["objectivesText"] = "Correctly answer one of Ju'Pa's questions about the history of Azeroth. Progress: Let us speak, then, of events that have already come to pass.", ["rewardGold"] = 1123600, ["rewardXP"] = 2830, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 110035, ["x"] = 0.365, ["y"] = 0.7445 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 110035, ["x"] = 0.365, ["y"] = 0.7445 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.7445 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4063 } },
[43471] = { ["id"] = 43471, ["name"] = "The Historians", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 440, ["mapID"] = 84, ["storyline"] = { 43471 }, ["description"] = "<name>, each year I visit Stormwind to help adventurers like you reflect on our shared history. While our eyes must always be trained on the future, we must be mindful of our past. Come visit me in the Stormwind Royal Library and we can speak more.", ["objectivesText"] = "Meet with Historian Llore in the Royal Library of Stormwind.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 139409 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 110034, ["x"] = 0.845, ["y"] = 0.253 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.845, ["y"] = 0.253 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne", ["startItems"] = { 139409 } },
