[43550] = { ["id"] = 43550, ["name"] = "Court of Stars: Into the Court of Stars", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 43550 }, ["description"] = "The weather is perfect for a party, isn't it? Travel to the Court of Stars , where the Grand Magistrix herself may appear among her nobles to reassure them of the need for all the Legion patrols.", ["objectivesText"] = "Defeat Advisor Melandrus in Court of Stars .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139457, 139471, 139472, 139473, 139474, 139475, 139476, 139477, 139478, 139479, 139480, 140147, 140163, 140164, 140171, 140172, 140177, 142340, 143328, 143479, 147501, 147505, 147509 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "dungeon", ["startItems"] = { 139472 } },
[43551] = { ["id"] = 43551, ["name"] = "Darkheart Thicket: Into Darkheart Thicket", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 739, ["storyline"] = { 43551 }, ["description"] = "Beneath the boughs of Shaladrassil, Xavius extends his power to twist and torment the once-pure druid grove. Not only this, but Xavius has taken a prize from among the druids, and his revenge will be slow and painful. We should go to Darkheart Thicket and stop his wicked plans.", ["objectivesText"] = "Defeat the Shade of Xavius in Darkheart Thicket . Progress: How are you finding the Darkheart Thicket ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139473 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 139 } }, ["questType"] = "dungeon", ["startItems"] = { 139473 } },
[43552] = { ["id"] = 43552, ["name"] = "Eye of Azshara: Into the Eye of Azshara", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["storyline"] = { 43552 }, ["description"] = "Our investigation found that the naga, under the orders of Queen Azshara herself, are preparing to summon a powerful entity to unleash Azshara's power across the Broken Isles. Travel to the Eye of Azshara , and put a stop to the ritual.", ["objectivesText"] = "Defeat the Wrath of Azshara in Eye of Azshara .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139474, 141179 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "dungeon", ["startItems"] = { 139474 } },
[43553] = { ["id"] = 43553, ["name"] = "Maw of Souls: Into the Maw of Souls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 739, ["storyline"] = { 43553 }, ["description"] = "Our scouts report that the vrykul damned are forced to sail aboard the Naglfar, a ship built of death. Travel to the Maw of Souls and confront Helya, before she collects any more poor, unfortunate souls.", ["objectivesText"] = "Defeat Helya in Maw of Souls .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139475, 141194 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7745 } }, ["questType"] = "dungeon", ["startItems"] = { 139475 } },
[43554] = { ["id"] = 43554, ["name"] = "Neltharion's Lair: Into Neltharion's Lair", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 739, ["storyline"] = { 43554 }, ["description"] = "Our scouts found that not only have the drogbar obtained a Titan relic, but also they've amassed an army large enough to threaten the overworld. Delve underground and stop the Underking before he can unleash the might of his drogbar army.", ["objectivesText"] = "Defeat Dargrul in Neltharion's Lair .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139476, 141181 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7745 } }, ["questType"] = "dungeon", ["startItems"] = { 139476 } },
[43555] = { ["id"] = 43555, ["name"] = "The Arcway: Into the Arcway", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 43555 }, ["description"] = "The Arcway is even more vast than we thought, and holds many dangers. If we have any hope of taking the city, we must first see to the underground. Enter The Arcway and clear out any, and all enemies.", ["objectivesText"] = "Defeat Advisor Vandros in The Arcway .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139477, 141182 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "dungeon", ["startItems"] = { 139477 } },
[43556] = { ["id"] = 43556, ["name"] = "Vault of the Wardens: Into the Vault of the Wardens", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 739, ["storyline"] = { 43556 }, ["description"] = "It's worse than we thought within the Vault of the Wardens . The prisoners have become the jailers, and have completely taken over the vault. However, our intelligence reports that Cordana Felsong herself may be there. Enter the Vault of the Wardens and cleanse the place of evil.", ["objectivesText"] = "Defeat Cordana Felsong in Vault of the Wardens .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139478, 141163 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7543 } }, ["questType"] = "dungeon", ["startItems"] = { 139478 } },
[43557] = { ["id"] = 43557, ["name"] = "Assault on Violet Hold: Into the Violet Hold", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["storyline"] = { 43557 }, ["description"] = "The Violet Hold contains some of the Lich King's most powerful servants, and is at risk of being overrun by Legion agents. We must go there and thwart the demons before any of the prisoners can be set free.", ["objectivesText"] = "Defeat the leader of the Assault on Violet Hold .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139479, 141184 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "dungeon", ["startItems"] = { 139479 } },
[43558] = { ["id"] = 43558, ["name"] = "Bindings of the Windlord", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 43558 }, ["series"] = { 43560, 43796, 44093, 44094, 44095, 44096, 44097, 94932 }, ["description"] = "With Thunderaan risen again as the lord of Skywall, there may indeed be an arrangement you can make in exchange for those wretched implements. But one binding is of no use on its own. Return to me with both bindings, and with powerful enough ore to bind them, and I will arrange your audience with Thunderaan the Windlord.", ["objectivesText"] = "Retrieve both Bindings of the Windlord and 10 Infernal Brimstone . Progress: Yes, <race>?", ["rewardGold"] = 1239200, ["rewardXP"] = 12280, ["rewardItems"] = { 124444, 139466, 139468, 139536, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92218, ["x"] = 0.408, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92218, ["x"] = 0.408, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard" },
[43560] = { ["id"] = 43560, ["name"] = "Audience with the Windlord", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 43560 }, ["series"] = { 43558, 43796, 44093, 44094, 44095, 44096, 44097, 94932 }, ["description"] = "I have kept my promise. Thunderaan the Windlord awaits. Know that if betrayal is in your heart, the Windlord will not be deceived. Be silent, and perhaps your audience shall be a fortunate one.", ["objectivesText"] = "Witness Thunderaan .", ["rewardItems"] = { 139536, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92218, ["x"] = 0.408, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 110990, ["x"] = 0.41, ["y"] = 0.806 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard" },
[43561] = { ["id"] = 43561, ["name"] = "I Believe I Can Fly!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 43561 }, ["description"] = "Let's not bother explaining how this happened, just know that I have the plan of all plans to escape this... this... <Looks over his hand-crafted outfit, then quickly glances to a pile of droppings nearby.> This place stinks! But you can help! These feathers here will help craft my escape plan. If you wouldn't mind, I'm sure there's enough for the both of us!", ["objectivesText"] = "Collect 6 Molted Feathers for Snicarus Dungleflight.", ["rewardItems"] = { 139500 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
