[43587] = { ["id"] = 43587, ["name"] = "Leyline Feed: Elor'shan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["storyline"] = { 43587 }, ["description"] = "<The leyline feed appears to be intact and undamaged, but is not functioning. An infusion of Ancient Mana should be enough to render it operational again.>", ["objectivesText"] = "Infuse the leyline feed with Ancient Mana . Progress: <The leyline feed pulses softly.>", ["rewardXP"] = 6140, ["rewardItems"] = { 140317, 140318, 141652, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[43588] = { ["id"] = 43588, ["name"] = "Leyline Feed: Kel'balor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["storyline"] = { 43588 }, ["description"] = "<This feed appears to draw power from the leyline in order to become fully operational. You should be able to imbue it with mana, but it will take a few minutes to draw enough leyline energy to accept the infusion. Beware, for creatures may notice the surge of arcane energy...>", ["objectivesText"] = "Defend the Leyline Feed and infuse it with Ancient Mana . Progress: <The leyline feed pulses softly.>", ["rewardXP"] = 6140, ["rewardItems"] = { 140317, 140318, 141652, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
