[43595] = { ["id"] = 43595, ["name"] = "To Honor the Fallen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39984, 40044, 40046, 43595, 43596 }, ["description"] = "Souls are not the only plunder Helya craves, and the kvaldir are ever eager to please. Among their spoils are the venerable blades of fallen heroes who dared stand against Helya's minions. These blades belong in a place of honor, not among their wretched kind. Reclaim the blades, for the honor of the Tideskorn!", ["objectivesText"] = "Collect 8 Ancient Tideskorn Blades from the kvaldir in Helmouth Shallows. Progress: Do you have the blades?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 29108, 29109, 139539, 190454, 191983, 191984, 191986, 191987, 191988, 191989, 191990, 191991, 191992, 191993, 191994, 191995, 191996, 191997, 191998, 191999, 192000, 192001, 192002, 192003, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192014, 192015, 192017, 192018, 192020, 192024, 192031, 192033, 192037, 193477, 197923, 197931, 197932, 197937, 197939, 197941, 197942, 197943, 197955, 197956, 197957, 198407, 198451, 198489, 205423, 205682, 209837, 209839, 217242, 217243, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97973, ["x"] = 0.59, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97973, ["x"] = 0.59, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5924, ["name"] = "The Fate of Tideskorn Harbor", ["orderIndex"] = 3, ["flags"] = 0 } } },
[43596] = { ["id"] = 43596, ["name"] = "Maw of Souls: Piercing the Mists", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39984, 40044, 40046, 43595, 43596 }, ["description"] = "In a time before memory, the Naglfar was the prize of Helya 's fleet. It would seem that it has lived on to serve her once more. Now, the dread ship sails the sea of souls, and cuts through the mist unseen by the living. The kvaldir must have a way to summon her, and this is what you must seek. Find her berth and board the Naglfar. Put an end to the dread ship, and the souls of the Tideskorn may be redeemed.", ["objectivesText"] = "Defeat Helya in the Maw of Souls dungeon, then return to Havi in Valdisdall Progress: Is it done?", ["rewardGold"] = 1123600, ["rewardXP"] = 12280, ["rewardItems"] = { 140618, 140619, 140620, 140621, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 }, { ["mapID"] = 634, ["npcID"] = 97973, ["x"] = 0.59, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5924, ["name"] = "The Fate of Tideskorn Harbor", ["orderIndex"] = 4, ["flags"] = 0 } } },
