[43643] = { ["id"] = 43643, ["name"] = "Secrets of the Axes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["storyline"] = { 43643 }, ["description"] = "Battlelord, I have a request. Find me inspiration! An axe whose form has seen a truly astounding amount of battle, wielded by one of the world's most powerful warriors. Both weapon and owner forged together in the crucible of war. Find this hero and their weapon, and convince them to come here.", ["objectivesText"] = "Search the Broken Isles for the greatest axe wielding warrior you know. Progress: You've found them?", ["rewardItems"] = { 139578, 140133, 140161, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard" },
