[43892] = { ["id"] = 43892, ["name"] = "Sealing Fate: Order Resources", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 43892 }, ["objectivesText"] = "Progress: These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Your order will certainly not miss these extra resources, but I must ask: When does it end? Will you ever stop risking others lives just to satisfy your greedy nature? You can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[43893] = { ["id"] = 43893, ["name"] = "Sealing Fate: Stashed Order Resources", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 43893 }, ["objectivesText"] = "Progress: Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be easier for you? I leave the choice up to you. Remember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[43894] = { ["id"] = 43894, ["name"] = "Sealing Fate: Extraneous Order Resources", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 43894 }, ["objectivesText"] = "Progress: Four times the cost of the first for only one seal. Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice. Remember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[43895] = { ["id"] = 43895, ["name"] = "Sealing Fate: Gold", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 43895 }, ["objectivesText"] = "Progress: These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Gold is indeed treasure, but additional treasure for gold? That is the offer I present. Remember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[43896] = { ["id"] = 43896, ["name"] = "Sealing Fate: Piles of Gold", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 43896 }, ["objectivesText"] = "Progress: Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be easier for you? I leave the choice up to you. Remember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[43897] = { ["id"] = 43897, ["name"] = "Sealing Fate: Immense Fortune of Gold", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 43897 }, ["objectivesText"] = "Progress: Four times the cost of the first, but for only one seal. Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice. Remember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[43898] = { ["id"] = 43898, ["name"] = "Preparing to Move", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "Thanks to your tireless efforts the Heart of Zin-Azshari is ready to withstand the full power of the Legion. The final destination in our journey has stood defiantly in front of us from the moment we began - the Nighthold, now home to none other than Gul'dan himself. Before we move on the hold, we should reunite with the Moon Guard in Shal'Aran - we still have need of their skills, and I would wager that they have unfinished business with their former brothers and sisters.", ["objectivesText"] = "Meet Archmage Kalec in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 111814, ["x"] = 0.625, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 634, 680 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 29, ["flags"] = 0 } } },
[43902] = { ["id"] = 43902, ["name"] = "The Emerald Nightmare: Fall of Cenarius", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8026, ["mapID"] = 739, ["storyline"] = { 43902 }, ["description"] = "While we know that the Nightmare bends the boundary between reality and dream, there is no doubt of the threat upon us. Our own allies have fallen into darkness.", ["objectivesText"] = "Defeat Cenarius in the Emerald Nightmare . Progress: How are you finding the challenges of the Emerald Nightmare ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139484, 140163 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 8026 } }, ["questType"] = "raid", ["startItems"] = { 140163 } },
