[43937] = { ["id"] = 43937, ["name"] = "Seeking Refuge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["mapID"] = 680, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The Nightfallen in Suramar were once a part of the Nightborne, but have been exiled by their former brethren and cut off from the Nightwell. I believe they could be valuable allies in our quest if you can turn them to our side. I know only that they have gone into hiding somewhere in Suramar. If you can convince the Nightfallen to aid us, they may be able to offer the Moon Guard and us both refuge right under the Legion's nose.", ["objectivesText"] = "Complete the \"Nightfall\" storyline in Suramar, then meet Archmage Kalec in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 15, ["flags"] = 0 } } },
[43938] = { ["id"] = 43938, ["name"] = "Focusing Our Efforts", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40603, 40608, 40613, 40614, 40615, 40668, 40672, 40673, 40675, 40678, 43496, 43501, 43503, 43505, 43514, 43517, 43518, 43519, 43520, 43521, 43522, 43523, 43524, 43525, 43526, 43527, 43528, 43530, 43531, 43532, 43533, 43581, 43898, 43937, 43938 }, ["description"] = "The Nightfallen in Suramar were once a part of the Nightborne, but have been exiled by their former brethren and cut off from the Nightwell. I believe they could be valuable allies in our quest if you can turn them to our side. I know only that they have gone into hiding somewhere in Suramar. Afterward, seek out the Moon Guard in the northern reaches of Suramar. They, too, could be valuable allies in our cause... if they still oppose the Legion as they once did many years ago.", ["objectivesText"] = "Complete the \"Nightfall\" and \"Moon Guard Stronghold\" storylines in Suramar, then meet Archmage Kalec in Shal'Aran.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 110773, ["x"] = 0.48, ["y"] = 0.255 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111826, ["x"] = 0.395, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.255 }, ["mapCandidates"] = { ["npc"] = { 630, 680 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 205, ["name"] = "Balance of Power", ["orderIndex"] = 13, ["flags"] = 0 } } },
