[44055] = { ["id"] = 44055, ["name"] = "They Have A Pitlord", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 44055 }, ["description"] = "The Feltotem are not the first to embrace the temptations of the Burning Legion. And they will not be the last. But in their arrogance, they have conjured a pit lord. Will you join us in battle against this beast? The power of your artifact and skill could prove invaluable against such a creature.", ["objectivesText"] = "Defeat Kuglaroth .", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 140721, 140722, 140723, 140724, 140725, 140726, 140727, 140728, 237812 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 108504, ["x"] = 0.298, ["y"] = 0.4 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 108504, ["x"] = 0.298, ["y"] = 0.4 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.4 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[44057] = { ["id"] = 44057, ["name"] = "A \"Noble\" Event", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 739, ["storyline"] = { 44057 }, ["series"] = { 44058 }, ["description"] = "The invitation appears to be for an exclusive fox hunt. They plan to hunt Volpin, a rare, elusive fox somewhere in the Broken Isles. Perhaps we can take advantage of this? We need to gather more information about this hunt, but we should do so without alerting the Nightborne to your plans. Your champions can act in your stead and further investigate where the hunt will be.", ["objectivesText"] = "Send champions on missions to investigate the hunt. Progress: Have your champions discovered anything about the fox hunt?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 121751, 124124, 137564, 137573, 140226, 140495, 140496, 140561, 140562, 140563, 141639, 147416, 147418, 237812, 249714 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["startItems"] = { 140495 } },
[44058] = { ["id"] = 44058, ["name"] = "Volpin the Elusive", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["mapID"] = 739, ["storyline"] = { 44058 }, ["series"] = { 44057 }, ["description"] = "According to the map, the fox hunt will start at the Feathermane Hunting Grounds in Suramar . If the Nightborne succeed, they will kill Volpin, a fox that is the last of his kind in the Broken Isles. Travel to the Hunting Grounds, and interrupt the hunt.", ["objectivesText"] = "Interrupt the fox hunt.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137564, 137573, 140495, 140496, 140561, 140562, 140563 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7834 } }, ["questType"] = "standard" },
