[44174] = { ["id"] = 44174, ["name"] = "The Very Best", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 44174 }, ["description"] = "This alignment of the stars is truly a strange one, causing the tiniest of creatures to gain unnatural aptitude. None of our sages can explain the phenomenon, but cunning tamers have much to gain, especially by testing their skills against those of their peers.", ["objectivesText"] = "Defeat 5 players through Find Battle with a team of level 25 pets. Progress: I foresee that you will travel across the land, searching far and wide. It's your destiny.", ["rewardItems"] = { 122457 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
