[44179] = { ["id"] = 44179, ["name"] = "Treasure", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44179 }, ["description"] = "There is a strange energy in the air. I feel as if a force is growing, pressing down on us. It is worrisome. Valtrois works most closely with the sources of power in this room. Speak to her. Ask if there is anything to be concerned with.", ["objectivesText"] = "Speak with Valtrois.", ["rewardGold"] = 561800, ["rewardXP"] = 4150, ["rewardItems"] = { 2842, 3342, 3343, 39336, 39380, 39433, 39454, 57549, 57571, 57572, 57574, 59198, 59199, 59200, 62958, 62959, 62960, 62961, 65924, 65949, 65973, 65994, 86428, 131459, 131474, 156948, 157007, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44182] = { ["id"] = 44182, ["name"] = "City Under Siege", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 12, ["mapID"] = 42, ["storyline"] = { 44182, 44184, 44421, 44500, 44663 }, ["series"] = { 44184, 44421, 44500 }, ["description"] = "<Khadgar's voice erupts from the elemental once again.> Obtaining information on the Pillars of Creation before the Legion could stop us was a considerable victory. It won't bring back those we lost on the Broken Shore, but I believe it will help us avenge them. Dalaran has become a focal point of the Legion's assault. Your presence here is crucial. If the demons are putting this much effort into attacking the city, it means Dalaran will play a pivotal role in the struggle to save Azeroth.", ["objectivesText"] = "Meet Khadgar at the Chamber of the Guardian in Dalaran.", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["rewardItems"] = { 44934, 237812 }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 113986, ["x"] = 0.475333, ["y"] = 0.745333 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.475333, ["y"] = 0.745333 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 42, ["questLines"] = { { ["id"] = 242, ["name"] = "Legion Launch Events - Week 3", ["orderIndex"] = 0, ["flags"] = 0 } } },
