[44204] = { ["id"] = 44204, ["name"] = "Seal their Fates", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 44204 }, ["description"] = "Ever feel like luck just isn't on your side? Well maybe I can help you with that. There are some interesting items I've come across in my travels which can be used to swing the dice in your favor, or at least give you another shot at it. It takes some time, and supplies are hard to come by, but I can get you one of them... for a price?", ["objectivesText"] = "Place a work order for a Seal of Broken Fate.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[44205] = { ["id"] = 44205, ["name"] = "Shape Your Fate", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["storyline"] = { 44205 }, ["description"] = "The whims of the spirits can be guided, I have seen it. There were whispers of an item, a way to change the path of destiny. I heard dem, and I went looking. For many years I listened to those whispers on the wind until one day they showed me the way. This is what I offer you. It will take some time, and some valuable resources, but I can perform the ritual to allow you to control this power. Well? Are you ready?", ["objectivesText"] = "Place a work order for a Seal of Broken Fate. Progress: Place a work order for a Seal of Broken Fate.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard" },
[44206] = { ["id"] = 44206, ["name"] = "The Ascended", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["storyline"] = { 44206 }, ["description"] = "These shaman have spent their lives dedicated to the path of Air, Water or Fire. On your request, we will beseech the elements to Ascend them, becoming a powerful, if short lived, force to deploy in this war against the Legion. The ritual of ascension is not to be requested lightly.", ["objectivesText"] = "Place a request to recruit Ascendants.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 174293, 177054, 178157, 179944, 180647 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard" },
[44207] = { ["id"] = 44207, ["name"] = "Portal Full of Shiny Things", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["storyline"] = { 44207 }, ["description"] = "When I heard the Hall of the Guardian was open again, I said to myself \" Minuette , this is your chance!\" I rushed over here thinking I'd be hurled into the front lines. Imagine it, me, little old me, assaulting Demons with missiles, blinking away from Fel Meteors. That would be brilliant! Instead, they send me over here and say \"Hey, open up some portals so we can throw things through, would you?\" At least I get to charge something for it.", ["objectivesText"] = "Place a work order for Champion armaments and equipment.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard" },
[44208] = { ["id"] = 44208, ["name"] = "Fate and Time", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["storyline"] = { 44208 }, ["description"] = "For years we wondered, we conjectured, that it was possible to control the twisting, slipping, streaming threads of fate and destiny. These books tell of powerful mages who embraced the manipulation of time. No no, not like Time Warp, they would laugh at us, think us silly amateurs. No, they were true Chronomancers. The only spell we've been able to determine is a conjuration. It calls forth what they termed a \"Seal of Fate\". This allowed them to repeat their actions. Let us try it out shall we?", ["objectivesText"] = "Place a work order for a Seal of Broken Fate.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard" },
[44210] = { ["id"] = 44210, ["name"] = "The Might of Dalaran pt2", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44210 }, ["description"] = "Yes, now once the crystal has been empowered, collect it here, and use it to unleash the power of our mages on a world quest.", ["objectivesText"] = "Collect the Focusing Crystal and use it to complete a world quest.", ["rewardItems"] = { 140038 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44211] = { ["id"] = 44211, ["name"] = "Unseen Armaments", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 44211 }, ["description"] = "If we gonna win dis war, we need to get these Champions of ours better equipment. It won't be cheap, or easy, but I can get dem for you.", ["objectivesText"] = "Place a work order for Champion armaments and equipment.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 110412, ["x"] = 0.584857, ["y"] = 0.487143 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 110412, ["x"] = 0.584857, ["y"] = 0.487143 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.584857, ["y"] = 0.487143 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard" },
[44212] = { ["id"] = 44212, ["name"] = "Unseen Fate", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 44212 }, ["description"] = "Our path is a winding, twisting road full of peril. Yet did you know it can be walked many times? There is an item of great power available to us. It allows us another opportunity, a second chance. Do you wish to acquire one?", ["objectivesText"] = "Place a work order for a Seal of Broken Fate.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 110816, ["x"] = 0.434667, ["y"] = 0.479667 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 110816, ["x"] = 0.434667, ["y"] = 0.479667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.434667, ["y"] = 0.479667 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard" },
[44213] = { ["id"] = 44213, ["name"] = "You Will Be Prepared!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8022, ["storyline"] = { 44213 }, ["description"] = "<name>, your strength and leadership inspires awe in all of us! The Illidari are prepared to furnish you with a full set of armor to aid in the fight against the Burning Legion. Continue expanding your influence across the Broken Isles, and we may yet achieve victory.", ["objectivesText"] = "Accept a gift from the Illidari.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 139718, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard" },
[44218] = { ["id"] = 44218, ["name"] = "Champion Armaments", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["storyline"] = { 44218 }, ["description"] = "This war against the Legion won't be won easily. We will need armaments and equipment for our Champions. Give the order sir, I'll get the word out and have a shipment brought in.", ["objectivesText"] = "Place a work order for Champion armaments and equipment.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard" },
[44219] = { ["id"] = 44219, ["name"] = "Fate's Blessing", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["storyline"] = { 44219 }, ["description"] = "The Light's blessing is powerful. We use it to mend, to defeat our enemies... we even use it to resurrect our allies. Did you know it can also be used to alter your destiny? The Silver Hand is able to procure a valuable item to help you in our war against the Legion. This Seal can be used at the most opportune moments to grant another chance at destiny. Shall we procure one for you?", ["objectivesText"] = "Place a work order for a Seal of Broken Fate.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard" },
[44221] = { ["id"] = 44221, ["name"] = "Champion Armaments", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["storyline"] = { 44221 }, ["description"] = "A warrior lives and dies by his weapons and armor. For a price, we can provide you with a shipment for armaments to equip your Champions with. Do we have a deal?", ["objectivesText"] = "Place a workorder for Champion armaments and equipment.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard" },
