[44306] = { ["id"] = 44306, ["name"] = "Blessings of the Order", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7834, ["storyline"] = { 44306 }, ["description"] = "Though it takes time and resources, we are able to, of course, Bless your champions. With this Blessing, their success on their adventures will be greatly improved.", ["objectivesText"] = "Request a Blessing of the Order.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7834 } }, ["questType"] = "standard" },
[44338] = { ["id"] = 44338, ["name"] = "Goddess Watch Over You", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["series"] = { 44337, 44448 }, ["description"] = "I may have found a \"key\" to unlock Light's Heart, <name>. I was going through some ancient cosmology tomes when I stumbled upon a passage indicating that the prime naaru may have been created by Elune during the great ordering of Light and Shadow. If Elune did create Xe'ra, then it stands to reason that we could use the Tears of Elune to unlock the secrets of Light's Heart. Now it falls upon you to recover the Tears of Elune from Val'sharah.", ["objectivesText"] = "Recover the Tears of Elune from Val'sharah.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 8, ["flags"] = 0 } } },
[44351] = { ["id"] = 44351, ["name"] = "FLAG: Upgrade First Crafted Item", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 44351 }, ["rewardGold"] = 194000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44400] = { ["id"] = 44400, ["name"] = "Assault on Violet Hold: Purple Pain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7996, ["storyline"] = { 44400 }, ["description"] = "Again! It happened again! Sure, it's the Legion that staged the prison breakout this time, but I *told* them it was a bad idea to keep some of the most dangerous beings on Azeroth in a prison inside our city! We can talk about relocating later, I suppose. Right now, we've got some... pacification to tend to. Can you help?", ["objectivesText"] = "Repel the Assault on Violet Hold. Progress: Oh, no. Don't tell me something ELSE has gone wrong?!", ["rewardGold"] = 1239200, ["rewardXP"] = 2830, ["rewardItems"] = { 141356, 141357, 141358, 141359, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7996 } }, ["questType"] = "dungeon" },
[44406] = { ["id"] = 44406, ["name"] = "Aggra's Guidance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["storyline"] = { 44406 }, ["series"] = { 43945 }, ["description"] = "<class>t, have you met the shaman Aggra ? Born of a shattered world, she learned the ways of the elements among the Mag'har orcs of Outland. On the eve of the Cataclysm she took it upon herself to complete Thrall's shamanistic training. Our younger initiates are fortunate to have her among us to guide them. If you wish to seek out a second artifact, Aggra can assist you. She is training new recruits above us on the Storm's Eye Overlook.", ["objectivesText"] = "Seek out Aggra at the Storm's Eye Overlook within the Heart of Azeroth.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard" },
[44411] = { ["id"] = 44411, ["name"] = "Strange Humming Crystal", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 44411 }, ["description"] = "<You place the crystal to your ear and hear the disharmonious din of hundreds of voices speaking at once. Perhaps Khadgar might know more about this strange gem.>", ["objectivesText"] = "Take the Strange Humming Crystal to Khadgar in Dalaran .", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 141349, 141350, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["startItems"] = { 141349 } },
[44412] = { ["id"] = 44412, ["name"] = "Enemies Everywhere", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 44412 }, ["description"] = "Hold a moment, <name>. While I look into this orb of yours, why don't you look into something for me? I have long suspected an infiltration of Dalaran but after an embarrassing encounter with a local florist I've withheld my accusations until I'm absolutely certain. Have you noticed citizens among us that seem just too mundane? Almost inhumanly so? Spies, serving dark masters, watch and wait until our backs are turned. Root them out, but try and keep it quiet.", ["objectivesText"] = "Defeat the hidden infiltrators in Dalaran . Progress: Have you disposed of our friends?", ["rewardItems"] = { 71153, 140394, 140808, 141348, 141349, 141350, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[44414] = { ["id"] = 44414, ["name"] = "Felspawns of Lothros", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8406, ["mapID"] = 793, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["series"] = { 44415, 44416 }, ["description"] = "These Felspawns are endless! I can't cut them down quickly enough to get to the dreadlord within the mausoleum. Master Illidan, will you come with me so we can take down Lothros together?", ["objectivesText"] = "Defeat Lothros . Progress: A dreadlord poses little danger to you, eh?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8406 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1646, ["db2PoiUiMapID"] = 793, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 13, ["flags"] = 1 } } },
[44415] = { ["id"] = 44415, ["name"] = "The Red Axe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8406, ["mapID"] = 793, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["series"] = { 44414, 44416 }, ["description"] = "Broxigar the Red is cornered on the bridge. I am not sure he would ever admit that he needs our help, but I feel it only proper to lend him our aid. If you wish to assist our ally, I would be humbled to accompany you in this endeavor.", ["objectivesText"] = "Close the Unstable Portals and make your way to Broxigar the Red . Progress: Our allies are strong, but our enemy is Legion!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8406 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1646, ["db2PoiUiMapID"] = 793, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 14, ["flags"] = 1 } } },
[44416] = { ["id"] = 44416, ["name"] = "Hunter of Night", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8406, ["mapID"] = 793, ["storyline"] = { 43295, 43483, 43705, 44004, 44009, 44153, 44257, 44337, 44338, 44414, 44415, 44416, 44448, 44464, 44466, 44479, 44480, 44481, 44496, 44497 }, ["series"] = { 44414, 44415 }, ["description"] = "A glorious battle indeed! If I am correct, we can expect something a bit more deadly at any moment. The Legion often uses fodder such as these to prepare the way for a more worthy foe. My axe is sharp and ready.", ["objectivesText"] = "Defeat Malvingeroth Progress: Are you sure you are a night elf? You wage battle with the ferocity of an orc!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 121802, 139902, 139932, 139962, 140002, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8406 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1646, ["db2PoiUiMapID"] = 793, ["questLines"] = { { ["id"] = 206, ["name"] = "Origins", ["orderIndex"] = 15, ["flags"] = 1 } } },
[44421] = { ["id"] = 44421, ["name"] = "Anomalous Anomalies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 44182, 44184, 44421, 44500, 44663 }, ["series"] = { 44182, 44184, 44500 }, ["description"] = "Dalaran's move to this location was intended to be a temporary measure, but we may need to depart sooner than expected. Blinking a city across the world is no mean feat. The magnitude of energies involved can lead to... unexpected side effects. Arcane anomalies are causing mischief throughout the city. Their presence could destabilize any attempt to blink again. We don't have time to let them dissipate on their own, <name>. I have a device that will help speed things along.", ["objectivesText"] = "Use Khadgar's crystal to neutralize anomalies in Dalaran.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 141411, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 113986, ["x"] = 0.475333, ["y"] = 0.745333 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 113986, ["x"] = 0.475333, ["y"] = 0.745333 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.475333, ["y"] = 0.745333 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 41, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 242, ["name"] = "Legion Launch Events - Week 3", ["orderIndex"] = 1, ["flags"] = 0 } } },
[44486] = { ["id"] = 44486, ["name"] = "Fel-Ravaged Tome", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7787, ["storyline"] = { 44486 }, ["description"] = "Much of the elven writing in the tome has been singed by fel fire. The head of the curators in Dalaran is renowned for his restoration skills. Perhaps he can treat the tome to bring it back to legibility.", ["objectivesText"] = "Bring the Fel-Ravaged Tome to Robert Newhearth in Dalaran . Progress: Oh, what's this one now?", ["rewardXP"] = 6140, ["rewardItems"] = { 141360, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7787 } }, ["questType"] = "standard" },
[44487] = { ["id"] = 44487, ["name"] = "Waterlogged Tome", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["storyline"] = { 44487 }, ["description"] = "In spite of its magical nature, the book has been damaged by water. The head of the curators in Dalaran is renowned for his abilities. Perhaps he can restore it.", ["objectivesText"] = "Bring the Waterlogged Tome to Robert Newhearth in Dalaran . Progress: What have we here?", ["rewardXP"] = 6140, ["rewardItems"] = { 141355, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 41 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Day of the Dead" },
[44488] = { ["id"] = 44488, ["name"] = "Cursed Tome", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6719, ["storyline"] = { 44488 }, ["description"] = "Much of the elven writing in the tome has been singed by fel fire. The head of the curators in Dalaran is renowned for his restoration skills. Perhaps he can treat the tome to bring it back to legibility.", ["objectivesText"] = "Bring the Fel-Ravaged Tome to Robert Newhearth in Dalaran . Progress: Oh, what's this one now?", ["rewardXP"] = 6140, ["rewardItems"] = { 141361 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[44492] = { ["id"] = 44492, ["name"] = "Leyline Apprentice", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44492 }, ["description"] = "Good work finding those additional leyline feeds. You seem rather competent - for an outlander. Allow me to share with you a few secrets about the power of the leylines. This should help you in scavenging more ancient mana from the creatures around Suramar . A grisly task, I know - which is why I leave it to you!", ["objectivesText"] = "Speak with Arcanist Valtrois .", ["rewardGold"] = 140450, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 }, { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 }, { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[44493] = { ["id"] = 44493, ["name"] = "Leyline Proficiency", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44493 }, ["description"] = "Our leyline feed grows stronger. The more powerful our feed becomes, the more I learn about ancient mana itself. Of course, as my apprentice, you may reap the benefits of my discoveries. Listen well, and I will teach you how to extract power from your enemies more reliably.", ["objectivesText"] = "Speak with Arcanist Valtrois .", ["rewardGold"] = 140450, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 }, { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 }, { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[44495] = { ["id"] = 44495, ["name"] = "Leyline Master", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44495 }, ["description"] = "You surprise me, outlander. During our first lesson about the ancient leylines, I half-expected you to be lost in daydreams of adventure, or treasure or... some such nonsense. But you have proven an apt student. Our leyline feed has grown extremely powerful. Watching it grow has taught me a great deal about the arcane, and the nature of mana. I have one final lesson that will help you find even more ancient mana.", ["objectivesText"] = "Speak with Arcanist Valtrois .", ["rewardGold"] = 140450, ["rewardXP"] = 3070, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 }, { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 }, { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[44500] = { ["id"] = 44500, ["name"] = "Author! Author!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 44182, 44184, 44421, 44500, 44663 }, ["series"] = { 44182, 44184, 44421 }, ["description"] = "We've reviewed the tome recovered from Karazhan. Though we found references to the Pillars of Creation, one piece of crucial information was omitted from the book... where to find the artifacts. Fortunately, we have access to an expert on the subject. The author, Alodi, was the first Guardian of Tirisfal. His spirit is forever bound to the Forge of the Guardian, which has been hidden in our safekeeping. I think the time has come to call him forth.", ["objectivesText"] = "Tell Khadgar to begin the ritual to summon the spirit of Alodi, the first Guardian. Progress: Alodi's knowledge of the Pillars of Creation is crucial to our campaign against the Legion.", ["rewardGold"] = 50550, ["rewardXP"] = 355, ["rewardItems"] = { 128862, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 113986, ["x"] = 0.475333, ["y"] = 0.745333 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 113986, ["x"] = 0.475333, ["y"] = 0.745333 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.475333, ["y"] = 0.745333 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 41, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 242, ["name"] = "Legion Launch Events - Week 3", ["orderIndex"] = 2, ["flags"] = 0 } } },
[44543] = { ["id"] = 44543, ["name"] = "The Battle for Broken Shore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 40522, 40605, 40607, 40760, 44092, 44543 }, ["series"] = { 39691, 40518, 40522, 40593, 40605, 40607, 40760, 40976, 40982, 40983, 41002, 43926, 44120, 44281, 44463, 44471, 44473, 44663, 95215 }, ["description"] = "This wind rider will take you to Broken Shore, <name>. May your weapon bring you many kills today. The Warchief has already made landfall, I will wager you will simply need to follow the trail of demon blood.", ["objectivesText"] = "Take the wind rider to the Broken Shore.", ["rewardItems"] = { 136582, 136583, 136584, 136586, 136587, 136588, 136589, 136590, 136591, 136595, 138764, 138765, 138766, 138767, 138768, 138769, 138770, 138771, 138772, 139292, 237812 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 100453, ["x"] = 0.572, ["y"] = 0.105 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.572, ["y"] = 0.105 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 263, ["name"] = "Legion Launch Events - Week 1", ["orderIndex"] = 0, ["flags"] = 0 } } },
[44545] = { ["id"] = 44545, ["name"] = "Pressing the Assault", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44545 }, ["description"] = "<With this Pillar of Creation safely secured, it is time to take advantage of your momentum and continue onward after the next.> <You recall that your order has gathered information that would aid you in your journey - looking it over once more before setting off would be wise.>", ["objectivesText"] = "Select your next assault point on the Broken Isles at the Command Map in your Order Hall.", ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44547] = { ["id"] = 44547, ["name"] = "Isle Hopping", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44547 }, ["description"] = "<Victory in hand, you know there are still Pillars of Creation that must be recovered if the Legion is to be defeated once and for all.> <Your order has identified uncharted regions of the Broken Isles that still house the remaining Pillars - looking over the information would help focus your next effort.>", ["objectivesText"] = "Select your next assault point on the Broken Isles at the Command Map in your Order Hall.", ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44548] = { ["id"] = 44548, ["name"] = "Scouring What Remains", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44548 }, ["description"] = "<Looking around the chamber, you know you are well on your way to gathering all of the Pillars of Creation, but your work is not yet complete.> <Your order has continued to scour the isles below for anything that might be useful - best to check in with them before embarking once more.>", ["objectivesText"] = "Select your next assault point on the Broken Isles at the Command Map in your Order Hall.", ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44549] = { ["id"] = 44549, ["name"] = "Master of the Isles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44549 }, ["description"] = "<Only one region remains from your order's carefully laid plan to assault the Broken Isles and gather the Pillars of Creation.> <Victory feels close, but studying your order's intelligence one last time couldn't hurt.>", ["objectivesText"] = "Review your remaining assault point on the Broken Isles at the Command Map in your Order Hall.", ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44563] = { ["id"] = 44563, ["name"] = "Redemption for the Fallen", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44563 }, ["description"] = "Soon the change of seasons will be upon us, and the Nightfallen will take command of their fate. You have given them hope, and set them on the path to redemption. They need you now more than ever. We all do.", ["objectivesText"] = "Reach Exalted with The Nightfallen . Progress: There is much to be done.", ["rewardGold"] = 101100, ["rewardXP"] = 3070, ["rewardItems"] = { 141685, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[44570] = { ["id"] = 44570, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 6, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 44570 }, ["description"] = "The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, <name>?", ["objectivesText"] = "Honor the Midsummer Bonfire in Spires of Arak.", ["rewardGold"] = 154900, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["mapID"] = 542, ["npcID"] = 114488, ["x"] = 0.48, ["y"] = 0.446 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.446 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 542 },
[44571] = { ["id"] = 44571, ["name"] = "Honor the Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 6, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 44571 }, ["description"] = "The Midsummer Fire Festival is a time to honor the elements. The element of fire stirs passion within us all. Many times, that passion pours out into aggressive actions. But here, in this land, we focus our passion on reverence. We will honor the flame as tradition dictates. Will you honor the flame with us, <name>?", ["objectivesText"] = "Honor the Midsummer Bonfire in Talador.", ["rewardGold"] = 154900, ["rewardXP"] = 100, ["rewardItems"] = { 23247 }, ["starts"] = { { ["mapID"] = 535, ["npcID"] = 114489, ["x"] = 0.434, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1116, ["db2PoiUiMapID"] = 535 },
