[44683] = { ["id"] = 44683, ["name"] = "Holding the Lines", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 44556, 44557, 44683, 44684, 44685, 44686, 44733, 44734, 44735, 44764, 44886, 44887, 44944, 45422 }, ["description"] = "Karazhan sits upon a confluence of ley lines. It's why this location was chosen for the tower in the first place... a fact that has not escaped the Legion's notice. If the demons are tapping into these lines of power, they must need their energy for something particularly menacing. You must cut off their access to the ley lines if we're to have a chance of retaking the tower, <name>.", ["objectivesText"] = "Secure the Eastern Ley Line and Western Ley Line beneath Karazhan.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142450, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 114310, ["x"] = 0.47, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 114310, ["x"] = 0.47, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "group", ["activities"] = { ["groupFinder"] = { { ["id"] = 225, ["name"] = "Deadwind Pass", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 0, ["maxPlayers"] = 0 } } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 294, ["name"] = "Return to Karazhan", ["orderIndex"] = 6, ["flags"] = 0 } } },
[44684] = { ["id"] = 44684, ["name"] = "Corruption Runs Deep", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 44556, 44557, 44683, 44684, 44685, 44686, 44733, 44734, 44735, 44764, 44886, 44887, 44944, 45422 }, ["description"] = "Everything the Legion touches is marred by fingerprints of their corruption. If I can study the traces of magic they leave behind, perhaps I can discern their plans for Karazhan. This vial is specially reinforced to contain fel magic. If you bring me the essences of corrupted soil and water from near their portals, I believe we'll be closer to unraveling their scheme.", ["objectivesText"] = "Recover an Essence of Corrupted Soil and an Essence of Corrupted Water from the caverns beneath Deadwind Pass . Progress: What have we here?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 141878, 142449, 211279, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 114631, ["x"] = 0.47, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 114631, ["x"] = 0.47, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "group", ["activities"] = { ["groupFinder"] = { { ["id"] = 225, ["name"] = "Deadwind Pass", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 0, ["maxPlayers"] = 0 } } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 294, ["name"] = "Return to Karazhan", ["orderIndex"] = 7, ["flags"] = 0 } } },
[44685] = { ["id"] = 44685, ["name"] = "Reclaiming the Ramparts", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 44556, 44557, 44683, 44684, 44685, 44686, 44733, 44734, 44735, 44764, 44886, 44887, 44944, 45422 }, ["description"] = "With the ley lines protected we must move to secure the tower's perimeter. Around the tower are several locations where corruption continues to run rampant. Seek out these locations and secure them with these wards. With the progress we've made so far, bolstering our defenses should keep the remaining Legion's forces at bay just long enough for us to discover who's behind their efforts.", ["objectivesText"] = "Plant the Wards at the Eastern, Southern and Northern locations around the tower in Deadwind Pass . Progress: Has the tower been secured?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142213, 142451, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 114310, ["x"] = 0.47, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 114310, ["x"] = 0.47, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "group", ["activities"] = { ["groupFinder"] = { { ["id"] = 225, ["name"] = "Deadwind Pass", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 0, ["maxPlayers"] = 0 } } }, ["db2PoiUiMapID"] = 41, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 294, ["name"] = "Return to Karazhan", ["orderIndex"] = 8, ["flags"] = 0 } } },
[44686] = { ["id"] = 44686, ["name"] = "Thought Collection", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 44556, 44557, 44683, 44684, 44685, 44686, 44733, 44734, 44735, 44764, 44886, 44887, 44944, 45422 }, ["description"] = "While I examine these samples further, I ask that you seek out one of our patrols in the structure to the north. It appears they've captured one of the demons. Go, interrogate it. Find out anything you can. And hurry! I'm afraid time is no longer an ally.", ["objectivesText"] = "Interrogate the Captured Wyrmtongue in the structure just north of the tower in Deadwind Pass . Progress: Has it been handled, <name>?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 114631, ["x"] = 0.47, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 114631, ["x"] = 0.47, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 294, ["name"] = "Return to Karazhan", ["orderIndex"] = 9, ["flags"] = 0 } } },
[44720] = { ["id"] = 44720, ["name"] = "A Call to Action", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44720, 44721, 44729, 44771 }, ["series"] = { 44721, 44729, 44771, 44868 }, ["description"] = "<As the raven stares into your eyes, a familiar voice fills your mind.> Champion, I require your aid. It seems Helya has shown her hand. Steel yourself then come to me.", ["objectivesText"] = "Find Havi at Valdisdall.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119531, ["x"] = 0.446, ["y"] = 0.64 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.64 }, ["mapCandidates"] = { ["npc"] = { 634, 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 280, ["name"] = "Deemed Worthy", ["orderIndex"] = 0, ["flags"] = 0 } } },
[44721] = { ["id"] = 44721, ["name"] = "Helya's Conquest", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 44720, 44721, 44729, 44771 }, ["series"] = { 44720, 44729, 44771, 44868 }, ["description"] = "If Helya is making an advance on the Broken Isles, we will need to answer in turn. Go to Tideskorn Harbor and scout her forces. We will see if Helya is foolish enough to begin her campaign against me.", ["objectivesText"] = "Search Tideskorn Harbor for evidence of Helya's forces. Progress: What is Helya planning?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142535, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 280, ["name"] = "Deemed Worthy", ["orderIndex"] = 2, ["flags"] = 0 } } },
