[44729] = { ["id"] = 44729, ["name"] = "Trial of Valor: Odyn's Favor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 44720, 44721, 44729, 44771 }, ["series"] = { 44720, 44721, 44771, 44868 }, ["description"] = "The time to deal with that treacherous witch has come. I suspect you may be the one to deal the final blow, but I must be certain. See me in the Halls of Valor and we will test the strength of your will.", ["objectivesText"] = "Gain Odyn 's favor within the Trial of Valor Raid.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142533, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 92539, ["x"] = 0.602, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "raid", ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1648, ["db2PoiUiMapID"] = 807, ["questLines"] = { { ["id"] = 280, ["name"] = "Deemed Worthy", ["orderIndex"] = 3, ["flags"] = 0 } } },
