[44733] = { ["id"] = 44733, ["name"] = "The Power of Corruption", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 44556, 44557, 44683, 44684, 44685, 44686, 44733, 44734, 44735, 44764, 44886, 44887, 44944, 45422 }, ["series"] = { 44764 }, ["description"] = "The time has come at last. Deep within the cavernous underbelly of Karazhan lies a long-forgotten chamber. Based on what you learned from our demon friend, I believe this is where its mistress dwells. This demon's master must come from the highest ranks of the Burning Legion. This does not bode well for Karazhan. We need to secure Deadwind Pass , <name>. You must find this demon and destroy it.", ["objectivesText"] = "Use the disguise to gain access to the chamber, then slay Thar'zul and Elux'ara Darkscorn beneath Karazhan in Deadwind Pass . Progress: The threat must be removed.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142208, 142452, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 114310, ["x"] = 0.47, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 114310, ["x"] = 0.47, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "group", ["activities"] = { ["groupFinder"] = { { ["id"] = 225, ["name"] = "Deadwind Pass", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 0, ["maxPlayers"] = 0 } } }, ["db2PoiUiMapID"] = 42, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 294, ["name"] = "Return to Karazhan", ["orderIndex"] = 11, ["flags"] = 0 } } },
[44734] = { ["id"] = 44734, ["name"] = "Fragments of the Past", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 44556, 44557, 44683, 44684, 44685, 44686, 44733, 44734, 44735, 44764, 44886, 44887, 44944, 45422 }, ["description"] = "Though your primary objective is to liberate the tower from the Legion's hold, I have... another request. Karazhan is a place where magic and history intertwine. Moments of the past have been known to take physical form, and these forms can possess great power. As you journey through Karazhan, watch for places where memories coalesce. These fragments could provide valuable insight into what's really going on inside that tower.", ["objectivesText"] = "Collect the Soul Fragments from the Guest Chambers, Banquet Hall, Servant Quarters, Opera Hall and the Menagerie inside Karazhan. Progress: Have you recovered the fragments?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142460, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 114310, ["x"] = 0.47, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 114310, ["x"] = 0.47, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1651, ["db2PoiUiMapID"] = 822, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 294, ["name"] = "Return to Karazhan", ["orderIndex"] = 12, ["flags"] = 0 } } },
[44735] = { ["id"] = 44735, ["name"] = "Return to Karazhan: In the Eye of the Beholder", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 44556, 44557, 44683, 44684, 44685, 44686, 44733, 44734, 44735, 44764, 44886, 44887, 44944, 45422 }, ["description"] = "The Legion's intentions are clear. They intend to harness the tower's magical energy to communicate with other Legion worlds! I'm afraid we haven't much time, <name>. You must ascend the tower and destroy this monstrosity before it is too late!", ["objectivesText"] = "Defeat Viz'aduum the Watcher in Karazhan. Progress: The tower must be restored.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142454, 143551, 143552, 143555, 143556, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 114310, ["x"] = 0.47, ["y"] = 0.755 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 114310, ["x"] = 0.47, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1651, ["db2PoiUiMapID"] = 822, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 294, ["name"] = "Return to Karazhan", ["orderIndex"] = 13, ["flags"] = 0 } } },
