[44767] = { ["id"] = 44767, ["name"] = "A Celestial Invitation", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 67, ["mapID"] = 120, ["storyline"] = { 44767 }, ["description"] = "Greetings, mortal. For many years I have continued my observation of this planet. The halls of Ulduar have been hollow and silent, save for the occasional clattering whisper from the darkness. I grew so very bored of it! Thus, I have taken up this \"pet battling\" you seem so fond of. Truly, an amusing pastime that will sustain my mind for many centuries! I have been amassing my collection, scouring the stars for tiny beings of cosmic power. Come, let us do battle once more!", ["objectivesText"] = "Defeat Algalon the Observer in a pet battle. Progress: Greetings, mortal. Do you wish to engage in a battle of the tiny minions?", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 142100, 142210 }, ["ends"] = { { ["mapID"] = 120, ["npcID"] = 115307, ["x"] = 0.414667, ["y"] = 0.244667 } }, ["coords"] = { ["mapID"] = 120, ["source"] = "quest_giver", ["x"] = 0.414667, ["y"] = 0.244667 }, ["mapCandidates"] = { ["npc"] = { 120 }, ["zone"] = { 67 } }, ["questType"] = "standard", ["startItems"] = { 142210 } },
