[44917] = { ["id"] = 44917, ["name"] = "Return to Karazhan: The Tower of Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 739, ["storyline"] = { 44917 }, ["description"] = "Your champions discovered that the area surrounding Karazhan is under an invasion from the Legion. This does not bode well. Climb the tower, and defeat all in your path.", ["objectivesText"] = "Defeat Viz'aduum the Watcher in Karazhan. Progress: How are you finding the challenges of Karazhan?", ["rewardItems"] = { 142340, 142342 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["startItems"] = { 142340 } },
[44922] = { ["id"] = 44922, ["name"] = "Inside the Winter Storm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 44922 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44940 }, ["description"] = "There, it looks like there's a good spot to launch to right across from here. This path should take you all the way to the top. According to my intel, your dragons should be up there. Let's just hope that they're still in a state to help you.", ["objectivesText"] = "Grapple across from the tower and climb to the top of the mountain path.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
