[44926] = { ["id"] = 44926, ["name"] = "A Familiar Axe to Grind", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 44926 }, ["series"] = { 44927 }, ["description"] = "The construction of this blade feels familiar, but you can't quite recall where you may have seen something like it before. Perhaps someone at Chiselgrip might know more about its construction.", ["objectivesText"] = "Show the axe blade to Hoddruc Bladebender at Chiselgrip. Provided item:", ["rewardGold"] = 31500, ["rewardXP"] = 260, ["rewardItems"] = { 142344 }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 115805, ["x"] = 0.468, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["startItems"] = { 142344 } },
[44927] = { ["id"] = 44927, ["name"] = "Worth Its Weight in Steel", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 46, ["mapID"] = 36, ["storyline"] = { 44927 }, ["series"] = { 44926 }, ["description"] = "Listen, ye seem like one who may be interested in getting a copy of those axe plans. Could probably make a pretty penny at the auction house on it. But I can't just hand 'em over to ya, <lad/lass>. Not fer free. That axe blade ye brought me, I could use more of those. Good steel in those blades. Don't worry, <lad/lass>, I just need a few... What do ye say?", ["objectivesText"] = "Gather 30 Axe Blades from orcs and ogres around the Burning Steppes. Return them to Hoddruc in Chiselgrip when you've collected them all. Progress: You see, I've got a shipment ta fill and it's been slim pickin' round these parts for good metal. Those blades are just what I'm lookin' for.", ["rewardXP"] = 260, ["rewardItems"] = { 142344, 142345, 142346 }, ["starts"] = { { ["mapID"] = 36, ["npcID"] = 115805, ["x"] = 0.468, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 115805, ["x"] = 0.468, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 36, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 36 }, ["zone"] = { 46 } }, ["questType"] = "standard" },
