[44940] = { ["id"] = 44940, ["name"] = "Inside the Winter Storm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 44940 }, ["series"] = { 38312, 38318, 38342, 38405, 38410, 38412, 38413, 38414, 38473, 38611, 38612, 38613, 38614, 38615, 38617, 38618, 38624, 38778, 38808, 38810, 38811, 38815, 38816, 38817, 38818, 38823, 39592, 39593, 39594, 39597, 39652, 39788, 39791, 39796, 39803, 39804, 40568, 44922 }, ["description"] = "There, it looks like there's a good spot to launch to right across from here. This path should take you all the way to the top. According to my intel, your dragons should be up there. Let's just hope that they're still in a state to help you.", ["objectivesText"] = "Grapple across from the tower and climb to the top of the mountain path.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
