[44948] = { ["id"] = 44948, ["name"] = "Raising Your Snowfeather", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44948 }, ["description"] = "<Your snowfeather hatchling looks at you timidly. It appears to be looking to you to help it survive and grow.>", ["objectivesText"] = "Raise your Snowfeather Hatchling to level 25. Progress: Erk?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 122457, 128763, 128837, 128839, 128843, 137577, 137578, 137579, 137580 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44949] = { ["id"] = 44949, ["name"] = "The Smell of Humans", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44949 }, ["description"] = "<You've noticed that your snowfeather hatchling shakes whenever humans are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of humans, so that it can get used to the smell.>", ["objectivesText"] = "Take your Snowfeather Hatchling to the Gilded Rose in Stormwind. Progress: <Your snowfeather hatchling looks at you uncertainly.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137578 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44950] = { ["id"] = 44950, ["name"] = "Hunting Lesson: Northern Hawk Owls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44950 }, ["description"] = "<Your snowfeather hatchling seems to get agitated when you are near other critters, none more so than the hawk owls of Highmountain. It fluffs up its plumage and squawks loudly whenever one is nearby. It appears to have a primal need for predation.> <It seems you will need to take your falcosaur out hunting.>", ["objectivesText"] = "Defeat 3 Northern Hawk Owls in Highmountain with your Snowfeather Hatchling . Progress: <Your snowfeather hatchling looks ready for some exercise.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137578 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44952] = { ["id"] = 44952, ["name"] = "Blackrock Depths: Jewel of the Depths", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 618, ["mapID"] = 83, ["storyline"] = { 44952 }, ["description"] = "Welcome to Everlook. Could I interest you in a new weapon of sorts? You know, I'm not just into selling weapons of mass dismemberment here at the shop. I like rare jewels as well. Perhaps you and I can come to an arrangement of sorts in procuring a jewel I've had my eye on getting for quite some time. I have some great blacksmithing plans here you might be interested in, you know, in trade for your services. Now, onto the details...", ["objectivesText"] = "Travel to Blackrock Depths and obtain a Core of Bael'Gar , Core of Roccor , Essence of Incendius , and Essence of Magmus . Once you have all four items, combine them at the Black Forge near the entrance to Molten Core at the bottom of Blackrock Depths and bring the Blackrock Ruby back to Wixxrak in Everlook. Progress: This ain't no easy task. It's why the jewel's so rare, you see?", ["rewardXP"] = 2765, ["rewardItems"] = { 12821, 142351, 142352, 142353, 142354, 142355, 142357 }, ["starts"] = { { ["mapID"] = 83, ["npcID"] = 11184, ["x"] = 0.602, ["y"] = 0.502 } }, ["ends"] = { { ["mapID"] = 83, ["npcID"] = 11184, ["x"] = 0.602, ["y"] = 0.502 } }, ["coords"] = { ["mapID"] = 83, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.502 }, ["mapCandidates"] = { ["npc"] = { 83 }, ["zone"] = { 618 } }, ["questType"] = "dungeon", ["db2QuestSortName"] = "Suffusion Camps" },
[44953] = { ["id"] = 44953, ["name"] = "Allies in Highmountain", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44953 }, ["description"] = "<Your snowfeather hatchling emits a deep, chittering growl when you pass near Thunder Totem.> <The Highmountain Tribes immediately began attempting to evict the falcosaurs from their territory. It must consider them a threat to the flock, and the growl is probably its attempt to protect you.> <Show your falcosaur that you and it can work alongside the Highmountain Tribes.>", ["objectivesText"] = "Complete 5 World Quests in Highmountain with your Snowfeather Hatchling out. Progress: <Your snowfeather hatchling isn't at all sure about this.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137578 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44954] = { ["id"] = 44954, ["name"] = "Snowfeather Team Up", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44954 }, ["description"] = "<Your snowfeather hatchling looks at you and emits a sort of squawking bark. It appears to want to do something together as a team!> <To learn, your hatchling must be at your side before you begin a battle, must be your first pet to enter the battle, and cannot die in battle.>", ["objectivesText"] = "Defeat 3 Pet Battle World Quests in Broken Isles with your Snowfeather Hatchling . Progress: <Your snowfeather hatchling looks ready for your commands!>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137578 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44956] = { ["id"] = 44956, ["name"] = "Deadly Prey", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44956 }, ["description"] = "<After working together on recent pet battles, your snowfeather falcosaur seems much more interested in your combat abilities. It might learn a thing or two from watching you do battle with a powerful opponent.>", ["objectivesText"] = "Complete 1 Rare Elite World Quest with your Snowfeather Hatchling out. Progress: <Your snowfeather hatchling looks ready to learn!>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137578 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44957] = { ["id"] = 44957, ["name"] = "Hunting Lesson: Spiketail Beaver", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44957 }, ["description"] = "<Your snowfeather hatchling has been interested in following beaver tracks recently. It must have found a new species to prey upon.>", ["objectivesText"] = "Defeat 3 Spiketail Beavers in Highmountain with your Snowfeather Hatchling . Progress: <Your snowfeather hatchling looks ready to hunt.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137578 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44958] = { ["id"] = 44958, ["name"] = "The Unfriendly Faction", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44958 }, ["description"] = "<When passing the other faction recently, your snowfeather walked right up to them without fear. It does not appear to understand that they are the enemy. Probably best to teach them before something bad happens.>", ["objectivesText"] = "Complete 3 PvP World Quests with your Snowfeather Hatchling out. Progress: <Your snowfeather hatchling seems to like the other faction a bit too much.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137578 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
