[44962] = { ["id"] = 44962, ["name"] = "Hunting Lesson: Coralback Fiddler", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44962 }, ["description"] = "<Your snowfeather hatchling is particularly wary of the elemental pets in your menagerie. They will need to learn to work together if they are to get along. Hunting together against the new prey it has begun stalking may just do the trick.>", ["objectivesText"] = "Defeat 3 Coralback Fiddlers in Highmountain with your Snowfeather Hatchling and 2 Elemental pets. Progress: <Your snowfeather hatchling looks wary of your elemental pets.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137578 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
