[44986] = { ["id"] = 44986, ["name"] = "Teamwork Lesson: Krosus", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44986 }, ["description"] = "<Your direbeak hatchling squawks loudly and panics when very large creatures are nearby, even if they are friendly. It must learn to remain calm under pressure, even when facing creatures many times its size. Showing it an epic example of teamwork against a monster the size of a mountain might help.>", ["objectivesText"] = "Defeat Krosus in the Nighthold with your Direbeak Hatchling out. Progress: <Your direbeak hatchling looks to you for guidance.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 122457, 137579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44987] = { ["id"] = 44987, ["name"] = "Direbeak Team Rumble", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44987 }, ["description"] = "<Your direbeak hatchling looks ready to team up with you for another round of battles and show off everything it has learned about teamwork. Commanding it with new allies would be an excellent test of its abilities.>", ["objectivesText"] = "Defeat 3 Pet Battle World Quests with your Direbeak Hatchling and 2 Humanoid pets.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 93040, 106244, 127868 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44988] = { ["id"] = 44988, ["name"] = "Direbeak Reunion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["storyline"] = { 44988 }, ["description"] = "<Your direbeak hatchling won't stop emitting soft, melancholy squawks. It seems to be depressed. Perhaps it is time to return it to its place of origin?>", ["objectivesText"] = "Return the Direbeak Hatchling to Gull Rock in Stormheim.", ["rewardGold"] = 262100, ["rewardXP"] = 6140, ["rewardItems"] = { 137579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard" },
[44989] = { ["id"] = 44989, ["name"] = "Raising Your Sharptalon", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44989 }, ["description"] = "<Your sharptalon hatchling continues to shiver as it settles in at your side. It looks up at you with wide, unblinking eyes. It appears to be looking to you to help it survive and grow.>", ["objectivesText"] = "Raise your Sharptalon Hatchling to level 25. Progress: Baroo!", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 116415, 116429, 122457, 128763, 128837, 128839, 128843, 137577, 137578, 137579, 137580 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
