[44991] = { ["id"] = 44991, ["name"] = "The Smell of Draenei", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44991 }, ["description"] = "<You've noticed that your bloodgazer hatchling shakes whenever draenei are nearby. It appears to be utterly terrified of them. Perhaps you could take it somewhere with a lot of draenei, so that it can get used to the smell.>", ["objectivesText"] = "Take your Bloodgazer Hatchling to the Inn in the Exodar. Progress: <Your bloodgazer hatchling looks at you uncertainly.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
