[44995] = { ["id"] = 44995, ["name"] = "Hunting Lesson: Spring Strider", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44995 }, ["description"] = "<Your sharptalon hatchling seems to get agitated when you are near other critters, especially the spring striders of Val'sharah. It fluffs up its plumage and scratches the ground whenever one is nearby. It appears to have a primal need for predation.> <It seems you will need to take your falcosaur out hunting.>", ["objectivesText"] = "Defeat 3 Spring Striders in Val'sharah with your Sharptalon Hatchling . Progress: <Your sharptalon hatchling looks ready for some exercise.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137580 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44996] = { ["id"] = 44996, ["name"] = "Hunting Lesson: Erudite Manafiend", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44996 }, ["description"] = "<Your bloodgazer hatchling seems to get agitated when you are near other critters, none more so than the erudite manafiends of Azsuna. It makes an odd, low clucking noise and spreads its wings whenever one is nearby. It appears to have a primal need for predation.> <It seems you will need to take your falcosaur out hunting.>", ["objectivesText"] = "Defeat 3 Erudite Manafiends in Azsuna with your Bloodgazer Hatchling . Progress: <Your bloodgazer hatchling looks ready for some exercise.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 87526 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44997] = { ["id"] = 44997, ["name"] = "Allies in Val'sharah", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44997 }, ["description"] = "<Your sharptalon hatchling stubbornly refuses to enter Val'sharah when you approach.> <Though they revere nature, the Dreamweavers also must maintain the balance of nature, and began an aggressive campaign against the falcosaurs once their invasiveness was noted. It has likely seen the druids of Val'sharah slaughter some members of its flock.> <Show your falcosaur that you and it can work alongside the Dreamweavers.>", ["objectivesText"] = "Complete 5 World Quests in Val'sharah with your Sharptalon Hatchling out. Progress: <Your sharptalon hatchling isn't at all sure about this.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137580 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44998] = { ["id"] = 44998, ["name"] = "Allies in Azsuna", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 44998 }, ["description"] = "<Your bloodgazer hatchling emits a terrified squawk, and you sense the spirits of Azsuna are nearby.> <The spirits of the elves of Azsuna must seem strange and unnatural to your pet. It may instinctively fear them.> <Show your falcosaur that you and it can work alongside the spirits of the Court of Farondis.>", ["objectivesText"] = "Complete 5 World Quests in Azsuna with your Bloodgazer Hatchling out. Progress: <Your bloodgazer hatchling isn't at all sure about this.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
