[45034] = { ["id"] = 45034, ["name"] = "Fire the Cannons!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["storyline"] = { 45034 }, ["description"] = "It will take more than a damn shipwreck to bring me down. Those overgrown, vomit-reeking, demon felbags have another thing coming if they think that's all it's gonna take to stop me. <Keeshan coughs up seawater, wiping his mouth dry with his sleeve.> Ughh... I may need a little breather though. Here, take this flare gun and use it to call down artillery strikes on the beach. Rain hell on those worthless, half-goat bastards and I'll rendezvous with you back at the base when the mission is complete!", ["objectivesText"] = "Slay 14 demons.", ["rewardItems"] = { 142390 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[45035] = { ["id"] = 45035, ["name"] = "The Call of Battle", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45035 }, ["description"] = "These demons have no honor! Rather than meet us in glorious, open-battle; they hide behind their barricades and siege weapons. The Valarjar have come for the glory of battle and we will not be turned away by cowardly tactics! Destroy their cannons and bring down their barriers, so that our valiant Valarjar may face them in the true spirit of battle! When the dust of battle clears, the corpses of demons shall litter the ground... and the Valarjar will stand triumphant!", ["objectivesText"] = "Legion Forces slain Defenses destroyed", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137642, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Legion Forces slain", ["amount"] = 16, ["type"] = 0, ["objectID"] = 121032, ["orderIndex"] = 0 }, { ["text"] = "Defenses destroyed", ["amount"] = 8, ["type"] = 0, ["objectID"] = 121013, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[45036] = { ["id"] = 45036, ["name"] = "Asgrim the Dreadkiller", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 45036 }, ["description"] = "The spirit of one of our most honored warriors has disappeared from the Halls of Valor. Asgrim the Dreadkiller was a great warlord and king. For centuries, his spirit has dwelled in its rightful place within the Halls of Valor... until recently. Countless years ago, the Dreadkiller's bones were laid to rest not far from here by his warband. We will seek our answers there. Sound Odyn's Horn upon the burial ground and summon his spirit before us.", ["objectivesText"] = "Sound Odyn's Horn upon the burial mound of Asgrim the Dreadkiller .", ["rewardItems"] = { 123860 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[45044] = { ["id"] = 45044, ["name"] = "Weapon No More", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 490, ["mapID"] = 78, ["storyline"] = { 45044 }, ["series"] = { 45051, 45055, 45057 }, ["description"] = "The spear you found certainly has the makings of troll designs from other blacksmithing crafts. Perhaps somebody at one of the camps here in Un'Goro will know more about it.", ["objectivesText"] = "Bring the Badly Broken Dark Spear to Ko'Zan at Mossy Pile in Un'Goro Crater. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["rewardItems"] = { 142377, 237812 }, ["ends"] = { { ["mapID"] = 78, ["npcID"] = 115923, ["x"] = 0.435, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 78, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 78 }, ["zone"] = { 490 } }, ["questType"] = "standard", ["startItems"] = { 142377 } },
