[45059] = { ["id"] = 45059, ["name"] = "Fel Infused Totem Fragment", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45059 }, ["series"] = { 44781, 44782, 44821, 45030, 45033, 45037, 45043, 45045, 45050, 45052, 45053, 45054, 45060, 45061, 46765, 47000 }, ["description"] = "This appears to be a fragment of a relic or totem from Highmountain. It glows eerily with fel power. This should be brought to the Council of Six in Dalaran at once!", ["objectivesText"] = "Take the totem fragment to the Council of the Six in Dalaran.", ["rewardItems"] = { 142395 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 142395 } },
[45060] = { ["id"] = 45060, ["name"] = "Damaged Kirin Tor Insignia", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45060 }, ["series"] = { 44781, 44782, 44821, 45030, 45033, 45037, 45043, 45045, 45050, 45052, 45053, 45054, 45059, 45061, 46765, 47000 }, ["description"] = "Whether it was lost or stolen, it is odd that a demon would possess an insignia of the Kirin Tor. The Council of Six would no doubt be interested in this finding.", ["objectivesText"] = "Take the insignia to the Council of the Six in Dalaran.", ["rewardItems"] = { 142396 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 142396 } },
[45061] = { ["id"] = 45061, ["name"] = "Scrolls of the Faldrottin", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 45061 }, ["series"] = { 44781, 44782, 44821, 45030, 45033, 45037, 45043, 45045, 45050, 45052, 45053, 45054, 45059, 45060, 46765, 47000 }, ["description"] = "While it is definitely odd that a demon would carry a scroll of vrykul writings, what is even more interesting are the contents. The writings appear to reference a vrykul prophesy of one who would unite the Tideskorn against the Burning Legion. This information should be brought to the Council of Six immediately.", ["objectivesText"] = "Take the scrolls to the Council of the Six in Dalaran.", ["rewardItems"] = { 142397, 144457 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 142397 } },
