[45083] = { ["id"] = 45083, ["name"] = "Crysa's Flyers", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 45083 }, ["description"] = "I have obtained some of the most exotic species of carrion bird ever seen on Azeroth. Do you think you can stand up to them?", ["objectivesText"] = "Defeat Crysa in a pet battle. Progress: The carrion birds are circling you!", ["rewardGold"] = 169800, ["rewardXP"] = 200, ["rewardItems"] = { 142447, 142448 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 115286, ["x"] = 0.635, ["y"] = 0.358 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 115286, ["x"] = 0.635, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.635, ["y"] = 0.358 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard" },
[45088] = { ["id"] = 45088, ["name"] = "Trial of Valor: The Lost Army", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8440, ["storyline"] = { 45088 }, ["description"] = "While Helya's defeat is your primary objective, I require more of your aid. Helya has gained the ability to steal and corrupt the souls of my Valarjar. Her minions hold these souls, corrupting them. I am certain Helya herself hordes the greatest Valarjar souls to herself. You must recover these lost souls, then return them to me. Do this and I will reward you with blessed guard from the hall's armory.", ["objectivesText"] = "Gather 1000 Valarjar Soul Fragments within the Trial of Valor Raid. Progress: Bring me the souls of my lost Valarjar. Only then will I reward you with the blessed armor you desire.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142487, 143506, 143510, 143514, 143518, 143521, 237812, 241599 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8440 } }, ["questType"] = "raid" },
[45102] = { ["id"] = 45102, ["name"] = "Begin the Assault", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8581, ["storyline"] = { 45102 }, ["description"] = "The battle for our world has been hard fought, but with the power of your weapon and the combined forces of Azeroth, we have driven the demon invaders back at every turn. Now we stand once again upon the Broken Shore, poised to do that which we previously failed to accomplish. Let us not forget those who sacrificed everything to give us this chance. Our first objective is to take the hill before us, so that we may build a stronghold. Steel yourself, <name>. The assault on the Broken Shore begins now.", ["objectivesText"] = "Begin the assault on the Broken Shore.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8581 } }, ["questType"] = "standard" },
[45104] = { ["id"] = 45104, ["name"] = "Your Next Assignment...", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 45104 }, ["description"] = "Congratulations on making it through the Intern Expo! However, we're not through with you yet! You still have some time left, so what better use of your time than to make treasures and vignettes on the Broken Shore!", ["objectivesText"] = "Create interesting treasures and vignettes for patch 7.2!", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[45105] = { ["id"] = 45105, ["name"] = "Lord Raz'gor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["storyline"] = { 45105 }, ["description"] = "The pit lord, Raz'gor, oversees this bulwark. If you wish to break the Broken Shore, Raz'gor must be defeated. Fight you way past the demon blockade and find Lord Raz'gor. Slay the demon and you will strike a heavy blow to the Burning Legion's plans on the Broken Shore.", ["objectivesText"] = "Defeat Lord Raz'gor on the Broken Shore.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard" },
