[45159] = { ["id"] = 45159, ["name"] = "Cubic Conundrum", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 45159 }, ["series"] = { 45160, 45238, 45239 }, ["description"] = "<You find a mysterious cube . Its design is unfamiliar, but unmistakably ancient. The cube's surface is inlaid with magical runes. Though inert, its properties may be worth investigating. Perhaps if you show it to Dariness the Learned in Dalaran , she could tell you more about it.>", ["objectivesText"] = "Take the Mysterious Cube to Dariness the Learned in Dalaran . Provided item:", ["rewardItems"] = { 142536, 142559 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["startItems"] = { 142559 } },
[45160] = { ["id"] = 45160, ["name"] = "Cubic Currents", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 45160 }, ["series"] = { 45159, 45238, 45239 }, ["description"] = "To determine this cube's purpose, we need to power it up. Hmm, I have an idea... The Nightborne covet a substance you are no doubt familiar with called ancient mana. Should be just the thing for a relic this old. Gather a sufficient quantity and we'll attempt to get it working. Be careful in Suramar ! It would be a shame if this curious cube were lost and became a memory once more.", ["objectivesText"] = "Obtain 300 Ancient Mana from Suramar", ["rewardItems"] = { 142536 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[45172] = { ["id"] = 45172, ["name"] = "To Battle!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 739, ["storyline"] = { 45172 }, ["description"] = "Your champions have returned from exploring the battleground with a report detailing wild adventures and death-defying feats of strength and honor. In these ever shifting battles of conquest, more assistance is always required. Will you answer the call?", ["objectivesText"] = "Join and win in any battleground. Progress: How are you faring in the battleground?", ["rewardGold"] = 842700, ["rewardXP"] = 2090, ["rewardItems"] = { 7979, 31380, 31381, 31382, 31383, 31404, 31405, 33447, 33448, 35814, 35815, 35816, 35817, 44382, 44383, 44384, 44385, 45724, 46114, 63760, 63761, 63762, 65852, 65853, 65854, 89125, 91086, 116415, 126923, 126924, 139457, 139471, 139472, 139473, 139474, 139475, 139476, 139477, 139478, 139479, 139480, 140147, 140163, 140164, 140171, 140172, 140177, 142001, 142002, 142003, 142004, 142340, 143328, 143479, 143606, 147501, 147505, 147509, 155413, 155414, 155415, 155416, 158174, 158179, 159980, 159981, 159982, 159983, 160335, 160338, 160341, 160344, 160373, 160376, 160379, 160382, 162140, 162141, 162142, 162143, 163036, 163526, 163533, 163534, 163536, 163537, 163538, 163539, 163540, 163541, 163542, 211279, 237812, 246812, 246814, 248247 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 103023, ["x"] = 0.4345, ["y"] = 0.4665 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.4345, ["y"] = 0.4665 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["startItems"] = { 143328 } },
