[45238] = { ["id"] = 45238, ["name"] = "Return to Karazhan: Cubic Cynosure", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 45238 }, ["series"] = { 45159, 45160, 45239 }, ["description"] = "Drat! The ancient mana doesn't seem to be working. I need to think the problem through, focus and... Wait, that's it! Focus! We need to focus the energy of the ancient mana to activate the cube. I've heard tell of a mana wyrm in Karazhan with the means to focus its powers. Might be just what we need! Watch out, though. My sources tell me this wyrm is humongous!", ["objectivesText"] = "Obtain a Mana Focus from the Mana Devourer within Karazhan", ["rewardItems"] = { 142536, 143537 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[45239] = { ["id"] = 45239, ["name"] = "Cubic Coalescing", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 45239 }, ["series"] = { 45159, 45160, 45238 }, ["description"] = "Success! The cube's magic has been restored! I'm excited to see what it does! Since you did all the legwork, you should have the honor of activating it. Care to give it a try?", ["objectivesText"] = "Activate the Mysterious Cube", ["rewardItems"] = { 142536, 142559 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[45271] = { ["id"] = 45271, ["name"] = "Insurrection", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45271 }, ["series"] = { 38649, 38695, 45260 }, ["description"] = "First Arcanist Thalyssra has received dark tidings regarding the Nightfallen rebellion and requires your assistance. Journey to Shal'Aran in Suramar and meet with her.", ["objectivesText"] = "Speak with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 63889, 63890 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[45272] = { ["id"] = 45272, ["name"] = "Insurrection: Missing Persons", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45272 }, ["series"] = { 45261 }, ["description"] = "First Arcanist Thalyssra has requested your aid in searching for her missing people. She has a lead from a very unexpected ally. Meet with her at Shal'Aran in Suramar .", ["objectivesText"] = "Speak with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[45277] = { ["id"] = 45277, ["name"] = "Insurrection: Waxing Crescent", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45277 }, ["description"] = "First Arcanist Thalyssra has sent word: there has been communication from Ly'leth. Your help is needed. Journey to Shal'Aran in Suramar and lend what aid you can.", ["objectivesText"] = "Speak with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[45278] = { ["id"] = 45278, ["name"] = "Insurrection: An Elven Problem", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45278 }, ["series"] = { 45263 }, ["description"] = "The Alliance and Horde have arrived in Suramar . First Arcanist Thalyssra needs your help in providing an introduction. Meet with Thalyssra in Shal'Aran.", ["objectivesText"] = "Meet with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[45280] = { ["id"] = 45280, ["name"] = "Insurrection: Crafting War", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45280 }, ["series"] = { 45265 }, ["description"] = "Refugees are flooding in to Shal'Aran, and many are willing to fight for Thalyssra's rebel army. They need weapons, training and help from anyone who can provide it. Go to Shal'Aran and lend your assistance.", ["objectivesText"] = "Meet with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[45281] = { ["id"] = 45281, ["name"] = "Insurrection: March on Suramar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45281 }, ["series"] = { 44738, 44739, 44740, 45266 }, ["description"] = "First Arcanist Thalyssra has sent word: the time has come to launch our assault on Suramar . The elven armies of the Horde, Alliance, Kirin Tor and Nightfallen are assembled. They only await your arrival to begin their assault. Report to Shal'Aran and meet with First Arcanist Thalyssra and prepare for battle.", ["objectivesText"] = "Meet with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[45282] = { ["id"] = 45282, ["name"] = "Insurrection: Elisande's Retort", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45282 }, ["series"] = { 44736, 45267 }, ["description"] = "The combined forces of the elves stand ready to begin their siege on the gates of the Nighthold. Report to First Arcanist Thalyssra in Shal'Aran to begin the siege.", ["objectivesText"] = "Meet with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[45285] = { ["id"] = 45285, ["name"] = "Insurrection: As Strong As Our Will", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45285 }, ["series"] = { 44918, 44919, 45268 }, ["description"] = "In the wake of Elisande's attack, the need is stronger than ever to add to the ranks of the Nightfallen rebellion. Plans are in motion that may help with this in an unconventional way. Report to First Arcanist Thalyssra in Shal'Aran for more details.", ["objectivesText"] = "Meet with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[45287] = { ["id"] = 45287, ["name"] = "Insurrection: Breaking the Nighthold", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45287 }, ["series"] = { 45269 }, ["description"] = "First Arcanist Thalyssra sends word that her forces are ready. It is time for you to lead the attack against the Nighthold. Report to Shal'Aran in Suramar for details.", ["objectivesText"] = "Meet with First Arcanist Thalyssra in Shal'Aran.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.364667, ["y"] = 0.461333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[45291] = { ["id"] = 45291, ["name"] = "Return to Karazhan: Book Wyrms", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 45291 }, ["series"] = { 45292, 45293, 45294, 45295 }, ["description"] = "My incorporeal condition has allowed me to enter the tower safely for the first time. I must say, it's a bit of a shambles in there! I could use some help tackling my cleaning checklist. We should start with the library. All those musty tomes are bound to attract mana wyrms! Please shelve any books that have fallen to the floor, or worse, taken flight. And if you find mana wyrms nibbling at the pages... step on them!", ["objectivesText"] = "Clean up the Karazhan Library. Progress: How did it go?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 143551, 143552, 143555, 143556, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "dungeon", ["db2QuestSortName"] = "Day of the Dead" },
[45294] = { ["id"] = 45294, ["name"] = "Return to Karazhan: High Stress Hiatus", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 45294 }, ["series"] = { 45291, 45292, 45293, 45295 }, ["description"] = "The new plays in the opera house have been well received by everyone... except cast members of the older shows. Egos are bruised and tensions are running high! Romulo and Julianne are ready to poison each other. Tinhead is rusting with tears over his lack of adoration. Little Red's cape was stolen by a disgruntled understudy, who ran off to play chess of all things. Actors, am I right? We need them ready to perform in case the audience demands a revival. Please, help me calm their nerves!", ["objectivesText"] = "Help Darius soothe the old casts egos by finding a Positive Review amongst the audience members to simmer tensions between Romulo and Julianne, stealing a Bouquet of Roses from one of the new acts for Tinhead's vanity and finding where the understudy stashed Little Red's cape in the Chess room. Progress: How did it go?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 142461, 142468, 143551, 143552, 143555, 143556, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "dungeon", ["db2QuestSortName"] = "Day of the Dead" },
[45295] = { ["id"] = 45295, ["name"] = "Return to Karazhan: Clearing Out the Cobwebs", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8443, ["mapID"] = 42, ["storyline"] = { 45295 }, ["series"] = { 45291, 45292, 45293, 45294 }, ["description"] = "I admit it... even as a spirit, I am deathly afraid of spiders. All those legs! Dripping fangs! Sticky webs coming out of their... <Darius does a squirming sort of shimmy that is uncomfortable to watch.> I'm sure a world-saving hero like you doesn't mind them, though. Which is good, since a whole brood of spiders has taken over the Servant's Quarters. You'll handle this, right? If you don't get them all, they'll keep multiplying.", ["objectivesText"] = "Clean out spiders from the Servant's Quarters.", ["rewardGold"] = 1239200, ["rewardXP"] = 12280, ["rewardItems"] = { 122451, 132444, 132466, 142469, 142552, 143551, 143552, 143555, 143556, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 8443 } }, ["questType"] = "dungeon" },
[45296] = { ["id"] = 45296, ["name"] = "No Bones About It", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 45296 }, ["description"] = "The Charred Bone Fragments still smolder with ancient power. Darius would be extremely interested in examining them and hearing of your defeat of Nightbane.", ["objectivesText"] = "Take the Charred Bone Fragments to Darius.", ["rewardGold"] = 1123600, ["rewardXP"] = 12280, ["rewardItems"] = { 142468, 142469, 143556 }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Day of the Dead", ["startItems"] = { 143556 } },
