[45392] = { ["id"] = 45392, ["name"] = "Dark Memento", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 45392 }, ["description"] = "The flowers were... a nice gesture. <Velonara sniffs one of the black roses.> I have a spare hood. Nothing fancy, but perhaps Moorgoth would like to have it. Just don't let him get his hopes up or anything. I'm merely repaying a kindness. I would appreciate it if you kept all this between us. Giving presents to admirers falls a bit outside the dark ranger rules of conduct.", ["objectivesText"] = "Bring Velonara's spare hood to Death Hunter Moorgoth .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 3420, 143663 }, ["starts"] = { { ["mapID"] = 739, ["npcID"] = 105099, ["x"] = 0.483143, ["y"] = 0.456905 } }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 100633, ["x"] = 0.522, ["y"] = 0.494 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.483143, ["y"] = 0.456905 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard" },
[45405] = { ["id"] = 45405, ["name"] = "Breaching the Sanctum", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 45405 }, ["description"] = "It is time. Valtrois is ready to destroy the barrier guarding the breach in the Sanctum. I will teleport you to the breach, then it falls on you to secure the area. Take these telemancy orbs . If you find you need support, use them to summon Withered. We must strike before the enemy can ready new defenses. Let me know when you are ready and we will begin.", ["objectivesText"] = "Speak with Oculeth to start the assault.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142118, 143747, 237812, 246812, 246813, 246814, 246815, 249783, 254267 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[45406] = { ["id"] = 45406, ["name"] = "The Storm's Fury", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 45406, 45839, 46110 }, ["series"] = { 45839 }, ["description"] = "No longer do we have time to prepare, the moment of action is upon us! Come with me, little one. With you guiding my aim we shall cleanse this isle by thunder and lightning!", ["objectivesText"] = "Destroy the Burning Legion forces within Shield's Rest.", ["rewardGold"] = 309800, ["rewardXP"] = 1060, ["rewardItems"] = { 190454, 197921, 237812 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 116868, ["x"] = 0.9, ["y"] = 0.11 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 118778, ["x"] = 0.816, ["y"] = 0.072 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.9, ["y"] = 0.11 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 305, ["name"] = "Legion Assault - Stormheim", ["orderIndex"] = 1, ["flags"] = 0 } } },
[45420] = { ["id"] = 45420, ["name"] = "The Nighthold: The Eye of Aman'Thul", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8025, ["storyline"] = { 45420 }, ["series"] = { 44719, 45417 }, ["description"] = "The battle is won, but the war is far from over. In order to stem the tide of demons flooding into Azeroth, we must use the Pillars of Creation to seal the Tomb of Sargeras. <Khadgar peers down at the Eye of Aman'Thul.> That... might be difficult to carry. Perhaps I can use the power of the Eye itself to teleport it to Dalaran. I suppose there is only one way to find out!", ["objectivesText"] = "Aid Khadgar in transporting the Eye of Aman'Thul.", ["rewardItems"] = { 142436, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8025 } }, ["questType"] = "raid" },
[45423] = { ["id"] = 45423, ["name"] = "Wailing Critters", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 17, ["storyline"] = { 45423 }, ["series"] = { 45540 }, ["description"] = "I'm glad you're here, <name>. Tiny wails have been heard in the caverns for some time since Naralex was awakened. At first, we suspected that some deviate critters had survived. Upon further investigation, we found them to be growing and multiplying beyond our wildest expectations. The corpse of Verdan the Everliving may have something to do with it, we're not sure. That's why we're sending you in. I've also seen suspicious footprints leading into the caverns recently. We may not be alone, be careful.", ["objectivesText"] = "Defeat the Budding Everliving Spore in Wailing Caverns. Progress: Have you completed your investigation the Wailing Caverns?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 86143, 117354, 122457, 143753 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 17 } }, ["questType"] = "standard" },
