[45527] = { ["id"] = 45527, ["name"] = "Eyir's Forgiveness", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 14979, ["mapID"] = 947, ["storyline"] = { 45527 }, ["description"] = "I'm sorry for everything I've put you through, outsider. After my actions here, I fear all of this may have been in vain. Come with me back to Skold-Ashil. There I will accept whatever judgment Eyir deems fit of me.", ["objectivesText"] = "Witness Eyir's judgment of Sigryn in the Vault of Eyir in Skold-Ashil.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["starts"] = { { ["mapID"] = 947, ["npcID"] = 116484, ["x"] = 0, ["y"] = 0 } }, ["coords"] = { ["mapID"] = 947, ["source"] = "quest_giver", ["x"] = 0, ["y"] = 0 }, ["mapCandidates"] = { ["npc"] = { 947 }, ["zone"] = { 14979 } }, ["questType"] = "standard" },
