[45534] = { ["id"] = 45534, ["name"] = "A Common Enemy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7541, ["storyline"] = { 45534 }, ["description"] = "I have one more request to ask of you, outsider. Return to your leaders and report to them what transpired here. Though your people may never truly be allies with the Tideskorn, know that we have a common enemy - one which my people will fight to the last vrykul. When the time comes, I hope to see you on the battlefield.", ["objectivesText"] = "Return to Khadgar in the Violet Citadel.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "standard" },
[45539] = { ["id"] = 45539, ["name"] = "Pet Battle Challenge: Wailing Caverns", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 17, ["storyline"] = { 45539 }, ["description"] = "The deviate critters of the Wailing Caverns continue to flourish in the damp darkness, but I've been doing my best to keep their numbers down. I've found a few pets and supplies while clearing out the caverns, I might be willing to part with a sack of supplies if you can beat my best run. You'll have to clear out the cavern without healing or reviving any of your pets to best me. Good luck!", ["objectivesText"] = "Defeat the Budding Everliving Spore in Wailing Caverns. Progress: How is the battle for Wailing Caverns going?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 86143, 143753, 147543 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 17 } }, ["questType"] = "standard" },
[45540] = { ["id"] = 45540, ["name"] = "A Call from the Caverns", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 45540 }, ["series"] = { 45423 }, ["description"] = "Oh, good, I'm glad you stopped by. We've heard disturbing rumors of corruption continuing to flourish in the Wailing Caverns. You seem like just the right person to investigate. Since Naralex's awakening, one of his disciples has been watching over the area to ensure that deviate creatures remain in check. She is the one that has been sending us these dire warnings. Meet up with her in the eye of the skull-shaped rock above Wailing Caverns and see if you can help her handle this situation.", ["objectivesText"] = "Find Muyani in the skull-shaped rock above Wailing Caverns.", ["rewardGold"] = 28090, ["rewardXP"] = 770, ["rewardItems"] = { 143753 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
