[45563] = { ["id"] = 45563, ["name"] = "The Shrouded Coin", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 6757, ["mapID"] = 554, ["storyline"] = { 45563 }, ["description"] = "A swirling mist envelops the coin and it begins to float above your hand. The mist briefly parts to reveal a shiny new coin, yet in the next instant the coin appears worn from years of exchange. As the coin settles back in to your hand, visions of jungles and mist shrouded peaks waft into your mind, and through the vision you recognize the four Celestials gathered in the courtyard of an island.", ["objectivesText"] = "Bring the Shrouded Timewarped Coin to Mistweaver Xia on the Timeless Isle .", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 71638, 71952, 103678, 129747, 129928, 133377, 133378, 143776, 167921, 167922, 187611, 225348 }, ["ends"] = { { ["mapID"] = 554, ["npcID"] = 118828, ["x"] = 0.43, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 554, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 554 }, ["zone"] = { 6757 } }, ["questType"] = "standard", ["startItems"] = { 143776 } },
[45570] = { ["id"] = 45570, ["name"] = "In Safer Hands", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 45570 }, ["description"] = "There is still the matter of the Focusing Iris . Please return it to your Kirin Tor friends, with my apologies. As for myself, I think I'm done chasing artifacts for a while. One possession by immortal shadowy evil is enough for me, thank you.", ["objectivesText"] = "Bring the Focusing Iris to Archmage Kalec in Dalaran. Provided item:", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 143779 }, ["starts"] = { { ["mapID"] = 76, ["npcID"] = 117252, ["x"] = 0.252, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.252, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 16 } }, ["questType"] = "standard" },
[45572] = { ["id"] = 45572, ["name"] = "Holding Our Ground", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45572, 45840, 46182 }, ["description"] = "Though we anticipated a strong Legion presence, our attacks on their camps have angered their forces even further than anticipated. Our forces rally on both land and in the skies above Thunder Totem in an attempt to regain our footing. Do what you can to reduce their forces. Once we've secured Thunder Totem we'll begin our plan for a final attack.", ["objectivesText"] = "Repel the Legion threat from Thunder Totem.", ["rewardXP"] = 1060, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 119944, ["x"] = 0.442, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 119676, ["x"] = 0.502, ["y"] = 0.644 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 750, ["questLines"] = { { ["id"] = 307, ["name"] = "Legion Assault - Highmountain", ["orderIndex"] = 1, ["flags"] = 0 } } },
