[45637] = { ["id"] = 45637, ["name"] = "Sandworm Meat", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 45637 }, ["objectivesText"] = "Progress: Gettin' de colossi to wake up takes a whole heap of meat. Lucky for you, Silithus is crawling with sandworms, and the colossi don't seem to mind da taste.", ["rewardXP"] = 25, ["rewardItems"] = { 20424 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[45638] = { ["id"] = 45638, ["name"] = "Crunchy Spider Legs", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 45638 }, ["objectivesText"] = "Progress: We need meat - any kind of meat - to feed de colossi. And there's no cheaper meat than spider meat. You can find plenty of it out in Outland.", ["rewardXP"] = 25, ["rewardItems"] = { 22644 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[45639] = { ["id"] = 45639, ["name"] = "Chilled Meat", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 45639 }, ["objectivesText"] = "Progress: De beasts of Northrend are big, heavy, and full of meat. Go find sometin' we can feed to the colossi.", ["rewardXP"] = 25, ["rewardItems"] = { 43013 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[45640] = { ["id"] = 45640, ["name"] = "Crocolisk Tails", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 45640 }, ["objectivesText"] = "Progress: De crocolisks of Uldum are known for bein' bigger than all the rest. When you need lots of meat in a hurry, they're always a good option.", ["rewardXP"] = 25, ["rewardItems"] = { 62784 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 117432, ["x"] = 0.34, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
