[45839] = { ["id"] = 45839, ["name"] = "Assault on Stormheim", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 45406, 45839, 46110 }, ["series"] = { 45406 }, ["description"] = "The eternal foe of our world, the Burning Legion, dare to attack the land of Stormheim ! Champion, now is your call to valor! Find the forces of the Legion and eradicate them!", ["objectivesText"] = "Repel the Burning Legion forces throughout Stormheim .", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 138762, 139155, 139156, 139157, 139158, 139159, 139160, 139161, 139162, 139163, 139164, 139165, 139166, 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 116868, ["x"] = 0.9, ["y"] = 0.11 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.9, ["y"] = 0.11 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "world", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 305, ["name"] = "Legion Assault - Stormheim", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45840] = { ["id"] = 45840, ["name"] = "Assault on Highmountain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 45572, 45840, 46182 }, ["description"] = "In my years I have seen disturbances and threats come and go, but never before have I seen such brazen disregard for life. The demons may scorch our lands and cause suffering amongst our kin, but we must not stand idly by while they threaten what we have fought so hard to create. Rise to the occasion, <name>. The time has come to stand against the Burning Legion!", ["objectivesText"] = "Repel the Burning Legion forces throughout Highmountain .", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 138762, 139155, 139156, 139157, 139158, 139159, 139160, 139161, 139162, 139163, 139164, 139165, 139166, 237812 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 119944, ["x"] = 0.442, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "world", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 307, ["name"] = "Legion Assault - Highmountain", ["orderIndex"] = 0, ["flags"] = 0 } } },
[45856] = { ["id"] = 45856, ["name"] = "Battle for Val'sharah", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 44789, 45812, 45856 }, ["description"] = "From the very start of these attacks I've felt as though the demons knew our plans, as if they anticipated our every move. If we are to put an end to this we must focus our attacks at the heart of the beast. Your efforts have shown these battles are not won by bravery alone, but willingness and sacrifice. I ask that you stand on the battlefield once more among allies to bring this madness to an end.", ["objectivesText"] = "Defeat Dread Vizier Gra'tork in Val'sharah .", ["rewardGold"] = 151650, ["rewardXP"] = 1060, ["rewardItems"] = { 109076, 139773, 142001, 246812, 246814, 248247 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 118250, ["x"] = 0.44, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 118440, ["x"] = 0.548, ["y"] = 0.732 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 308, ["name"] = "Legion Assault - Val'sharah", ["orderIndex"] = 2, ["flags"] = 0 } } },
