[46110] = { ["id"] = 46110, ["name"] = "Battle for Stormheim", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 45406, 45839, 46110 }, ["description"] = "Your efforts have destroyed the Legion's forces upon Shield's Rest, yet they continue to press their assault. There is only one way to end this - you must venture into the midst of our foe, find their commander, and remove his vile head!", ["objectivesText"] = "Defeat Lord Commander Alexius in Stormheim .", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["rewardItems"] = { 142003, 246812, 246814, 248247 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 118778, ["x"] = 0.816, ["y"] = 0.072 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 118781, ["x"] = 0.718, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.816, ["y"] = 0.072 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 305, ["name"] = "Legion Assault - Stormheim", ["orderIndex"] = 2, ["flags"] = 0 } } },
