[46148] = { ["id"] = 46148, ["name"] = "Furthering Knowledge", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 626, ["storyline"] = { 43466, 43749, 43816, 43817, 43818, 43819, 43820, 43821, 43822, 43823, 43824, 43825, 43826, 43877, 43878, 43879, 43880, 43881, 43883, 43884, 43885, 43886, 43887, 43888, 46108, 46125, 46129, 46130, 46131, 46132, 46133, 46140, 46141, 46142, 46143, 46144, 46147, 46148, 46149, 46150, 46151, 46152, 46153, 46154, 46155, 46156, 46157, 46158 }, ["description"] = "We've got the skinny on a bit of the artifact power already and I am working an angle to capitalize on it. We've been extorting a group of scribes to put together notes for you, yet they are holding out for a few more resources before they deliver. The good news is that we can squeeze them for a few more courses, but after that it will be back to doing our own research.", ["objectivesText"] = "Deliver Order Resources to complete a crash course in artifact knowledge. Progress: Hey, you know what? If you slip me even more order resources , I can put together more notes about your artifact weapon's history and potential. You need to power up your weapon, and I can pass along the knowledge to get it done. Bring me those resources as soon as you can. We've got a business to run here!", ["rewardItems"] = { 146745 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 626, ["questLines"] = { { ["id"] = 211, ["name"] = "Artifact Research", ["orderIndex"] = 37, ["flags"] = 0 } } },
[46149] = { ["id"] = 46149, ["name"] = "Furthering Knowledge", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7877, ["mapID"] = 739, ["storyline"] = { 43466, 43749, 43816, 43817, 43818, 43819, 43820, 43821, 43822, 43823, 43824, 43825, 43826, 43877, 43878, 43879, 43880, 43881, 43883, 43884, 43885, 43886, 43887, 43888, 46108, 46125, 46129, 46130, 46131, 46132, 46133, 46140, 46141, 46142, 46143, 46144, 46147, 46148, 46149, 46150, 46151, 46152, 46153, 46154, 46155, 46156, 46157, 46158 }, ["description"] = "I am amazed by what we have learned so far. I believe I can prepare for you some notes based on our initial research to get you caught up quickly. It will take just a few more resources to prepare the notes properly. These steps we take now should provide a boost to our knowledge and we can delve even deeper into the hidden potential of these weapons.", ["objectivesText"] = "Deliver Order Resources to complete a crash course in artifact knowledge. Progress: With even more order resources , I can scribe further notes about your artifact weapon's history and potential. This knowledge will be crucial for infusing your weapon with additional power. Bring me those resources as soon as you can. The Legion must fall!", ["rewardItems"] = { 146745 }, ["ends"] = { { ["mapID"] = 739, ["npcID"] = 98737, ["x"] = 0.527667, ["y"] = 0.548667 } }, ["coords"] = { ["mapID"] = 739, ["source"] = "quest_giver", ["x"] = 0.527667, ["y"] = 0.548667 }, ["mapCandidates"] = { ["npc"] = { 739 }, ["zone"] = { 7877 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 211, ["name"] = "Artifact Research", ["orderIndex"] = 38, ["flags"] = 0 } } },
