[46151] = { ["id"] = 46151, ["name"] = "Furthering Knowledge", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 139, ["mapID"] = 24, ["storyline"] = { 43466, 43749, 43816, 43817, 43818, 43819, 43820, 43821, 43822, 43823, 43824, 43825, 43826, 43877, 43878, 43879, 43880, 43881, 43883, 43884, 43885, 43886, 43887, 43888, 46108, 46125, 46129, 46130, 46131, 46132, 46133, 46140, 46141, 46142, 46143, 46144, 46147, 46148, 46149, 46150, 46151, 46152, 46153, 46154, 46155, 46156, 46157, 46158 }, ["description"] = "I am surprised and awed each day I delve deeper into the history of these weapons. Our researcher has been going extremely well and we have been busy preparing notes for you. With a few more resources I am sure we can prepare something to boost your artifact knowledge a little. Remember though, this is only a first step. These weapons have been around longer than most recorded history so much deeper knowledge will take time.", ["objectivesText"] = "Deliver Order Resources to complete a crash course in artifact knowledge. Progress: With even more order resources , I kin scribe further notes 'bout yer artifact weapon's hist'ry an' potential. This knowledge'll be crucial fer infusing yer weapon with additional pow'r. Bring me tha resources as soon as ye can. The Legion must fall!", ["rewardItems"] = { 146745 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 211, ["name"] = "Artifact Research", ["orderIndex"] = 40, ["flags"] = 0 } } },
[46152] = { ["id"] = 46152, ["name"] = "Furthering Knowledge", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8022, ["mapID"] = 721, ["storyline"] = { 43466, 43749, 43816, 43817, 43818, 43819, 43820, 43821, 43822, 43823, 43824, 43825, 43826, 43877, 43878, 43879, 43880, 43881, 43883, 43884, 43885, 43886, 43887, 43888, 46108, 46125, 46129, 46130, 46131, 46132, 46133, 46140, 46141, 46142, 46143, 46144, 46147, 46148, 46149, 46150, 46151, 46152, 46153, 46154, 46155, 46156, 46157, 46158 }, ["description"] = "Through pain and blood we have cut through the initial layers of research. We have been busy preparing notes for you and with a few more resources we can get you something to boost your artifact knowledge. This is only the first step, more resources will be required to catch you up further.", ["objectivesText"] = "Deliver Order Resources to complete a crash course in artifact knowledge. Progress: With even more order resources , I can scribe further notes about your artifact weapon's history and potential. This knowledge will be crucial for infusing your weapon with additional power. Bring me those resources as soon as you can. The Legion will cry out in agony as they die!", ["rewardItems"] = { 146745 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8022 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1519, ["db2PoiUiMapID"] = 721, ["questLines"] = { { ["id"] = 211, ["name"] = "Artifact Research", ["orderIndex"] = 41, ["flags"] = 0 } } },
