[46155] = { ["id"] = 46155, ["name"] = "Furthering Knowledge", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7813, ["mapID"] = 695, ["storyline"] = { 43466, 43749, 43816, 43817, 43818, 43819, 43820, 43821, 43822, 43823, 43824, 43825, 43826, 43877, 43878, 43879, 43880, 43881, 43883, 43884, 43885, 43886, 43887, 43888, 46108, 46125, 46129, 46130, 46131, 46132, 46133, 46140, 46141, 46142, 46143, 46144, 46147, 46148, 46149, 46150, 46151, 46152, 46153, 46154, 46155, 46156, 46157, 46158 }, ["description"] = "Studying these ancient magic and metals has given us great insight into the potential of these weapons. Just as these weapons were forged with time and effort so can we forge you instruction on how best to wield and unlock them. With a few more order resources we will have a course completed for you to increase your knowledge. This is only breaking the surface of what we will unlock, and as we break through the layers of lost knowledge it will take time to delve deeper.", ["objectivesText"] = "Deliver Order Resources to complete a crash course in artifact knowledge. Progress: With even more order resources , I can scribe further legends of your artifact weapon's history and potential. This knowledge will be crucial for infusing your weapon with additional power. Bring me those resources as soon as you can. For the Valarjarl!", ["rewardItems"] = { 146745 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7813 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1479, ["db2PoiUiMapID"] = 695, ["questLines"] = { { ["id"] = 211, ["name"] = "Artifact Research", ["orderIndex"] = 44, ["flags"] = 0 } } },
[46156] = { ["id"] = 46156, ["name"] = "Furthering Knowledge", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 43466, 43749, 43816, 43817, 43818, 43819, 43820, 43821, 43822, 43823, 43824, 43825, 43826, 43877, 43878, 43879, 43880, 43881, 43883, 43884, 43885, 43886, 43887, 43888, 46108, 46125, 46129, 46130, 46131, 46132, 46133, 46140, 46141, 46142, 46143, 46144, 46147, 46148, 46149, 46150, 46151, 46152, 46153, 46154, 46155, 46156, 46157, 46158 }, ["description"] = "<Sir/Mam>, thank you and the Tirisgarde for this opportunity. Learning about this weapon of yours has been an absolute joy. To repay your confidence and trust in my abilities I have organized our researchers notes into an easily digestible course. If you have the resources I know we will continue to output even more valuable insights. I assure you it has been worth every minute.", ["objectivesText"] = "Deliver Order Resources to complete a crash course in artifact knowledge. Progress: With even more order resources , I can scribe further notes about your artifact weapon's history and potential. This knowledge will be crucial for infusing your weapon with additional power. Bring me those resources as soon as you can. The Legion must fall!", ["rewardItems"] = { 146745 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 211, ["name"] = "Artifact Research", ["orderIndex"] = 45, ["flags"] = 0 } } },
[46157] = { ["id"] = 46157, ["name"] = "Furthering Knowledge", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7902, ["mapID"] = 709, ["storyline"] = { 43466, 43749, 43816, 43817, 43818, 43819, 43820, 43821, 43822, 43823, 43824, 43825, 43826, 43877, 43878, 43879, 43880, 43881, 43883, 43884, 43885, 43886, 43887, 43888, 46108, 46125, 46129, 46130, 46131, 46132, 46133, 46140, 46141, 46142, 46143, 46144, 46147, 46148, 46149, 46150, 46151, 46152, 46153, 46154, 46155, 46156, 46157, 46158 }, ["description"] = "The amount of power in these artifacts is astounding and we have only just begun our journey. Our researchers have been busy preparing notes for you and with a few more resources I am sure they can prepare something to boost your artifact knowledge. This is only the first step, with more resources we should be able to help you catch up even more.", ["objectivesText"] = "Deliver Order Resources to complete a crash course in artifact knowledge. Progress: With even more order resources , I can scribe further notes about your artifact weapon's history and potential. Such intriguing stories to be told! This knowledge will be crucial for infusing your weapon with additional power. Bring me those resources as soon as you can. Within words lies wisdom.", ["rewardItems"] = { 146745 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7902 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1514, ["db2PoiUiMapID"] = 709, ["questLines"] = { { ["id"] = 211, ["name"] = "Artifact Research", ["orderIndex"] = 46, ["flags"] = 0 } } },
[46158] = { ["id"] = 46158, ["name"] = "Furthering Knowledge", ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7745, ["mapID"] = 726, ["storyline"] = { 43466, 43749, 43816, 43817, 43818, 43819, 43820, 43821, 43822, 43823, 43824, 43825, 43826, 43877, 43878, 43879, 43880, 43881, 43883, 43884, 43885, 43886, 43887, 43888, 46108, 46125, 46129, 46130, 46131, 46132, 46133, 46140, 46141, 46142, 46143, 46144, 46147, 46148, 46149, 46150, 46151, 46152, 46153, 46154, 46155, 46156, 46157, 46158 }, ["description"] = "As we follow the stories further back there are strong whispers of even greater potential. We have discovered much along the way and we can impart that knowledge. With the help of more order resources we will continue to bring in information from members traveling far and wide. These shaman like you are the key to finally unlocking the full potential of these weapons and soon enough we will be back to the time consuming task of chasing down rumors to discover more.", ["objectivesText"] = "Deliver Order Resources to complete a crash course in artifact knowledge. Progress: With even more order resources , I can scribe further notes about your artifact weapon's history and potential. This knowledge will be crucial for infusing your weapon with additional power. Bring me those resources as swiftly as you can. The wind guides us to victory!", ["rewardItems"] = { 146745 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7745 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1469, ["db2PoiUiMapID"] = 726, ["questLines"] = { { ["id"] = 211, ["name"] = "Artifact Research", ["orderIndex"] = 47, ["flags"] = 0 } } },
