[46206] = { ["id"] = 46206, ["name"] = "Whispers of a Frightened World", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 46206 }, ["description"] = "\"Champion! Azeroth needs our help.\" <Magni Bronzebeard's words echo in your mind, as if rising from somewhere deep and ancient. Azeroth's world soul seeks to deliver a warning to the Speaker, but some force is interfering with the message.> <Magni has urged you to travel to Sholazar Basin, the vibrant heart of frozen Northrend, to aid him.>", ["objectivesText"] = "Meet Magni in Sholazar Basin and hear the warning.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 151789 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
