[46291] = { ["id"] = 46291, ["name"] = "The Deadmines Strike Back", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8630, ["mapID"] = 52, ["storyline"] = { 46291 }, ["series"] = { 46293 }, ["description"] = "Breanni sent you? For her, info is always free. Just don't call me a snitch. I've been hangin' around the Deadmines for years. For the most part, it's a pretty easy livin'. But a few days ago, I started hearing noises of all sorts comin' from the mines. If you want to get in unnoticed, I'll grab us a mine cart and we can get most of the way down without so much as an awkward glace in our direction. Just let me know when you're ready to head in.", ["objectivesText"] = "Defeat Cookies' Leftovers in the Deadmines. Progress: I can sneak you in. Getting out might be more of a challenge.", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 122457 }, ["starts"] = { { ["mapID"] = 52, ["npcID"] = 119390, ["x"] = 0.415, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 52, ["npcID"] = 119390, ["x"] = 0.415, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 52, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 52 }, ["zone"] = { 8630 } }, ["questType"] = "standard" },
[46292] = { ["id"] = 46292, ["name"] = "Pet Battle Challenge: Deadmines", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8630, ["mapID"] = 52, ["storyline"] = { 46292 }, ["description"] = "The Deadmines could still use some cleaning up, seems you didn't clear the place out last time. We'll use the ol' mine cart trick again. Cept, we're going to put some flair into it. How do you feel about fire? No? Okay, fine. Just let me know when you're ready.", ["objectivesText"] = "Defeat Cookies' Leftovers in the Deadmines. Progress: I can sneak you in. Getting out might be more of a challenge.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 86143, 90173, 151191 }, ["starts"] = { { ["mapID"] = 52, ["npcID"] = 119390, ["x"] = 0.415, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 52, ["npcID"] = 119390, ["x"] = 0.415, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 52, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 52 }, ["zone"] = { 8630 } }, ["questType"] = "standard" },
[46293] = { ["id"] = 46293, ["name"] = "Deadmines, Part Three?", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 52, ["storyline"] = { 46293 }, ["series"] = { 46291 }, ["description"] = "I've heard suspicious rumors of movement in the Deadmines. After everything you pulled off in the Wailing Caverns, you'd be the perfect person to look into this! I have a friend in Westfall. He may not look like much, but he's quick as a whip and may have more information on what is happening in Westfall. We've already dealt with the Van Cleefs... twice. So what could be making that sort of ruckus down there?", ["objectivesText"] = "Find Marcus \"Bagman\" Brown outside the Deadmines in Westfall.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 122457 }, ["ends"] = { { ["mapID"] = 52, ["npcID"] = 119390, ["x"] = 0.415, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 52, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 52 }, ["zone"] = { 7502 } }, ["questType"] = "standard" },
