[46683] = { ["id"] = 46683, ["name"] = "Starweave and Shadowcloth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46683 }, ["series"] = { 46679, 46680, 46682 }, ["description"] = "At last, you are ready for true tailoring knowledge. I truly think you've earned it. I've fashioned the materials you've gathered into a satchel of Legendary Tailor's Materials . Go to the Queen's Grace Loom and weave two bolts of cloth. With my careful research of fashion, heroes, and legends. I believe the new cloth you will make will echo through the ages. Hurry!", ["objectivesText"] = "Make a bolt of Starweave and a bolt of Shadowcloth . Progress: Please make a bolt of Starweave and a bolt of Shadowcloth at the loom as soon as you can and bring it back to me for final inspection.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 146659, 146666, 146710, 146711, 146952, 147437, 147451 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46684] = { ["id"] = 46684, ["name"] = "The Legend of the Elderhide", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46684 }, ["description"] = "Leatherworking is one of the oldest forms of craftsmanship in the world. Hides of animals were the first clothing. Legends tell of a particular form of leather curing that has been lost to us in modern times. Combining magic of the earth with some of the finest leathers ever found, this technique has been recreated by yours truly through careful analysis and my understanding of style. To begin, you must capture some ancient wisps to channel the exact nature magic for the curing process.", ["objectivesText"] = "Capture Ancient Wisps in Val'sharah. Progress: Have you found an Ancient Wisp ?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 124113, 124124, 146659, 146669, 146712 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46687] = { ["id"] = 46687, ["name"] = "The Wisp and the Nightmare", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46687 }, ["series"] = { 46685, 46686, 46688, 46689 }, ["description"] = "Xavius, the Nightmare Lord in Val'Sharah, derives some of his power from his spellsash. It is enchanted and tied to the world beneath his feet and cannot be removed from his body. However, with the ancient wisp's help, the spellsash can be removed if you can but defeat Xavius in combat. Trivial for one of your skill, I'm sure. Take the wisp to the Emerald Nightmare, take the spellsash, and use your skills to repair any damage you've caused in the battle.", ["objectivesText"] = "Get the spellsash from Xavius in the Emerald Nightmare and repair it. Progress: <name>, defeat Xavius and obtain his spellsash for me. Make sure that it is repaired to perfect condition!", ["rewardGold"] = 295000, ["rewardXP"] = 6140, ["rewardItems"] = { 146690, 146691 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46688] = { ["id"] = 46688, ["name"] = "Leather of the Ancients", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46688 }, ["series"] = { 46685, 46686, 46687, 46689 }, ["description"] = "<name>, we are going to need high quality leather to work with. Ancient Dreadleather is the best hereabouts and local tanning techniques were exceptional in the past. To the untrained eye, it may look like normal dreadleather. That is where the wisp comes in. Many of your enemies across Broken Shore will have some amount of Ancient Dreadleather . As you defeat them, you will start to recognize armor made from it and you can harvest the leather for our purposes.", ["objectivesText"] = "Obtain 100 pieces of Ancient Dreadleather from humanoids in Broken Shore. Progress: Keep your eye out for ancient dreadleather . We will need a good amount for our purposes.", ["rewardGold"] = 292100, ["rewardXP"] = 6140, ["rewardItems"] = { 146692, 146693, 147451 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46691] = { ["id"] = 46691, ["name"] = "The Owl and the Traitor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46691 }, ["series"] = { 46692, 46693, 46694, 46695 }, ["description"] = "I've scoured the tales and legends for armor that might have Wardenscale components and one Cordana Felsong is a name that caught my attention. Evidently she has a family mantle that has what we need. Kill her and find it on her traitor's corpse. The owl will make sure that you spot it. It is likely chipped from years of hard use so restore it to prime condition and bring it back to me.", ["objectivesText"] = "Find and repair Cordana Felsong's Mantle in the Vault of the Wardens in Mythic difficulty. Progress: Have you gotten Cordana's mantle and restored it yet? Rumor has it she is in the Vault of the Wardens.", ["rewardGold"] = 63800, ["rewardXP"] = 6140, ["rewardItems"] = { 146694, 146695 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46698] = { ["id"] = 46698, ["name"] = "The Dragonhunter", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46698 }, ["series"] = { 46697, 46699, 46700, 46701 }, ["description"] = "The Dragonhunter lived in a time before history was written and her tale was passed down orally to us. It seems that dragons tormented her people and after her village temple was destroyed, she rallied the local tribes, became a queen and killed all of the dragons. She was then banished for some reason and wandered until her death, alone. What proves the story is a piece of draconic slag from left over from a metal idol in her birth village. Dargul the Underking has it now. Forge a hammer from it.", ["objectivesText"] = "Defeat Dargul in Neltharion's Lair in Mythic difficulty and create a hammer from his Red-Hot Draconic Slag Progress: Did you find the draconic slag from the Dragonhunter's birth village temple? When you do, forge a hammer from it.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146704, 146705 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46699] = { ["id"] = 46699, ["name"] = "The Hellslayer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46699 }, ["series"] = { 46697, 46698, 46700, 46701 }, ["description"] = "The Hellslayer's tale is a classic story of revenge. Odyn wished to take the souls of the bravest as champions but Helya sent her kvaldir to take the souls first. The people of Stormheim suffered as their pawns. The kvaldir came to the Hellslayer's ship at night and killed her son and took his soul to serve Helya for eternity. The Hellslayer took up her axe and the spear of her son and sought vengeance. Finish her quest. Defeat Helya and forge a hammer from the Frostveined Shale .", ["objectivesText"] = "Defeat Helya and forge a hammer from the Frostveined Shale in the Trial of Valor. Progress: The Frostveined Shale is what remains of the Hellslayer's weapons after they were destroyed on Helya's cold forge. It is powerful stuff and we need it.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146706, 146707 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46701] = { ["id"] = 46701, ["name"] = "Hammer of Forgotten Heroes", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46701 }, ["series"] = { 46697, 46698, 46699, 46700 }, ["description"] = "<name>, this is exciting, I have to admit. I've put everything you've gathered into this chest of supplies and the only place with the power and magic to handle the creation of the final hammer is the Firmament Stone. I believe that blacksmiths of your rarified skills will know it? I realize that there are dwarf stereotypes out there about smithing but I really don't care for all of the banging and heat. Suppose that is why I followed the scholarly path. Good luck to you!", ["objectivesText"] = "Go to the Firmament Stone in Highmountain and forge the Hammer of Forgotten Heroes . Progress: Be sure to take the chest of supplies I've given you to the Firmament Stone and forge the final hammer. Bring it back to me for inspection when you have done so.", ["rewardGold"] = 286500, ["rewardXP"] = 6140, ["rewardItems"] = { 146667, 146714, 147207, 147443 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
