[46743] = { ["id"] = 46743, ["name"] = "Supplies From Highmountain", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7731, ["storyline"] = { 46743 }, ["description"] = "Champion, your help to our people has far exceeded any of our expectations, and has provided us some much needed breathing space. Please, take these supplies to aid you in the war against the Legion. With your continued aid, we should be able to gather more and prepare them for you.", ["objectivesText"] = "Speak with Ransa Greyfeather in Highmountain for your reward.", ["rewardItems"] = { 152104, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2085, ["threshold"] = 10000 } } } },
[46745] = { ["id"] = 46745, ["name"] = "Supplies From the Court", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 46745 }, ["description"] = "Prince Farondis has asked me to thank you for your continued efforts to aid our lands. Please take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", ["objectivesText"] = "Speak with Veredis Fallon in Azsuna for your reward.", ["rewardItems"] = { 152102, 180648, 237812 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 107376, ["x"] = 0.468, ["y"] = 0.414 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.414 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2087, ["threshold"] = 10000 } } } },
[46746] = { ["id"] = 46746, ["name"] = "Supplies From the Valarjar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 46746 }, ["description"] = "Greetings, little hero. The mighty Odyn has proclaimed that you should receive these gifts of war. At every turn you continue to prove your valor and your efforts to aid the Valarjar have not gone unnoticed. For the Valarjar! For Odyn! For <name>!", ["objectivesText"] = "Speak with Valdemar Stormseeker in Stormheim for your reward.", ["rewardItems"] = { 152106, 237812 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 106904, ["x"] = 0.602, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2086, ["threshold"] = 10000 } } } },
