[46748] = { ["id"] = 46748, ["name"] = "Supplies From the Nightfallen", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 46748 }, ["description"] = "Outlander, I have some supplies for you. These goods are yours, earned by your continued efforts to our forces here in Suramar . I shall set aside similar treasures should you choose to aid our people more. You have my deepest thanks.", ["objectivesText"] = "Speak with First Arcanist Thalyssra in Suramar for your reward.", ["rewardItems"] = { 152105, 237812 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2089, ["threshold"] = 10000 } } } },
