[46804] = { ["id"] = 46804, ["name"] = "Fashion History and a Philosophy of Style", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46804 }, ["description"] = "Greetings, <name>. I am a fashion historian and I have astonishing advancements in tailoring, leatherworking, and blacksmithing that I must share with you. Why? A true legend is only as good as their ability to form an epic silhouette on the battlefield and--let's be honest--this is not where you shine. Speak to me again if you wish to learn.", ["objectivesText"] = "Learn from Eliezer Hammerbeard how to create \"flair and drama\" in your wardrobe. Progress: Let me know when you are ready to begin your education. You sorely need it!", ["rewardXP"] = 770, ["rewardItems"] = { 146659, 146712, 146713, 147451 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46805] = { ["id"] = 46805, ["name"] = "The Deceiver's Downfall", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46805 }, ["description"] = "Once he was as a brother to me. Then he bartered the soul of my world for his own power. Hounded my people across the stars. Twisted my son into a monster. Now he has come to oversee the final assault on Azeroth. To end this world as he has countless others. Kil'jaeden. We must ensure he does not escape our grasp this time, <name>. Storm the tomb. Break the Legion's hold. End the Deceiver's reign.", ["objectivesText"] = "Enter the Tomb of Sargeras and defeat Kil'jaeden. Progress: Give no quarter. The Deceiver must fall.", ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120372, ["x"] = 0.445, ["y"] = 0.633 }, { ["mapID"] = 619, ["npcID"] = 122800, ["x"] = 0, ["y"] = 0 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120372, ["x"] = 0.445, ["y"] = 0.633 }, { ["mapID"] = 619, ["npcID"] = 122800, ["x"] = 0, ["y"] = 0 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.633 }, ["mapCandidates"] = { ["npc"] = { 619, 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
