[47002] = { ["id"] = 47002, ["name"] = "The Crown of the Triumvirate", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["storyline"] = { 47002 }, ["description"] = "We begin our search now, <name>. The Crown of the Triumvirate was created to spread the Light's touch to all. With it, our culture thrived. When I fled Argus with the Draenei, I took one shard of the Crown with me to ensure that it would not fall into the wrong hands. <Velen tips his staff forward and gestures to the central crystal.> Kil'jaeden and Archimonde's fragments are still here. I will seek them out, but you will need to safeguard me while I search. Stay close, my friend.", ["objectivesText"] = "Protect Velen while he locates fragments of the Crown of the Triumvirate.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard" },
