[47097] = { ["id"] = 47097, ["name"] = "A Walk to Remember", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46268, 46272, 46274, 46275, 46282, 47097, 47112, 47202 }, ["description"] = "It's good to have you at my side, <name>. I've come to the Broken Shore to see, for myself, the price that my father... that the Alliance has paid to protect our world. As long as I am blind to the suffering and sacrifices of my people, I will never be able to lead them to peace. Time is short, we should move onward.", ["objectivesText"] = "Escort King Anduin to Soul Ruin at the Broken Shore.", ["rewardXP"] = 6140, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 121224, ["x"] = 0.414, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 121226, ["x"] = 0.525, ["y"] = 0.484 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 347, ["name"] = "The King's Path", ["orderIndex"] = 5, ["flags"] = 0 } } },
[47104] = { ["id"] = 47104, ["name"] = "Imprisoned Inquisitor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47104, 47134, 47182, 47287, 47554 }, ["series"] = { 47102, 47134, 47182, 47554 }, ["description"] = "This report states that the Legion seeks to free an imprisoned Legion inquisitor called Raalgar, a demon from here on Argus who cannot be killed because of a secret magic he alone possesses. Because of his immortality, he is held in the Arcatraz in Tempest Keep. The Light Mother told us of that naaru stronghold, but I've never set eyes upon it myself, <name>. Turalyon mentioned the Vindicaar has some connection to Tempest Keep. Perhaps your ship's engineer knows more.", ["objectivesText"] = "Travel to the Vindicaar and ask Grand Artificer Romuul about High Inquisitor Raalgar.", ["rewardGold"] = 210675, ["rewardXP"] = 6140, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 121519, ["x"] = 0.405, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 886, ["questLines"] = { { ["id"] = 355, ["name"] = "The Legion Jailbreak", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47112] = { ["id"] = 47112, ["name"] = "Lost Souls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46268, 46272, 46274, 46275, 46282, 47097, 47112, 47202 }, ["description"] = "Never in my life have I beheld such destruction... such misery. The very ground we walk on us paved with the bones of our allies. Even now I can see the lost spirits of Alliance soldiers wandering the ruins. I cannot leave this place without putting the souls of our brave soldiers to rest. We owe them... I owe them that much.", ["objectivesText"] = "Release 10 Lost Souls .", ["rewardGold"] = 122850, ["rewardXP"] = 6140, ["rewardItems"] = { 181478, 181549, 181552, 181646, 181648, 181650, 181743, 184149, 184379, 184380, 184763, 184764 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 121226, ["x"] = 0.525, ["y"] = 0.484 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 121237, ["x"] = 0.590333, ["y"] = 0.262333 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 347, ["name"] = "The King's Path", ["orderIndex"] = 6, ["flags"] = 0 } } },
