[47148] = { ["id"] = 47148, ["name"] = "Something Different", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 15969, ["mapID"] = 2393, ["storyline"] = { 47148 }, ["description"] = "Even the most bloodthirsty combatants eventually grow weary and turn their backs to the unending struggle of war. They seek a new way to test their mettle and destroy their enemies. Join the Brawl in progress and fight your opponents in a limited time event that tosses traditional rules aside.", ["objectivesText"] = "Win a PvP Brawl. Progress: Even I could not foresee the strange ways in which you would fight your enemies <name>.", ["rewardItems"] = { 137642, 139781, 147203 }, ["starts"] = { { ["mapID"] = 2393, ["npcID"] = 254971, ["x"] = 0.362, ["y"] = 0.81 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 144383, ["x"] = 0.74, ["y"] = 0.145 }, { ["mapID"] = 1165, ["npcID"] = 144384, ["x"] = 0.565, ["y"] = 0.886 }, { ["mapID"] = 2112, ["npcID"] = 196191, ["x"] = 0.433333, ["y"] = 0.423333 }, { ["mapID"] = 2339, ["npcID"] = 219260, ["x"] = 0.588, ["y"] = 0.754 }, { ["mapID"] = 2393, ["npcID"] = 254971, ["x"] = 0.362, ["y"] = 0.81 } }, ["coords"] = { ["mapID"] = 2393, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.81 }, ["mapCandidates"] = { ["npc"] = { 1161, 1165, 2112, 2339, 2393 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
[47202] = { ["id"] = 47202, ["name"] = "A Personal Message", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 46268, 46272, 46274, 46275, 46282, 47097, 47112, 47202 }, ["description"] = "The time has come for me to travel to the Broken Shore and see, for myself, the place where my father died. If I am to be the king my father was... the king Stormwind deserves, I must know firsthand the threat my people face. Please tell my advisors that I've gone to the Broken Shore. If I told them myself they'd only try and stop me. I'll wait for you at Deliverance Point. Farewell.", ["objectivesText"] = "Speak with Prophet Velen .", ["rewardXP"] = 4605, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 120268, ["x"] = 0.854, ["y"] = 0.344667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 119340, ["x"] = 0.8625, ["y"] = 0.3465 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.854, ["y"] = 0.344667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 347, ["name"] = "The King's Path", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47251] = { ["id"] = 47251, ["name"] = "Interesting Times", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 440, ["mapID"] = 85, ["storyline"] = { 47251 }, ["description"] = "<name>, I don't mean to alarm you, but we may be experiencing some... temporal disturbances. Have you ever heard the phrase 'I hope the past doesn't come back to haunt you?' Come visit me in the Valley of Spirits and we can speak more.", ["objectivesText"] = "Meet with Historian Ju'Pa in the Valley of Spirits of Orgrimmar.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 128507, 147880, 147881 }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 110035, ["x"] = 0.365, ["y"] = 0.7445 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.7445 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne", ["startItems"] = { 147881 } },
