[47254] = { ["id"] = 47254, ["name"] = "The Originals", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 440, ["mapID"] = 85, ["storyline"] = { 47254 }, ["description"] = "Long ago, great terrors walked our lands, and drove even the smallest to flights of heroism. I speak, of course, about Lord Kazzak , Azuregos , and the Dragons of Nightmare. Legends have it that so sought after were their treasures, that armies would camp overnight to hunt them down. The dragons have felt disturbances in the timeways, coincidentally located where these giants once roamed. They have tasked me with finding champions to investigate.", ["objectivesText"] = "Defeat Lord Kazzak in Blasted Lands, Azuregos in Azshara, and the Dragon of Nightmare at one of the portals to the Emerald Dream. Progress: They're just memories, right?", ["rewardGold"] = 1366400, ["rewardXP"] = 8230, ["rewardItems"] = { 14344, 63207, 65274, 139552, 139590, 150393, 150417, 232877, 233014 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 110035, ["x"] = 0.365, ["y"] = 0.7445 }, { ["mapID"] = 71, ["npcID"] = 223882, ["x"] = 0.622, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 110035, ["x"] = 0.365, ["y"] = 0.7445 }, { ["mapID"] = 71, ["npcID"] = 223882, ["x"] = 0.622, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.365, ["y"] = 0.7445 }, ["mapCandidates"] = { ["npc"] = { 71, 85 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4063 }, ["db2QuestSortName"] = "Nightborne" },
