[47330] = { ["id"] = 47330, ["name"] = "Whispers of a Frightened World", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 47330 }, ["description"] = "Champion, Magni needs your help! The Speaker has a message for you, perhaps from Azeroth herself. He seems to be having trouble understanding her, but I'm sure he can explain everything better. He said he was in Sholazar Basin, in Northrend. He should be contacting you shortly.", ["objectivesText"] = "Meet Magni in Sholazar Basin and hear the warning. Progress: Yes, <name>? What news do you bring?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 151789 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 350, ["name"] = "Azeroth's Warning", ["orderIndex"] = 0, ["flags"] = 0 } } },
