[47523] = { ["id"] = 47523, ["name"] = "Disturbance Detected: Black Temple", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 3959, ["mapID"] = 111, ["storyline"] = { 47523 }, ["description"] = "<name>, right on time, as always. Good news first, because they're happening at the same time for me anyway. Thanks to the various timewarped objects past and future you discovered, we've figured out how to detect when a new one turns up. The bad news is, we know our technique works because something has changed in the Black Temple , and it's wreaking havoc across the timescape! We need you to ensure the fateful raid turns out exactly like it did before, and to remove the source of this disturbance.", ["objectivesText"] = "Relive the assault on the Black Temple . Progress: Be extra careful the raid on the temple turns out exactly like it did before. One extra flap of dragonfly wings, and you might end up killing Illidan for real! Then imagine the mess we'd be in!", ["rewardGold"] = 315900, ["rewardXP"] = 4115, ["rewardItems"] = { 32458, 97554, 97555, 122110, 122112, 133543, 150436, 150442, 150490, 150496, 150504, 150507, 150512, 150527, 150531, 150571, 150774, 171897, 171914, 208091, 224547 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 123252, ["x"] = 0.546, ["y"] = 0.3888 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 123252, ["x"] = 0.546, ["y"] = 0.3888 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.3888 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3959 } }, ["questType"] = "standard" },
