[47543] = { ["id"] = 47543, ["name"] = "The Day That Chromie Dies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 47543, 47545, 47550, 47904, 47906 }, ["series"] = { 47545, 47550 }, ["description"] = "Oh, <name>! I was just thinking about you! Talk about being at the right time in the right place! I was just reviewing some aberrations in the timeways, when I discovered something... unexpected. Something not-so-great. I'm going to die in the near future. Bad times. I was just about to jump ahead and see if I can figure out why, how, who... but I'd feel better with |5<race> like you by my side. Care to join me?", ["objectivesText"] = "Speak with Chromie , then travel to the future to find out how she dies. Progress: I'm sure I just fall into a hole or something. This wouldn't be the first time!", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 150938, 150939, 150940, 150941, 150943, 150945, 150946, 151141, 151166, 151167, 151168, 151370, 151692, 151693, 151694, 151695 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 27856, ["x"] = 0.6, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 27856, ["x"] = 0.6, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 352, ["name"] = "The Deaths of Chromie", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47545] = { ["id"] = 47545, ["name"] = "Rewind", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 47543, 47545, 47550, 47904, 47906 }, ["series"] = { 47543, 47550 }, ["description"] = "Now we know when the attack happens, and vaguely where it's coming from. Progress! All we need to do now is to find out more details and stop that attack! Let me know when you're ready to try again.", ["objectivesText"] = "Speak with Chromie again, then travel to the future and gather information from the other Wyrmrest emissaries. Progress: I sure hope we don't cause a paradox!", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 150938, 150939, 150940, 150941, 150943, 150945, 150946, 151141, 151166, 151167, 151168, 151370, 151692, 151693, 151694, 151695, 166846, 166970, 166971, 204196, 208390, 246697 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 27856, ["x"] = 0.6, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 27856, ["x"] = 0.6, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 352, ["name"] = "The Deaths of Chromie", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47550] = { ["id"] = 47550, ["name"] = "The Many Advantages of Being a Time Dragon", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 47543, 47545, 47550, 47904, 47906 }, ["series"] = { 47543, 47545 }, ["description"] = "Well, unfortunately for... whomever is fixated on blasting me into oblivion, I am a fairly skilled master of the timeways! We have the advantage of trying that again, and again, and again, until I'm not dead anymore. We're going to need a little more than a few seconds to stop this attack. How does four hours sound?", ["objectivesText"] = "Speak with Chromie a third time, then travel to the future and attempt to save her again.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 150938, 150939, 150940, 150941, 150943, 150945, 150946, 151141, 151166, 151167, 151168, 151370, 151692, 151693, 151694, 151695 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 27856, ["x"] = 0.6, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1756, ["db2PoiUiMapID"] = 897, ["questLines"] = { { ["id"] = 352, ["name"] = "The Deaths of Chromie", ["orderIndex"] = 2, ["flags"] = 0 } } },
