[47557] = { ["id"] = 47557, ["name"] = "Smoldering Chronoshard", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 47557 }, ["description"] = "This shard of crystal is hot to the touch. The void creature that carried it wasn't a wielder of flame in any noticeable way, so perhaps the chronoshard is related to fire in some other way.", ["objectivesText"] = "Bring the Smoldering Chronoshard to Wyrmrest to unlock a time portal.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 150943 } },
