[47591] = { ["id"] = 47591, ["name"] = "Wanna Buy a Lamp?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 47591 }, ["description"] = "Ey dere, wanna buy a lamp? You be not regrettin' it.", ["objectivesText"] = "Purchase the Dubious Lamp from Griftah . Progress: I promise ya don' regret dis.", ["rewardItems"] = { 113575, 120857, 138954, 151131, 151143, 151144, 151146, 151165, 151180, 151569, 151633, 151749, 151877 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[47592] = { ["id"] = 47592, ["name"] = "Shine Bright Like a Diamond", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 47592 }, ["description"] = "Oh, I be sorry. Dat lamp look like it could use some shinin'. I happen to have just da ting.", ["objectivesText"] = "Purchase a Certified Organic Lamp Shining Kit from Griftah and use it to shine the Grimy Lamp. Progress: I'm sure dis will all be worth it.", ["rewardItems"] = { 151181 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[47594] = { ["id"] = 47594, ["name"] = "I'll Take Those, Thanks!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 47594 }, ["description"] = "These coins, dey be vanishin' inta air ya say? Dat be soundin' perfect, as I have jus the fella ta give dem to.", ["objectivesText"] = "Obtain 10,000 Coins of Air for Griftah . Progress: Oh man, I can't wait to use these. I be thankin' you.", ["rewardGold"] = 16176000, ["rewardItems"] = { 151163 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[47595] = { ["id"] = 47595, ["name"] = "I Don't Need Them, But I'll Take Them", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 47595 }, ["description"] = "If you wanna collect more, Griftah not gonna argue with dat. Dat bein' said, I don't need dem as much anymore, so I be givin' you less for dem.", ["objectivesText"] = "Collect 10,000 Coins of Air for Griftah . Progress: Another batch, huh? You be really enthusiastic about dese.", ["rewardGold"] = 656493, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[47603] = { ["id"] = 47603, ["name"] = "The Mysterious, Magnificent Al'Abas", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 47603 }, ["description"] = "I see you, puny mortal! I appreciate your concern for my lamp!", ["objectivesText"] = "Speak to Al'Abas . Progress: The very world trembles, trembles with the weight of magic. Their pockets are full of it.", ["rewardItems"] = { 151197 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[47604] = { ["id"] = 47604, ["name"] = "In the Land of Magic", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 47604 }, ["description"] = "I think I see the problem. Your puny eyes are too weak to detect the mana-infused finery that these elves have spread throughout the land. They've been wearing jewelry the entire time, and you simply couldn't see it. I propose a partnership, my newly minted associate. My lamp currently suffers from an embarrassing lack of magic and could always use more beautiful decorations. I propose a trade. I shall pierce this sinister veil, and you shall give me the spoils of your theft.", ["objectivesText"] = "Speak to Al'Abas ... again.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[47605] = { ["id"] = 47605, ["name"] = "Coins of Air", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 47605 }, ["description"] = "I would be much interested in these magical trinkets that reside in the pockets of the denizens of this land, and humbly offer my services in helping you acquire them, <name>. However, I sadly cannot pay you in the coin of this realm. What I can offer are ephemera - coins of purest air. They're better than nothing, though! Carry my lamp with you. Drop the treasures you steal within, and I will grant you these coins. Perhaps the former owner of my lamp would have a use for them.", ["objectivesText"] = "Speak to Al'Abas yet again.", ["rewardItems"] = { 151131 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[47606] = { ["id"] = 47606, ["name"] = "Loyalty Is Its Own Reward", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 47606 }, ["description"] = "I offer you a challenge, mortal. Obtain a thousand of my coins, and I believe that I can empower my lamp and the vision within.", ["objectivesText"] = "Obtain a thousand Coins of Air . Progress: My goodness, already!?", ["rewardItems"] = { 151131, 151143, 151158, 151159, 151160, 151161, 151162, 151163, 151165 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[47607] = { ["id"] = 47607, ["name"] = "High Fash-Djinn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 47607 }, ["description"] = "With my newly empowered lamp, I sense further, more valuable trinkets in the pockets of these elves and demons. Fetch them for me!", ["objectivesText"] = "Find rare treasures in the pockets of the denizens of the Broken Isles. Progress: Well, well, well. You continue to amuse and amaze, mortal.", ["rewardItems"] = { 151143, 151144, 151158, 151159, 151160, 151161, 151162, 151163, 151164 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
