[47642] = { ["id"] = 47642, ["name"] = "Soul Crystal", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 47642 }, ["description"] = "<The three shards combine neatly into a large crystal. Once reassembled, the image of a powerful lich appears above the crystal's surface.> <The lich speaks:> Keep the Ruby Shrinewardens occupied. I shall carry out our master's attack from within the great tree itself.", ["objectivesText"] = "Seek out the lich hidden within the Ruby Dragonshrine's tree.", ["rewardItems"] = { 150938, 150939, 150940, 150941, 150943, 150945, 150946, 151141, 151166, 151167, 151168, 151370, 151692, 151693, 151694, 151695 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 150940 } },
[47643] = { ["id"] = 47643, ["name"] = "The Ancients' Wisdom", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["storyline"] = { 47643 }, ["description"] = "The three ancients left three clues: \"...the great nightmare...\" \"...by the water...\" \"...within the dragon's palm...\" Perhaps Chromie 's attacker lies in the place the ancients describe?", ["objectivesText"] = "Seek out the satyr hidden in the Emerald Dragonshrine.", ["rewardItems"] = { 150938, 150939, 150940, 150941, 150943, 150945, 150946, 151141, 151166, 151167, 151168, 151370, 151692, 151693, 151694, 151695 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[47644] = { ["id"] = 47644, ["name"] = "Demonic Corestone", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 47644 }, ["description"] = "<Deep within the demonic corestone, the image of a dreadlord speaks ominously:> Yes, master. It shall be done, at the exact time that you specified. The bronze dragon will see nothing. One shot from outside the Obsidian Dragonshrine is all I require.", ["objectivesText"] = "Uncover the dreadlord hidden near the entrance to the Obsidian Dragonshrine's cave.", ["rewardItems"] = { 150938, 150939, 150940, 150941, 150943, 150945, 150946, 151141, 151166, 151167, 151168, 151370, 151692, 151693, 151694, 151695 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 150938 } },
[47645] = { ["id"] = 47645, ["name"] = "Voidcallers' Scroll", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 47645 }, ["description"] = "<The scroll pieces combine to form a tattered, but readable message:> The time is nigh. The invocation will take place above the azure shrine. The void will swallow the bronze dragon. Our master has spoken, and we obey.", ["objectivesText"] = "Seek out the creature of void hidden above the Azure Dragonshrine.", ["rewardItems"] = { 150938, 150939, 150940, 150941, 150943, 150945, 150946, 151141, 151166, 151167, 151168, 151370, 151692, 151693, 151694, 151695 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 150941 } },
