[47663] = { ["id"] = 47663, ["name"] = "A Timely Summons from Shattrath", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 111, ["storyline"] = { 47663 }, ["description"] = "The blazing star holds a peculiar alignment this cycle, calling out across the heavens. Seek out the sage Vormu in Shattrath City , and lend her your aid.", ["objectivesText"] = "Meet with Vormu in Shattrath. Progress: I foresee you will need the strength of many allies to walk this path.", ["rewardGold"] = 30900, ["rewardXP"] = 25, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 123252, ["x"] = 0.546, ["y"] = 0.3888 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.3888 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 7502 } }, ["questType"] = "standard" },
