[47709] = { ["id"] = 47709, ["name"] = "The Great Gnomeregan Run", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6457, ["mapID"] = 469, ["storyline"] = { 47709 }, ["description"] = "Ready for the big race today, <name>? Every year, gnomes from near and far gather to run all the way from Gnomeregan to Booty Bay! It reminds us that no goal is too tall, even for us! Whether you run fast or slow, alone or with friends, you'll make it as long as you keep trying! So make sure to stretch, then get out there and show the world what we gnomes are made of!", ["objectivesText"] = "Race to Booty Bay.", ["rewardGold"] = 619600, ["rewardXP"] = 250, ["starts"] = { { ["mapID"] = 469, ["npcID"] = 124280, ["x"] = 0.364, ["y"] = 0.364 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 124257, ["x"] = 0.401, ["y"] = 0.726 }, { ["mapID"] = 210, ["npcID"] = 156018, ["x"] = 0.4, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 469, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.364 }, ["mapCandidates"] = { ["npc"] = { 210, 469 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiMapID"] = 369, ["db2PoiUiMapID"] = 499, ["questLines"] = { { ["id"] = 447, ["name"] = "The Great Gnomeregan Run", ["orderIndex"] = 0, ["flags"] = 0 } } },
