[47744] = { ["id"] = 47744, ["name"] = "Smoke, Meat, and Pretty Flowers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 9051, ["storyline"] = { 47744 }, ["series"] = { 47745 }, ["description"] = "Back of town's on lockdown, kid. And yes, I do have a key, but you're a stranger. <Emery pats his pocket gingerly.> Listen, I'd like to help you out. You've got an honest look to you. Fetch me some venison, some pipe tobacco, and a bundle o' yellow flowers, and I might be able to make an exception.", ["objectivesText"] = "Obtain some Salted Venison Jerky , Grimm's Special Pipe Blend , and a Marigold Bouquet . Progress: You're not in a hurry, are you?", ["rewardItems"] = { 151280, 151281, 151287, 151493 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9051 } }, ["questType"] = "standard" },
[47745] = { ["id"] = 47745, ["name"] = "Yeah, Definitely for the Kids", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 9051, ["storyline"] = { 47745 }, ["series"] = { 47744 }, ["description"] = "I don't know if you've ever seen Orphan Matron Meliana before, but she is a goddess come down to humble Lordaeron. Her hair, those cheekbones, and... ...and anyhow, these flowers are for the kids at the orphanage where she works. Tell Meliana that they're from me. For the kids.", ["objectivesText"] = "Deliver the Marigold Bouquet to Orphan Matron Meliana . Progress: What's this?", ["rewardItems"] = { 151287 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9051 } }, ["questType"] = "standard" },
[47746] = { ["id"] = 47746, ["name"] = "Holing Up", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 9051, ["storyline"] = { 47746 }, ["series"] = { 47747, 47750 }, ["description"] = "Did... did you see that? Prince Arthas just struck that person down in cold blood! Right in the middle of the street! <Meliana regains her composure.> I need to protect the children. Please, help us, visitors. I need a gun, bandages, and some venison jerky. Children! Everybody, get into the house!", ["objectivesText"] = "Obtain a Refurbished Military Rifle , Basic Cloth Bandages , and Salted Venison Jerky . Progress: The children are priority one.", ["rewardItems"] = { 151281, 151282, 151283, 151493 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9051 } }, ["questType"] = "standard" },
[47747] = { ["id"] = 47747, ["name"] = "Fight Plague with Fire", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 9051, ["storyline"] = { 47747 }, ["series"] = { 47746, 47750 }, ["description"] = "One final request of you, stranger. I've seen what's happening outside, and I've heard about this \"plague\". I don't want to go down without a fight. I have enough rum in the back of this bar to set this whole tavern on fire, but I don't have the tools to do it safely. Fetch me a flint and some rope, and I'll give you my key to the backstreets of Stratholme.", ["objectivesText"] = "Obtain a Flinty Firestarter and some Heavy Straw Rope . Progress: Mad Prince or drooling zombie - nobody's going to take this bar away from me without a fight!", ["rewardItems"] = { 151284, 151286, 151347 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9051 } }, ["questType"] = "standard" },
