[47750] = { ["id"] = 47750, ["name"] = "For Emery", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 9051, ["storyline"] = { 47750 }, ["series"] = { 47746, 47747 }, ["description"] = "We do have plenty of food here, however. If you're braving the streets, please deliver this venison to that big dummy at the tavern. Tell him it's from the kids.", ["objectivesText"] = "Deliver the Salted Venison Jerky to Emery Neill . Progress: Say, what've you got there?", ["rewardItems"] = { 151281 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9051 } }, ["questType"] = "standard" },
