[47772] = { ["id"] = 47772, ["name"] = "Sky Ablaze With Cannonfire", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 9051, ["storyline"] = { 47772 }, ["description"] = "Oh! It's me! And <name>, was it? I remember this! I seem to have found myself in the middle of a battle between the Horde and the Alliance, which wouldn't USUALLY be a big deal, except for that enormous cannon that seems to be trained on me anytime I try to fly away. Think you could take it out for me?", ["objectivesText"] = "Destroy the Horde Siege Cannon. Progress: Any luck? I just need the Horde cannon taken disabled if I want to escape.", ["rewardItems"] = { 6364, 33820, 118391, 133755, 150938, 150939, 150940, 150941, 150943, 150945, 150946, 151141, 151166, 151167, 151168, 151368, 151369, 151370, 151493, 151692, 151693, 151694, 151695 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9051 } }, ["questType"] = "standard" },
