[47807] = { ["id"] = 47807, ["name"] = "Worried About My Friends", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 9051, ["storyline"] = { 47807 }, ["description"] = "I've heard about some trouble over at the black dragonshrine. I know, I'm a bronze dragon, but still! I worry about them sometimes! They weren't ALWAYS so grumpy. If you're going there anyways, would you mind taking care of... whatever's causing so much of a disturbance?", ["objectivesText"] = "Slay Zorathides at the Obsidian Dragonshrine. Progress: I don't know what I'd do without my aspect. Must be tough.", ["rewardItems"] = { 151493 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9051 } }, ["questType"] = "standard" },
[47808] = { ["id"] = 47808, ["name"] = "The Dead Walk", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 9051, ["storyline"] = { 47808 }, ["description"] = "Greetings, <race>. I know you are here in the service of the bronze, but I have a request of you. The Ruby Dragonshrine is plagued by undead. My shrine's wardens were unprepared, and we risk losses if an intervention is not done quickly. Would you assist us?", ["objectivesText"] = "Slay Talar Icechill at the Ruby Dragonshrine. Progress: Thank you for hearing my request.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 35884, 35885, 35886, 35887, 151493 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9051 } }, ["questType"] = "standard" },
[47809] = { ["id"] = 47809, ["name"] = "Darkness in the Ley", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 9051, ["storyline"] = { 47809 }, ["description"] = "A strange, dark disturbance perturbs the ley lines in my flight's dragonshrine. Do you have the time to investigate?", ["objectivesText"] = "Slay the Void Gargantuan at the Azure Dragonshrine. Progress: < Kalecgos eyes you cautiously.>", ["rewardItems"] = { 151493 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9051 } }, ["questType"] = "standard" },
[47810] = { ["id"] = 47810, ["name"] = "Darkened Dreams", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 9051, ["storyline"] = { 47810 }, ["description"] = "The ancients at the Emerald Dragonshrine suffer in their dreams. With Ysera gone, I am shorthanded and unable to investigate the matter myself. Would you help me cleanse the nightmare from the Emerald Dragonshrine?", ["objectivesText"] = "Slay Thalas Vylethorn at the Emerald Dragonshrine. Progress: I appreciate you taking the time to listen to my concern, <race>.", ["rewardItems"] = { 151493 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9051 } }, ["questType"] = "standard" },
