[47851] = { ["id"] = 47851, ["name"] = "Sealing Fate: Marks of Honor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 47851 }, ["objectivesText"] = "Progress: These seals provide an additional chance at treasure in dungeons and raids, but at what cost? Killing others isn't honorable, and yet you collect marks for honor? I suppose I can use those marks for an additional treasure. That is the offer I present. Remember, you can only obtain three seals per week. This counts as one of those three. Next week, I will have others.", ["rewardItems"] = { 137642 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
