[47895] = { ["id"] = 47895, ["name"] = "Bert's Bots", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1, ["storyline"] = { 47895 }, ["description"] = "If I'm going to clean up Gnomeregan, I've got to be ready to battle all manner of rat, roach, and potentially even the dreaded mutant rat-roach. What I'm saying is that I need to put these bots to the test! A real, live-action field demo. Are your pets up for a code review?", ["objectivesText"] = "Defeat Bert in a pet battle. Progress: Better bots, by Bert!", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 151638, 151645 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Epic" },
[47904] = { ["id"] = 47904, ["name"] = "Preserve the True Future", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 47543, 47545, 47550, 47904, 47906 }, ["series"] = { 47906 }, ["description"] = "I know how this looks, <name>. I'm not asking for your help simply because I don't want to get killed. I need your help because this isn't how I'm SUPPOSED to die. I will die - I've seen it! - but it happens much later than this. Besides, meddling with the timeways for personal reasons - well, it goes against pretty much everything my dragonflight stands for. Let's stop all four of the dragonshrine attacks. That should do the trick.", ["objectivesText"] = "Stop the attacks from the Obsidian, Ruby, Azure, and Emerald Dragonshrines in one attempt of the Deaths of Chromie scenario.", ["rewardGold"] = 842700, ["rewardXP"] = 9210, ["rewardItems"] = { 150938, 150939, 150940, 150941, 150943, 150945, 150946, 151141, 151166, 151167, 151168, 151370, 151482, 151493, 151550, 151554, 151692, 151693, 151694, 151695, 151828, 151829 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 27856, ["x"] = 0.6, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 27856, ["x"] = 0.6, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 352, ["name"] = "The Deaths of Chromie", ["orderIndex"] = 3, ["flags"] = 0 } } },
[47906] = { ["id"] = 47906, ["name"] = "The Deaths of Chromie", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 47543, 47545, 47550, 47904, 47906 }, ["series"] = { 47904 }, ["description"] = "It looks like we're going to have to stop all eight attacks on me. In one fifteen-minute span. Even to me, that doesn't seem like a lot of time. Still, if anybody can do it, it's us. Are you ready, <name>?", ["objectivesText"] = "Stop all eight attacks on Chromie in one attempt in the Deaths of Chromie scenario.", ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["rewardItems"] = { 124634, 124635, 124636, 124637, 124638, 150938, 150939, 150940, 150941, 150943, 150945, 150946, 151141, 151166, 151167, 151168, 151370, 151482, 151493, 151546, 151549, 151550, 151554, 151692, 151693, 151694, 151695, 151828, 151829 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 27856, ["x"] = 0.6, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 27856, ["x"] = 0.6, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 352, ["name"] = "The Deaths of Chromie", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47953] = { ["id"] = 47953, ["name"] = "Tereck the Selector", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite", "rare" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47953 }, ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "world", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["db2QuestInfoID"] = 136, ["db2QuestInfoName"] = "Rare Elite World Quest" },
[48002] = { ["id"] = 48002, ["name"] = "Limited Supplies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 48002, 48013, 48016 }, ["series"] = { 48013, 48016 }, ["description"] = "Hello, <name>. It's good to see a fellow alchemist again. I've been supplying our camp with necessary potions to deal with the demons, but lately I've been running low on supplies. Normally when scouting parties go out, they return with empty vials, but as of late fewer have been returning. I try to recycle as much as I can, so you see, those vials are precious to me. If you'd be willing to go out and retrieve them, I could show you what I've been making to help combat the demons.", ["objectivesText"] = "Go to the Petrified Forest and reclaim 12 Used Vials . Progress: How goes the search? Any luck on finding my vials?", ["rewardItems"] = { 151608, 151845 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 125346, ["x"] = 0.562, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 125346, ["x"] = 0.562, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 357, ["name"] = "Legion Alchemy", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48013] = { ["id"] = 48013, ["name"] = "Tracking the Trackers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 48002, 48013, 48016 }, ["series"] = { 48002, 48016 }, ["description"] = "<name>, have I told you about my tracking potion? Our scouts use it to track demons, especially their \"fiends\". Those particular creatures tend to consume the astral glory in the area, making it difficult to replenish our stores of the herb. If you could help thin their numbers out, it would greatly help us from having to search elsewhere for supplies. You can find many of them in the Annihilan Pits. I could also teach you the recipe for this potion for your effort.", ["objectivesText"] = "Kill 14 Feflame Scavengers at the Annihilan Pits.", ["rewardItems"] = { 151609 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 125346, ["x"] = 0.562, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 125346, ["x"] = 0.562, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 357, ["name"] = "Legion Alchemy", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48016] = { ["id"] = 48016, ["name"] = "Ascending Alchemy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 48002, 48013, 48016 }, ["series"] = { 48002, 48013 }, ["description"] = "I've seen other alchemists come through our camp carrying interesting looking trinkets. I believe they refer to them as... \"alchemist stones\"? I can sense the power they radiate, but they appear fel-tainted. The herb that grows on this planet is particularly good at cleansing corruption. I use it to purify the primal sargerite that's often found amongst the herbs. I'm certain that if we used a purified sargerite with one of those stones, we could elevate the power within it.", ["objectivesText"] = "Bring Funen 75 Astral Glory , 5 Primal Sargerite and a Bound Infernal Alchemist Stone . Progress: I know it's a lot of materials to ask for, but it's necessary.", ["rewardItems"] = { 127842, 127906, 151565, 151568, 164379, 164380 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 125346, ["x"] = 0.562, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 125346, ["x"] = 0.562, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 357, ["name"] = "Legion Alchemy", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48021] = { ["id"] = 48021, ["name"] = "Chromie", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 48021 }, ["description"] = "<name>. Is that you? I'm convinced that something unusual has happened in the timelines. I need your help! Come find me at Wyrmrest Temple, in Dragonblight, and I'll show you.", ["objectivesText"] = "Reach \"Timehopper\" friendship rank with Chromie in Dragonblight. Progress: Any luck traversing the timeways?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 150938, 150939, 150940, 150941, 150943, 150944, 150945, 150946, 151141, 151166, 151167, 151168, 151484, 151485, 151486, 151491, 151493, 151692, 151693, 151694, 151695, 151700, 232877, 233014 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[48027] = { ["id"] = 48027, ["name"] = "The Glory of Argus", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 48027 }, ["description"] = "<Amazed that anything so pure could continue to grow on this planet, you pick the flower from the ground. You feel a small power radiate from it and then vanish.> <As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.>", ["objectivesText"] = "Find someone on Argus who might be able to train you on how to handle Astral Glory. Provided item:", ["rewardItems"] = { 151856 }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 125346, ["x"] = 0.562, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["startItems"] = { 151856 } },
[48028] = { ["id"] = 48028, ["name"] = "Youthful Resistance", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 48028 }, ["description"] = "<As you begin to gather the flowers, you realize that some of the younger blooms are still resistant to your approach and refuse to yield. Perhaps Funen might know more about how to handle the herb in its adolescent stages.>", ["objectivesText"] = "Ask Funen about how to handle the younger Astral Glories. Provided item:", ["rewardItems"] = { 151568, 151857 }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 125346, ["x"] = 0.562, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["startItems"] = { 151857 } },
[48029] = { ["id"] = 48029, ["name"] = "The Heart of It", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 48029 }, ["description"] = "<Having handled astral glory for a while now, you've picked up on something interesting about its roots. Tightly wound in a cocoon, small flecks of light permeate through the cracks creating a shimmering effect.> <Perhaps Funen might be able to expand on the nature of these lights.>", ["objectivesText"] = "Ask Funen about the shimmering roots of the Astral Glory. Provided item:", ["rewardGold"] = 619600, ["rewardXP"] = 100, ["rewardItems"] = { 6948, 25712, 25713, 25714, 36739, 50375, 50376, 50377, 50378, 50384, 50386, 50387, 50388, 50397, 50398, 50399, 50400, 50401, 50402, 50403, 50404, 52569, 52570, 52571, 52572, 54921, 54922, 57320, 57321, 57322, 58991, 58992, 58993, 60709, 60710, 64507, 64508, 64509, 64510, 64511, 64512, 64513, 64514, 112603, 112604, 112605, 112606, 129250, 129251, 129252, 129253, 129254, 129255, 129256, 129257, 131300, 131417, 131557, 147442, 151858, 156932, 159901, 159902, 159903, 159904, 159905, 159906, 159907, 159908, 160906, 160907, 160908, 160909, 160910, 160911, 160912, 160913, 160914, 160915, 160916, 160917, 160918, 160919, 160920, 160921, 175648, 175649, 175650, 175651, 175713, 175740, 176832, 176921, 176922, 179500, 179508, 179517, 179537, 179547, 179562, 179584, 179604, 180944, 181368, 181377, 181407, 181409, 181410, 181418, 181422, 181423, 181424, 181425, 181430, 181457, 181458, 181459, 181477, 181479, 181506, 181541, 181569, 181577, 181587, 181591, 181603, 181605, 181627, 181632, 181633, 181635, 181636, 181637, 181702, 181704, 181738, 181745, 182128, 182203, 182385, 182480, 182649, 182675, 182736, 182743, 183167, 183402, 183468, 183469, 183473, 183481, 183482, 183486, 183489, 184294, 184362, 184373, 184374, 184381, 184382, 184383, 184384, 184587, 184765, 184766, 184767, 184768, 189865, 198002, 198003, 198004, 198006, 198009, 198034, 198105, 198612, 200597, 204581, 204589, 204597, 204605, 211279, 219764, 219765, 237812, 251547, 253021 }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 125346, ["x"] = 0.562, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["startItems"] = { 151858 } },
