[48034] = { ["id"] = 48034, ["name"] = "Empyrium Deposit Chunk", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["storyline"] = { 48034 }, ["description"] = "<As you swing your pickaxe into the ore, it hits with a resounding thud, sending a small chunk of it to the ground. At this rate, it would take you all day to get a sufficient amount of ore from this deposit.> <Perhaps someone can give you some insight into how to mine this deposit properly.>", ["objectivesText"] = "Find someone on the Vindicaar who might be able to train you on how to mine an empyrium deposit. Provided item:", ["rewardItems"] = { 151860, 151861 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["startItems"] = { 151860 } },
[48035] = { ["id"] = 48035, ["name"] = "Angling For a Better Strike", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["storyline"] = { 48035 }, ["description"] = "<Looking at the empyrium dust from taking down this deposit, you wonder if there's a way to prevent part of the deposit from shattering with each impact.> <Perhaps Khamir will know something further that he can share with you.>", ["objectivesText"] = "Speak with Khamir and see if there's a better way to mine empyrium deposits. Provided item:", ["rewardItems"] = { 151861 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["startItems"] = { 151861 } },
[48036] = { ["id"] = 48036, ["name"] = "Precision Perfected", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["storyline"] = { 48036 }, ["description"] = "<While you've learned to extract as much of the deposit as you can, the core of the deposit is always left unusable. Looking closely, you can see where your strikes were causing fractures in its structure.> <One more lesson from Khamir might be needed to correct this problem.>", ["objectivesText"] = "Speak with Khamir and see if there's an even better way to mine empyrium deposits. Provided item:", ["rewardItems"] = { 151862 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["startItems"] = { 151862 } },
[48037] = { ["id"] = 48037, ["name"] = "Empyrium Seam Chunk", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["storyline"] = { 48037 }, ["description"] = "<At first you thought the ore to have a mirrored surface, reflecting the starry space above you. After breaking off a chunk, you realize that the ore itself has a starry quality all of its own.> <Perhaps someone back at the Vindicaar can give you some insight on how to better extract these seams more efficiently.>", ["objectivesText"] = "Find someone at the Vindicaar who might be able to train you on how to mine empyrium seams. Provided item:", ["rewardItems"] = { 151863 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["startItems"] = { 151863 } },
[48038] = { ["id"] = 48038, ["name"] = "Don't Just Pick At It", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["storyline"] = { 48038 }, ["description"] = "<Even though you've learned to expose the ore, large chunks of it still seem to be embedded in the surrounding rock. Picking those pieces away may not result in the pure form of empyrium that you're looking for.> <Perhaps Khamir can show you a way to remove the ore from these sections of the seam.>", ["objectivesText"] = "Speak with Khamir about a way to extract more ore from empyrium seams. Provided item:", ["rewardItems"] = { 151864 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["startItems"] = { 151864 } },
[48039] = { ["id"] = 48039, ["name"] = "Balancing the Break", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["storyline"] = { 48039 }, ["description"] = "<Getting down to the root of the seam, you're left with nothing but small bits and pieces. Collectively though, they would have been enough to work with.> < Khamir might know a way to prevent this from happening.>", ["objectivesText"] = "Speak with Khamir about a way to extract even more ore from empyrium seams. Provided item:", ["rewardItems"] = { 151865 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["startItems"] = { 151865 } },
[48040] = { ["id"] = 48040, ["name"] = "Tainted Scraps", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["storyline"] = { 48040 }, ["description"] = "<As you begin to carefully remove the skin from the corpse, you notice it quickly becoming corrupted by the decay of the creature.> <Pulling away, you were only able to extract a small amount of leather and something foul smelling. Perhaps someone on the Vindicaar might know more about this foul hide.>", ["objectivesText"] = "Find someone at the Vindicaar who might be able to train you on how to skin fiendish leather. Provided item:", ["rewardItems"] = { 151866 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["startItems"] = { 151866 } },
[48041] = { ["id"] = 48041, ["name"] = "A Larger Cut", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["storyline"] = { 48041 }, ["description"] = "<While you've become quicker at removing pieces of the hide, there is still much that is spoiled before you're able to remove it.> < Enstraa might have a better idea of how to remove more of the hide before it becomes tainted.>", ["objectivesText"] = "Speak with Enstraa about a better way to remove fiendish leather. Provided item:", ["rewardItems"] = { 151867 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["startItems"] = { 151867 } },
[48042] = { ["id"] = 48042, ["name"] = "Order of Operations", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["storyline"] = { 48042 }, ["description"] = "<The skins have been more abundant, but you're only able to gather a couple teeth and claws before they take on the corruption.> <Unsure as to how to extract as many teeth and claws as possible, you find yourself wanting to have one last conversation with Enstraa back at the Vindicaar.>", ["objectivesText"] = "Speak with Enstraa about a better way to dissect the beasts of Argus. Provided item:", ["rewardItems"] = { 151566, 151868 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["startItems"] = { 151868 } },
[48043] = { ["id"] = 48043, ["name"] = "FLAG - Plating Cleared", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 48043 }, ["rewardItems"] = { 151282, 151283 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[48044] = { ["id"] = 48044, ["name"] = "FLAG - Shields Cleared", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 48044 }, ["rewardItems"] = { 151282, 151283 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[48054] = { ["id"] = 48054, ["name"] = "Weigh Anchor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 76, ["storyline"] = { 48054 }, ["description"] = "<name>, I was hoping to ask you for a small favor. The naval fleet at Bilgewater Harbor have been requesting large amounts of felslate to help construct supplies for their ships. I'm pretty busy here coordinating the gathering efforts and all my couriers are still out. I was wondering if you wouldn't mind taking that shipment over there to them? I heard there's a portal to Orgrimmar in the Windrunner's Sanctuary here in Dalaran so it shouldn't be a long trip or anything.", ["objectivesText"] = "Bring the Crate of Felslate to Kruda Thunderhand at Bilgewater Harbor. Progress: Did Vridiel send you?", ["rewardItems"] = { 151871 }, ["ends"] = { { ["mapID"] = 76, ["npcID"] = 125216, ["x"] = 0.552, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 76, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 76 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 76, ["questLines"] = { { ["id"] = 364, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48055] = { ["id"] = 48055, ["name"] = "Empyrial Strength", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 887, ["storyline"] = { 48055 }, ["description"] = "I see my armor's caught your interest. It's made from the finest material on Argus: empyrium. I actually specialize in crafting breastplates. I could show you how to craft one, but you'll need to bring your own supplies, I'm afraid. Our stores of the ore are low and we need all that we have. But here are the plans so you'll know what you need to find...", ["objectivesText"] = "Craft an Empyrial Breastplate . You can find the materials from gathering the ore from Argus, from other players, or from the auction house. Progress: I hope those plans weren't too complicated for you to understand.", ["rewardItems"] = { 151564, 151568, 151576, 151872, 151923, 151924, 151925 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8899 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 887, ["questLines"] = { { ["id"] = 358, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48056] = { ["id"] = 48056, ["name"] = "A Harsh Mistress", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 48056, 48065, 48069 }, ["description"] = "So there I was thinkin' about how to get everyone ready for movin' around Argul or whatever it's called, since I figure its gravity is different than ours, and I come up with a design for a device you slip onto your shoes, or hooves or whatever you're wearin' down there. Next thing I hear, the gravity on that planet? Completely the same as ours! Regardless, I figure I could get the prototype workin'. Mind givin' me a hand? Maybe when we're done you can like, sell 'em to kids or somethin'.", ["objectivesText"] = "Help Hobart calibrate the Prototype Gravitational Reduction Slippers around Dalaran. Progress: This is gonna be fun... to watch!", ["rewardItems"] = { 151927 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 359, ["name"] = "Legion Engineering", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48065] = { ["id"] = 48065, ["name"] = "Extraterrestrial Exploration", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 48056, 48065, 48069 }, ["series"] = { 48069 }, ["description"] = "<name>, I hear you've been over to that large green planet in the sky already. Swarming with demons too, I hear. I was thinking maybe we could put together another wormhole generator for it. Make it easier to zip around the planet. Problem is we need to get readings on the landscape, and I'd go, but uh... well I need to stay here and run the shop. Can't leave it to these bozos to handle. Here, take this and get some readings for me, will ya?", ["objectivesText"] = "Use the Ionized Geographical Recorder at the locations marked on your map. Return to Didi when you're finished.", ["rewardItems"] = { 151926 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 359, ["name"] = "Legion Engineering", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48069] = { ["id"] = 48069, ["name"] = "The Wrench Calls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 627, ["storyline"] = { 48056, 48065, 48069 }, ["series"] = { 48065 }, ["description"] = "<name>, Didi the Wrench is looking for you back in Dalaran. You might want to see what she's working on. Pretty fancy stuff from what I heard.", ["objectivesText"] = "Meet with Didi the Wrench in Dalaran.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8899 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 359, ["name"] = "Legion Engineering", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48074] = { ["id"] = 48074, ["name"] = "Looming Over Me", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 887, ["storyline"] = { 48074 }, ["description"] = "When I rallied to the Xenedar, I left behind a valuable tool. My lightweave loom . Without it, I'm forced to labor for much longer to make garments of power for our allies. But you are powerful, much more so than I. Perhaps you could do me a favor. Should you happen to be in the Arinor Gardens, could you retrieve my loom and return it to me? I'd be more than willing to share my knowledge of sewing lightweave with you.", ["objectivesText"] = "Go to the Arinor Gardens and retrieve Khaela 's Lightweave Loom . Progress: Any luck in finding my loom?", ["rewardItems"] = { 151874 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8899 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 887, ["questLines"] = { { ["id"] = 363, ["name"] = "Legion Tailoring", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48075] = { ["id"] = 48075, ["name"] = "A Colorful Key", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 887, ["storyline"] = { 48075, 48076 }, ["description"] = "<name>, I hear you're a jewelcrafter. I too am a master cutter, but I fear my designs will be lost to the Legion. I hurried out of my home with the intention of returning, but I fear that may not be a possibility. You see, I left my most prized possession, a book of jewelcrafting designs. But you, you're strong, you could fight your way into my home and recover my book! However, I locked it away in a special chest that requires the gems of this land to unlock. You'll need one of each to open it.", ["objectivesText"] = "Travel to Vorel 's home and unlock his chest using each of the six gems that come from prospecting empyrium. Recover his jewelcrafting book and return to him on the Vindicaar. Progress: The combination isn't that difficult, just put the gems in their appropriate settings.", ["rewardItems"] = { 151564, 151568, 151579, 151580, 151583, 151584, 151585, 151718, 151719, 151720, 151721, 151722, 151876, 152726 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8899 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 887, ["questLines"] = { { ["id"] = 361, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48076] = { ["id"] = 48076, ["name"] = "A Crowning Achievement", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 887, ["storyline"] = { 48075, 48076 }, ["description"] = "With my book nearly being lost forever, it occurs to me that I shouldn't keep all this knowledge in one place. I would like to pass it along to you, <name>. My most recent designs are ones that I am particularly proud of. I call them Empyrial Crowns . Each one uses a different combination of gems to render different effects of power. Let me show you how to construct one and then I'll show you how different combinations of gems create different results.", ["objectivesText"] = "Craft an Empyrial Crown for Vorel . You can find the materials from gathering and prospecting the ore from Argus, from other players, or from the auction house. Progress: Perhaps in time you too will find a student whom you may pass all your knowledge unto.", ["rewardItems"] = { 151568, 151587, 151588, 151589, 151590, 151878 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8899 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 887, ["questLines"] = { { ["id"] = 361, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48078] = { ["id"] = 48078, ["name"] = "Counterbalancing", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 887, ["storyline"] = { 48078 }, ["description"] = "In the past, I was able to make glorious items from the beasts of this land. But then the Legion came and wiped out all those amazing beasts. Now I'm forced to use their polluted hides to craft armor for my allies. I have, however, found a way to remove their taint. The cloth we use is made from special thread infused with Light energy. I devised an oil which when combined with the cloth purifies the leather and makes it usable. Here, take my oil and see for yourself.", ["objectivesText"] = "Gather Fiendish Leather and Lightweave Cloth and use Enstraa's Tanning Oil to create 12 Purified Fiendish Leather . Progress: I often dream of working with unsullied leather again. But who knows when that will ever be...", ["rewardItems"] = { 151566, 151567, 151568, 151879, 151880 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 887, ["questLines"] = { { ["id"] = 362, ["name"] = "Legion Leatherworking", ["orderIndex"] = 0, ["flags"] = 0 } } },
