[48192] = { ["id"] = 48192, ["name"] = "Tar Spitter", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite", "rare" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 48192 }, ["rewardGold"] = 606600, ["rewardXP"] = 9210, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "world", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["db2QuestInfoID"] = 136, ["db2QuestInfoName"] = "Rare Elite World Quest" },
[48203] = { ["id"] = 48203, ["name"] = "The Burning Throne", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8701, ["storyline"] = { 48203 }, ["description"] = "The time has come, <name>, to begin our assault upon Antorus. Everything we have fought for, everything our friends and family have sacrificed, has brought us to this moment. We will fire Light's Judgment upon the walls of the accursed citadel and storm their seat of power. We will end the Legion. After all you have done, it is fitting that you have the honor. Activate the Crown of the Triumvirate and let us finish our mission.", ["objectivesText"] = "Use the Crown of the Triumvirate while above the Antoran Wastes to open the way to Antorus. Progress: We have not come this far to stop now.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 152626, 152984, 237812, 246815, 246936, 249400, 251821, 254267, 254579, 264675 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8701 } }, ["questType"] = "standard" },
[48230] = { ["id"] = 48230, ["name"] = "Fragment of the Past", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["storyline"] = { 48230 }, ["description"] = "<Your eye is drawn to the faint glow of the crystalline fragment. Examining the piece, you trace the partial pattern of a rune that had been inscribed upon its surface. The fragment appears similar to the argunite crystals used by the Army of the Light to power their armaments. Could this crystal have belonged to the eredar who fought to escape Argus so long ago? Perhaps Captain Fareeya would be able to tell you more about the crystal.>", ["objectivesText"] = "Take the Glowing Key Fragment to Captain Fareeya .", ["rewardGold"] = 140450, ["rewardXP"] = 6140, ["rewardItems"] = { 142460, 152204, 152241, 152242, 152243, 152244, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["startItems"] = { 152204 } },
[48272] = { ["id"] = 48272, ["name"] = "Visions of Fear", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 48272 }, ["description"] = "I've done it, <lad/lass>. I've reached him again! Oh, but it's so painful. So painful! He's not doin' well, not one bit! You'll have to listen on in with me to understand.", ["objectivesText"] = "Witness Argus' vision with Magni. Progress: It's a lot to take in, I know, but it might help us while we can still be helped.", ["rewardGold"] = 77400, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 124595, ["x"] = 0.568, ["y"] = 0.668667 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 124595, ["x"] = 0.568, ["y"] = 0.668667 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.668667 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard" },
[48273] = { ["id"] = 48273, ["name"] = "The Speaker Listens", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 48273 }, ["description"] = "Magni has sent for you in Krokul Hovel once more. He seems to have made a new breakthrough in trying to reach Argus. I suggest you find him immediately. His last vision foretold Aggramar's coming, and there is still so much we do not know of Sargeras' plans.", ["objectivesText"] = "Meet Magni in the Krokul Hovel.", ["rewardGold"] = 77400, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 124595, ["x"] = 0.568, ["y"] = 0.668667 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.668667 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard" },
[48277] = { ["id"] = 48277, ["name"] = "The Speaker Seeks", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 48277 }, ["description"] = "Our forces are ready for battle, but we still do not know where Eonar's spirit lies. You should seek Magni out at once and see if you can find her while we still have a chance. If she falls, nothing we muster will be able stand against Sargeras.", ["objectivesText"] = "Meet Magni in the Krokul Hovel.", ["rewardGold"] = 77400, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 124595, ["x"] = 0.568, ["y"] = 0.668667 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.668667 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard" },
