[48489] = { ["id"] = 48489, ["name"] = "The Spires of Home", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 48489 }, ["description"] = "My sister Vereesa told me of the events that led to the high... excuse me, \"blood\" elves joining the Horde. Part of me still can't accept it. Prince Kael'thas led my people down a dark path. I have to believe the majority of sin'dorei would shrug off the Horde if given the choice. The last time I spoke to Lor'themar, we served together in the Farstriders. He was a fine ranger and a good man. I pray the years have not changed that. Come. We must not keep the regent waiting.", ["objectivesText"] = "Meet Alleria Windrunner on the Isle of Quel'Danas.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
