[48954] = { ["id"] = 48954, ["name"] = "Blood of a Titan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 48954 }, ["description"] = "<Before your eyes, a trickle of blood from the fallen titan Argus congeals into a flawless gemstone. Holding it in your palm, you sense an almost unfathomable power emanating from within... along with echoes of pain and sorrow. It is the last remnant of a battle that should not have been winnable. An impossible achievement. Yet, as with all victories, this one came at tremendous cost. You realize immediately to whom you must convey this prize.>", ["objectivesText"] = "Bring the blood of Argus the Unmaker to Khadgar in Dalaran. Provided item:", ["rewardXP"] = 1535, ["rewardItems"] = { 104246, 128422, 152900, 152901 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["startItems"] = { 152900 } },
