[48964] = { ["id"] = 48964, ["name"] = "Immortal Ace", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8899, ["storyline"] = { 48964 }, ["description"] = "<The scroll's runes shift to a more intelligible form.> An effigy. The Many-Faced One requires it. Steal from the Imps. Steal from the Fiends. Steal from the Ur'zul. He comes.", ["objectivesText"] = "Collect bones from the Antoran Wastes to form a bone effigy.", ["rewardGold"] = 194000, ["rewardXP"] = 200, ["rewardItems"] = { 152786 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8899 } }, ["questType"] = "standard" },
