[48977] = { ["id"] = 48977, ["name"] = "Supplies From the Army of the Light", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8574, ["storyline"] = { 48977 }, ["description"] = "Archenon poros, champion. The Army of the Light wishes to thank you for your aid against the Legion's forces on Argus. Please accept these supplies with our gratitude. Your continued support brings us ever closer to our ultimate goal of eradicating the Legion once and for all.", ["objectivesText"] = "Speak with Vindicator Jaelaana on the Vindicaar for your reward.", ["rewardItems"] = { 152923, 153043, 153044, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2166, ["threshold"] = 10000 } } } },
