[49014] = { ["id"] = 49014, ["name"] = "The Burning Throne", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 8899, ["storyline"] = { 49014 }, ["description"] = "The time has come, <name>, to begin our assault upon Antorus. Everything we have fought for, everything our friends and family have sacrificed, has brought us to this moment. We will fire Light's Judgment upon the walls of the accursed citadel and storm their seat of power. We will end the Legion. After all you have done, it is fitting that you have the honor. Speak to Romuul and let us finish our mission.", ["objectivesText"] = "Speak with Grand Artificer Romuul while above the Antoran Wastes to open the way to Antorus.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 152593, 152626, 152984, 237812, 246815, 246936, 249400, 251821, 254267, 254579, 264675 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8899 } }, ["questType"] = "standard" },
[49015] = { ["id"] = 49015, ["name"] = "Antorus, the Burning Throne: The Death of a Titan", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8574, ["mapID"] = 882, ["storyline"] = { 49015 }, ["description"] = "There is no way to express the depth of my sorrow. My rage. What Sargeras has done... Argus, my home world, holds the soul of a titan. It has been twisted and corrupted beyond redemption, its power harnessed to fuel the Legion's infinite army. We must do the impossible... breach the depths of Antorus and sever the Legion's connection to the world soul. Please, <name>. End its pain, its suffering. In striking down the dark heart of Argus, we will defeat the Legion... and redeem the soul of my world.", ["objectivesText"] = "Strike down the soul of Argus in Antorus, the Burning Throne . Progress: Argus... what could have been...", ["rewardItems"] = { 152593, 152626, 152984, 154172, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.523111, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8574 } }, ["questType"] = "raid" },
[49027] = { ["id"] = 49027, ["name"] = "Targets of Opportunity: Terminus", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 49027 }, ["description"] = "Those Legion ships are a problem, <name>. Even now they dock perilously close to the Vindicaar, threatening us with their presence. Sometimes when fighting the Legion it is better to go straight to the top rather than thinning their numbers. Go to the shipyards of Terminus and slay their officers and commanders. That should rattle their forces and put them back on the defensive.", ["objectivesText"] = "Slay $1oa Rare Elites in Terminus.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 152733, 152737, 152740 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[49029] = { ["id"] = 49029, ["name"] = "Invasion of Space", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 49029 }, ["description"] = "We are on the Legion home world, but we must not let ourselves get caught unawares. These invasion points can bolster their forces and ruin our plans. By defeating them on their territory we also damage their command and infrastructure. Slay the commanders and stop their invading forces. The fight to push the Legion back begins now!", ["objectivesText"] = "Defeat any $1oa commanders in Invasion Points.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 152733, 152737, 152740 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[49030] = { ["id"] = 49030, ["name"] = "Fragments of the Abyss", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 49030 }, ["description"] = "Our scouts have delivered a disturbing report, champion. Some of the more powerful creatures of the Void are carrying powerful crystals that augment their abilities. They now pose a greater threat than before, and we can no longer ignore them. Find these void-tainted monstrosities and take their crystals. We will find a way to dispose of them safely.", ["objectivesText"] = "Collect $1oa <PH SHADOW CRYSTAL THINGS> from Rare Elites on Argus.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 152733, 152737, 152740 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[49031] = { ["id"] = 49031, ["name"] = "Out With The Inquisitors", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 49031 }, ["description"] = "Of all of the demons at the Legion's disposal, the inquisitors are some of the most terrible. Even feared by some of the lesser demons, these monsters delight in cruelty and torturing their captives. Inquisitors revel in the terror they cause, but perhaps we can make that work to our advantage. Find the most powerful inquisitors you can and defeat them. Their deaths will not only improve the morale of our troops, but also send a message to their lesser forces.", ["objectivesText"] = "Slay $1oa Rare Elite inquisitors on Argus.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 152733, 152737, 152740 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
