[49224] = { ["id"] = 49224, ["name"] = "The Netherlight Crucible", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 9359, ["storyline"] = { 49224 }, ["description"] = "The crucible thrums with power. Soon our weapons will shine like the stars themselves! We will need that strength if we are to have any hope of defeating the Legion here. <name>, you have endured great hardship to bring us to this moment. The honor of first tapping the crucible's power must be yours.", ["objectivesText"] = "Imbue a relic with Netherlight Fortification using the Netherlight Crucible. Progress: We need every advantage we can muster if we are to see the Legion's end.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9359 } }, ["questType"] = "standard" },
[49293] = { ["id"] = 49293, ["name"] = "Invasion Onslaught", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 8899, ["mapID"] = 885, ["storyline"] = { 49293 }, ["description"] = "We must not yield even a single world to the Legion. Continue our Invasion Point offensive and crush the Legion beneath your heel.", ["objectivesText"] = "Complete 3 standard Invasion Points . Progress: The offensive continues.", ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 885, ["npcID"] = 127051, ["x"] = 0.688, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 885, ["npcID"] = 127051, ["x"] = 0.688, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 885, ["source"] = "quest_giver", ["x"] = 0.688, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 885 }, ["zone"] = { 8899 } }, ["questType"] = "standard" },
[49472] = { ["id"] = 49472, ["name"] = "A Titanic Effort", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 49472 }, ["description"] = "Illidan may have forced fate's hand, but bringing Argus so near to Azeroth has accelerated the reaction triggered by the Nightwell's collapse. I believe the Legion's actions on Argus are further destabilizing the powers we've drawn upon unknowingly for many years. It is clear that further studies are required.", ["objectivesText"] = "Bring 50 Wakening Essence to Arcanomancer Vridiel . Progress: Illidan may believe that no price is too high to pay for banishing the Legion, but fate might prove him wrong.", ["rewardItems"] = { 154879, 154880 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[49473] = { ["id"] = 49473, ["name"] = "A Titanic Effort", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 49473 }, ["description"] = "The reaction's intensity is accelerating by the day. We may win the fight against the Legion only to lose something very dear to us. Is this a portent of some greater upheaval to come? What fate awaits our world, <name>? I will seek answers at my forge, as I have done all my life. Your answers, I suspect, lie elsewhere.", ["objectivesText"] = "Bring 50 Wakening Essence to Arcanomancer Vridiel . Progress: If I do not soon discover the underlying cause of this disturbance, I fear we may find ourselves too far down the path to turn back.", ["rewardItems"] = { 154879, 154880 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[49474] = { ["id"] = 49474, ["name"] = "The Cursed Shard", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7502, ["storyline"] = { 49474 }, ["description"] = "<A unnatural metallic shard catches your eye as it shifts from color to color. At your touch, one end of the shard swells in size before melting away. Droplets hit the ground with a hiss and a noxious stench invades your nostrils. Someone in Dalaran who works with metals should be able to tell you more.>", ["objectivesText"] = "Bring the Cursed Shard to Arcanomancer Vridiel in Dalaran on the Broken Isles.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 154879, 154880 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["startItems"] = { 154880 } },
[49538] = { ["id"] = 49538, ["name"] = "Warchief's Command: Jade Forest!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 49538 }, ["series"] = { 29611, 29612, 29690, 31765, 31766, 31767, 31768, 31769, 31853, 60126 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to General Nazgrim in Orgrimmar. Recent victories in our naval battles against the Alliance strengthens our resolve. Report to Grommash Hold and assist the Horde's invasion fleet. For the Horde!", ["objectivesText"] = "Report to General Nazgrim in Grommash Hold.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 54870, ["x"] = 0.485, ["y"] = 0.707 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.707 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
