[49540] = { ["id"] = 49540, ["name"] = "Warchief's Command: Krasarang Wilds!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6134, ["mapID"] = 376, ["storyline"] = { 49540 }, ["series"] = { 29873, 30079, 30081, 49558 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to Zhu's Watch in Krasarang Wilds . There have been rumors that the pandaren living in Krasarang Wilds are not their usual self. Speak with Ken-Ken at Zhu's Watch. Perhaps he has a better idea of what has happened to cause the pandaren to become lethargic.", ["objectivesText"] = "Speak with Ken-Ken in Krasarang Wilds .", ["rewardGold"] = 2775, ["rewardXP"] = 260, ["ends"] = { { ["mapID"] = 376, ["npcID"] = 56115, ["x"] = 0.51, ["y"] = 0.262 } }, ["coords"] = { ["mapID"] = 376, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.262 }, ["mapCandidates"] = { ["npc"] = { 376 }, ["zone"] = { 6134 } }, ["questType"] = "standard" },
[49541] = { ["id"] = 49541, ["name"] = "Warchief's Command: Kun-Lai Summit!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 49541 }, ["series"] = { 30457, 31254, 31255, 38936, 49559 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to assist Lorewalker Cho in Kun-Lai Summit . Speak with a messenger grummle in Valley of the Four Winds. They will show you the way to Kun-Lai Summit . For the Horde!", ["objectivesText"] = "Speak to the Messenger Grummle in Valley of the Four Winds.", ["rewardGold"] = 5350, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 63778, ["x"] = 0.458, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard" },
[49542] = { ["id"] = 49542, ["name"] = "Warchief's Command: Townlong Steppes!", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 49542 }, ["series"] = { 30814, 31695, 39127, 49560 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to Taran Zhu in Townlong Steppes . The Shado-Pan want to reclaim their land from the clutches of the yaungol, but lack the numbers to do so. Assist them with their assault against the yaungol. For the Horde!", ["objectivesText"] = "Speak with Taran Zhu in Townlong Steppes .", ["rewardGold"] = 7925, ["rewardXP"] = 430, ["ends"] = { { ["mapID"] = 388, ["npcID"] = 60688, ["x"] = 0.712, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 388, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 388 }, ["zone"] = { 5842 } }, ["questType"] = "standard" },
[49543] = { ["id"] = 49543, ["name"] = "Warchief's Command: Dread Wastes!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 5840, ["mapID"] = 390, ["storyline"] = { 49543 }, ["series"] = { 31001, 31895, 49561 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to Bowmistress Li on the Serpent's Spine in the Vale of Eternal Blossoms. The Shado-Pan are attempting to stop the mantid army from invading the entirety of Pandaria. You can reach Bowmistress Li by securing a kite and flying to the Serpent's Spine. Destiny calls!", ["objectivesText"] = "Speak with Bowmistress Li on the Serpent's Spine.", ["rewardGold"] = 13740, ["rewardXP"] = 515, ["ends"] = { { ["mapID"] = 390, ["npcID"] = 62112, ["x"] = 0.142, ["y"] = 0.77 } }, ["coords"] = { ["mapID"] = 390, ["source"] = "quest_giver", ["x"] = 0.142, ["y"] = 0.77 }, ["mapCandidates"] = { ["npc"] = { 390 }, ["zone"] = { 5840 } }, ["questType"] = "standard" },
[49546] = { ["id"] = 49546, ["name"] = "Warchief's Command: Gorgrond!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6721, ["mapID"] = 543, ["storyline"] = { 49546 }, ["series"] = { 33010, 33543, 33544, 34123, 34124, 34867, 35557 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to Durotan in Gorgrond . Durotan is seeking allies to help us navigate the savage landscape of Gorgrond in hopes that we will find ancient powers to help us destroy the Iron Horde. Speak with him and see what secrets the lands hold. For the Horde!", ["objectivesText"] = "Speak to Durotan in Gorgrond .", ["rewardGold"] = 28090, ["rewardXP"] = 260, ["ends"] = { { ["mapID"] = 543, ["npcID"] = 74594, ["x"] = 0.415333, ["y"] = 0.737333 } }, ["coords"] = { ["mapID"] = 543, ["source"] = "quest_giver", ["x"] = 0.415333, ["y"] = 0.737333 }, ["mapCandidates"] = { ["npc"] = { 543 }, ["zone"] = { 6721 } }, ["questType"] = "standard" },
[49547] = { ["id"] = 49547, ["name"] = "Warchief's Command: Talador!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6662, ["mapID"] = 535, ["storyline"] = { 49547 }, ["series"] = { 34566, 34681, 35036, 35038, 35041, 35128, 35129, 35136, 35139, 35202, 35210, 35399, 35402, 35406, 35416, 35430, 35434, 35487, 35507, 35509, 35510, 35536, 36208, 36209, 36210, 36223, 36482, 36488, 36494, 36508, 36573, 36574, 36953 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to Foreman Grobash in Talador . The Iron Horde seek to control Talador . The area is perfect to send reinforcements to any other part of Draenor quickly and without resistance. Foreman Grobash is currently establishing an outpost in Talador . Travel there and stop the Iron Horde. For the Horde!", ["objectivesText"] = "Speak with Foreman Grobash in Talador .", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 535, ["npcID"] = 79176, ["x"] = 0.71, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 535, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 535 }, ["zone"] = { 6662 } }, ["questType"] = "standard" },
[49548] = { ["id"] = 49548, ["name"] = "Warchief's Command: Spires of Arak!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6722, ["mapID"] = 542, ["storyline"] = { 49548 }, ["series"] = { 34653, 34655, 34656, 34657, 34658, 34659, 34756, 34805, 35537, 35554, 35636, 35668, 35671, 36951, 49566 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to Azik in Spires of Arak . There have been wingless arakkoa seen fleeing from Spires of Arak . Rumors suggest that they are running from an Iron Horde superweapon. We need to find out what is causing them to leave their homeland, and why their wings have withered. For the Horde!", ["objectivesText"] = "Speak with Azik in the Spires of Arak .", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["ends"] = { { ["mapID"] = 542, ["npcID"] = 79539, ["x"] = 0.378, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 542, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 542 }, ["zone"] = { 6722 } }, ["questType"] = "standard" },
