[49567] = { ["id"] = 49567, ["name"] = "Hero's Call: Nagrand!", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 6755, ["mapID"] = 550, ["storyline"] = { 49567 }, ["series"] = { 34674, 34675, 34678, 34682, 37184 }, ["description"] = "All able-bodied citizens of the Alliance are to report to Lieutenant Balfor in Nagrand on Draenor. Yrel is recommending that the Alliance establish an outpost in Nagrand to help in our fight against the Warsong clan. Secure a flight to Nagrand and meet up with Lieutenant Balfor and the supply caravan. Glory to the Alliance!", ["objectivesText"] = "Speak with Lieutenant Balfor in Nagrand on Draenor.", ["rewardGold"] = 30900, ["rewardXP"] = 600, ["ends"] = { { ["mapID"] = 550, ["npcID"] = 79263, ["x"] = 0.864, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 550, ["source"] = "quest_giver", ["x"] = 0.864, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 550 }, ["zone"] = { 6755 } }, ["questType"] = "standard" },
[49772] = { ["id"] = 49772, ["name"] = "For the Alliance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredRaces"] = { 30 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 9359, ["mapID"] = 84, ["storyline"] = { 49772, 50313 }, ["description"] = "The Army of the Light was founded with one purpose: to defeat the Legion. Though we have achieved that goal, a new duty lies before us. Azeroth is a world beset by enemies. Use your training to battle the darkness and uphold the ideals of the Alliance. Go to Stormwind. Seek the king's ambassador at the embassy, then set out to spread the Light's justice across the land. Pheta thones gamera, <name>.", ["objectivesText"] = "Meet Ambassador Moorgard at the Stormwind Embassy.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 23002, 23007, 23015, 23022, 37500, 42792, 42805, 42817, 42830, 65618, 65625, 65639, 65642, 66073, 94219, 108908, 108909, 108910, 108912, 108913, 108914, 108918, 108919, 116202, 151557, 157022, 157756, 157758, 161329, 165010, 165872, 166883, 168615, 168850, 169764, 174068, 174507, 204616, 204617, 204618, 204619, 211279, 223907, 237812, 241215 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 133362, ["x"] = 0.530667, ["y"] = 0.150667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.530667, ["y"] = 0.150667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9359 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 578, ["name"] = "Allies of the Alliance", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49773] = { ["id"] = 49773, ["name"] = "For the Horde", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 28 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7731, ["mapID"] = 85, ["storyline"] = { 49773, 50319 }, ["description"] = "A new age dawns upon Highmountain, <name>. After centuries apart, the bond with our kin from Kalimdor has been reforged. And in the fight to save our land, we found new friends among the people of the Horde. To show the strength we bring to our allies, brave tauren like you must heed the call of adventure. You have been invited to Orgrimmar. Meet with the ambassador at the warchief's embassy, then begin your journey across Azeroth. Earthmother be with you, <name>.", ["objectivesText"] = "Meet Ambassador Blackguard at the Orgrimmar Embassy.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 23002, 23007, 23015, 23022, 29928, 29930, 29931, 29934, 29938, 29941, 29943, 29945, 37956, 37964, 37998, 38006, 38041, 38048, 38081, 38102, 38110, 57509, 57510, 57511, 57512, 65680, 65701, 65719, 65728, 66073, 94220, 111535, 111536, 111537, 111538, 111539, 111540, 111541, 111542, 116202, 118761, 118762, 118763, 118764, 118765, 131486, 131696, 131697, 151557, 155662, 157028, 157757, 157759, 161328, 165001, 165871, 166883, 167169, 168615, 168850, 169765, 174069, 174508, 211279, 223907, 237812, 241215 }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.794 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 7731 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 580, ["name"] = "Allies of the Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49782] = { ["id"] = 49782, ["name"] = "Heritage of the Lightforged", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 30 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1519, ["storyline"] = { 49782 }, ["description"] = "Your service to the Alliance has been most impressive, $p. I could not have done better myself. Well, I could... but not by much. Come, meet with me at the Vindicaar. It is time that we reward your diligence.", ["objectivesText"] = "Meet Captain Fareeya aboard the Vindicaar. Progress: Welcome aboard, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[49783] = { ["id"] = 49783, ["name"] = "Heritage of Highmountain", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 28 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7503, ["storyline"] = { 49783 }, ["description"] = "Your sojourn through Azeroth has been long, $p. And through it all, you have brought honor to Highmountain. Now Thunder Totem calls you home. It is time we thank you for all that you have done for us.", ["objectivesText"] = "Meet Mayla Highmountain in Thunder Totem.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[49784] = { ["id"] = 49784, ["name"] = "Heritage of the Nightborne", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 27 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 49784 }, ["description"] = "You are among the first shal'dorei to venture forth and explore the wilds of Azeroth. But now it is time to come home. Return to Suramar so that we may thank you for helping our people reclaim a place in this world.", ["objectivesText"] = "Meet First Arcanist Thalyssra at the Nighthold.", ["rewardGold"] = 315900, ["rewardXP"] = 6815, ["rewardItems"] = { 156675, 156676, 156677, 156678, 156679, 156680, 156681, 156685, 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 131326, ["x"] = 0.594, ["y"] = 0.855 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.594, ["y"] = 0.855 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard" },
[49788] = { ["id"] = 49788, ["name"] = "For the Alliance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredRaces"] = { 29 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 9415, ["mapID"] = 84, ["storyline"] = { 49788, 50305 }, ["series"] = { 50305, 51486 }, ["description"] = "Mastering the whispers requires constant focus and discipline. Your dedication inspires all who bear the name ren'dorei--for we have become children of the Void. You have learned many lessons here, but the time has come to venture beyond Telogrus Rift. Go to Stormwind, the heart of the Alliance. There, the king's ambassador will greet you and guide you along your journey. Azeroth must be defended. I can think of no one better suited to answer that call than you, $p.", ["objectivesText"] = "Meet Ambassador Moorgard at the Stormwind Embassy.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 23002, 23007, 23015, 23022, 37500, 42792, 42805, 42817, 42830, 65618, 65625, 65639, 65642, 66073, 94219, 108908, 108909, 108910, 108912, 108913, 108914, 108918, 108919, 116202, 151557, 157022, 157756, 157758, 161329, 165010, 165872, 166883, 168615, 168850, 169764, 174068, 174507, 204616, 204617, 204618, 204619, 211279, 223907, 237812, 241215 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 133362, ["x"] = 0.530667, ["y"] = 0.150667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.530667, ["y"] = 0.150667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9415 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 579, ["name"] = "Allies of the Alliance", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49789] = { ["id"] = 49789, ["name"] = "The Pledge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 49789 }, ["description"] = "The ethereals were lying in wait, anticipating someone strong enough in the void to be corrupted by the influence of the Old Gods. We arrived in time to save them, and I will help teach them how to resist the whispers. Umbric is ready to join the Alliance. Let us return to Stormwind and inform King Wrynn.", ["objectivesText"] = "Return to Stormwind and speak with Anduin.", ["rewardGold"] = 28090, ["rewardXP"] = 4115, ["rewardItems"] = { 29294, 29298, 29302, 29307, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[49855] = { ["id"] = 49855, ["name"] = "Disaster at Mount Hyjal", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 49855 }, ["series"] = { 25316, 25317, 25319, 27721, 27726 }, ["description"] = "Our brothers in the Cenarion Circle report that Deathwing's minions have launched a destructive offensive against the world tree and threaten to burn it to the ground! You can speak with Cenarion Emissary Blackhoof to gain entry into Moonglade. He is in the tauren district in the Valley of Wisdom in Orgrimmar.", ["objectivesText"] = "Speak to Cenarion Emissary Blackhoof to secure transportation to Moonglade.", ["rewardGold"] = 13740, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 45244, ["x"] = 0.469714, ["y"] = 0.464571 } }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 39865, ["x"] = 0.454667, ["y"] = 0.447333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.469714, ["y"] = 0.464571 }, ["mapCandidates"] = { ["npc"] = { 80, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[49928] = { ["id"] = 49928, ["name"] = "Heritage of the Void", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 29 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 9415, ["storyline"] = { 49928 }, ["description"] = "Throughout your journeys across Azeroth, you have achieved mastery over the forces that constantly seek to control you. You have become a formidable weapon of the Alliance, $p. Return to the void rift so that we may honor your accomplishment.", ["objectivesText"] = "Meet Alleria Windrunner at Telogrus Rift.", ["rewardGold"] = 319000, ["rewardXP"] = 6815, ["rewardItems"] = { 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9415 } }, ["questType"] = "standard" },
[49933] = { ["id"] = 49933, ["name"] = "For the Horde", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 27 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 49933, 50303 }, ["description"] = "After ages standing alone, we are once again poised to become part of something greater. Our alliance with the Horde affords us a fresh start, a unique chance that must not be squandered. Go to Orgrimmar. From there, you will set out on a journey across Azeroth. Fight to defend this land, and claim a place for the shal'dorei within it. Show the world who we are, <class>. Bring honor to the Horde, for in so doing, you will bring honor to Suramar.", ["objectivesText"] = "Meet Ambassador Blackguard at the Orgrimmar Embassy.", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 23002, 23007, 23015, 23022, 29928, 29930, 29931, 29934, 29938, 29941, 29943, 29945, 37956, 37964, 37998, 38006, 38041, 38048, 38081, 38102, 38110, 57509, 57510, 57511, 57512, 65680, 65701, 65719, 65728, 66073, 94220, 111535, 111536, 111537, 111538, 111539, 111540, 111541, 111542, 116202, 118761, 118762, 118763, 118764, 118765, 131486, 131696, 131697, 151557, 155662, 157028, 157757, 157759, 161328, 165001, 165871, 166883, 167169, 168615, 168850, 169765, 174069, 174508, 211279, 223907, 237812, 241215 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 131326, ["x"] = 0.594, ["y"] = 0.855 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.594, ["y"] = 0.855 }, ["mapCandidates"] = { ["npc"] = { 85, 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 581, ["name"] = "Allies of the Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50048] = { ["id"] = 50048, ["name"] = "The Seething Shore", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49976, 49981, 50046, 50047, 50048, 50049, 50056, 50057, 50226, 50227, 50228, 50371, 50372, 50373, 50374 }, ["description"] = "We've received reports of an island off the coast of Silithus that is ripe with Azerite deposits. It is vital that we secure the island before the Horde learns of its existence. Master Mathias Shaw is personally leading the expedition force and has requested that you report for duty. Good luck!", ["objectivesText"] = "Complete the Seething Shore battleground.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 131963, ["x"] = 0.694, ["y"] = 0.176 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.176 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 12, ["flags"] = 0 } } },
[50242] = { ["id"] = 50242, ["name"] = "A Choice of Allies", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = false, ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 49930, 50242 }, ["description"] = "As ambassador, it is my duty to bolster the Horde's ranks and strengthen our numbers in the face of danger. Your adventures have led you to many different people who can aid the Horde if we can convince them to join our cause. I've kept a record of the most promising potential allies. The choice of which to approach first is yours.", ["objectivesText"] = "Learn more about potential allies. Progress: Is there a problem with my notes?", ["rewardGold"] = 34100, ["rewardXP"] = 685, ["rewardItems"] = { 155662, 156487, 161330 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 126065, ["x"] = 0.378, ["y"] = 0.81 }, { ["mapID"] = 85, ["npcID"] = 133523, ["x"] = 0.378667, ["y"] = 0.809333 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 126065, ["x"] = 0.378, ["y"] = 0.81 }, { ["mapID"] = 85, ["npcID"] = 133523, ["x"] = 0.378667, ["y"] = 0.809333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.81 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 574, ["name"] = "Allies of the Horde", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6057, ["name"] = "Allied Race Display", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50250] = { ["id"] = 50250, ["name"] = "Posthaste", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["storyline"] = { 50250 }, ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[50303] = { ["id"] = 50303, ["name"] = "Stranger in a Strange Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 27 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 49933, 50303 }, ["description"] = "Hi. I'm Ambassador Blackguard . I am honored to welcome you to Orgrimmar, <race>. <He smiles unconvincingly.> As a lifetime of adventure unfolds before you, be assured that... uh... You know what? I've been saying this same greeting all day. Enough's enough. Talk to Chromie on top of the hourglass, then talk to your emissary. Run along.", ["objectivesText"] = "Talk to Chromie in Orgrimmar. Progress: Not quite as beautiful as Suramar, is it?", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 246740, 246795 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 131328, ["x"] = 0.466667, ["y"] = 0.777333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.794 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 581, ["name"] = "Allies of the Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50305] = { ["id"] = 50305, ["name"] = "Stranger in a Strange Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredRaces"] = { 29 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 49788, 50305 }, ["series"] = { 49788, 51486 }, ["description"] = "Welcome to Stormwind, <race>. I invite you to explore our fair city. Say, you look like someone who enjoys the night life. We have many popular taverns and a vibrant music scene! Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of the ren'dorei is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay, <name>!", ["objectivesText"] = "Talk to Chromie in Stormwind City. Progress: So, how does Stormwind suit you?", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 246740, 246795 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 133362, ["x"] = 0.530667, ["y"] = 0.150667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 131347, ["x"] = 0.5988, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.530667, ["y"] = 0.150667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 579, ["name"] = "Allies of the Alliance", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50313] = { ["id"] = 50313, ["name"] = "Stranger in a Strange Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredRaces"] = { 30 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 49772, 50313 }, ["description"] = "Welcome to Stormwind, <race>. I invite you to explore our fair city. Say, you look like the devout sort. We have a lovely cathedral that will no doubt be of interest! Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of the Lightforged is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay, <name>!", ["objectivesText"] = "Find Chromie in Stormwind City. Progress: I can feel the Light in this place.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 246740, 246795 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 133362, ["x"] = 0.530667, ["y"] = 0.150667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 131334, ["x"] = 0.5988, ["y"] = 0.2484 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.530667, ["y"] = 0.150667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 578, ["name"] = "Allies of the Alliance", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50316] = { ["id"] = 50316, ["name"] = "Disturbance Detected: Ulduar", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 4273, ["storyline"] = { 50316 }, ["description"] = "You're late. Don't you remember the last time we had to deal with the tampering that allowed Yogg-Saron to escape from his prison underneath Ulduar ? You were late then too. You should really try to be more punctual. Well, get going! Old gods! Keepers! Titan stuff! Get this one checked off your list so we can move on. We've got times and places to be. < Vormu gestures impatiently for you to leave.>", ["objectivesText"] = "Relive the expedition to Ulduar . Progress: Exactly the same number of dwarves must be roasted as last time. Medium rare, of course - well done would be insanity.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 157030, 208094 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "standard" },
[50319] = { ["id"] = 50319, ["name"] = "Stranger in a Strange Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 28 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 49773, 50319 }, ["description"] = "Hi. I'm Ambassador Blackguard . I am honored to welcome you to Orgrimmar, <race>. <He smiles unconvincingly.> As a lifetime of adventure unfolds before you, be assured that... uh... You know what? I've been saying this same greeting all day. Enough's enough. Talk to Chromie on top of the hourglass, then talk to your emissary. Run along.", ["objectivesText"] = "Talk to Chromie . Progress: Not quite as beautiful as Highmountain, is it?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 246740, 246795 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 131201, ["x"] = 0.4735, ["y"] = 0.775 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.794 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 580, ["name"] = "Allies of the Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50335] = { ["id"] = 50335, ["name"] = "Grant Me Revenge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 717, ["storyline"] = { 50335 }, ["description"] = "I don't care who you pledge allegiance to, <race>. I need Hogger dead! He--and the other cretins in this Light-forsaken place--have slain my men. The Alliance and the Horde may not see eyes-to-eye, but you must know that murdering my people in cold blood cannot stand.", ["objectivesText"] = "Defeat Randolph Moloch , Lord Overheat , and Hogger . Progress: Is it done? Is Hogger dead?", ["rewardGold"] = 315000, ["rewardXP"] = 1415, ["rewardItems"] = { 65915, 65941, 65965, 65989, 131683 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 717 } }, ["questType"] = "dungeon" },
[50336] = { ["id"] = 50336, ["name"] = "The G-Team", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 721, ["storyline"] = { 50336 }, ["description"] = "I'd keep my distance from B.E Barechus and Murd Doc, neither is terribly stable. Let's get you to work! Go down into this tunnel until you get to Tinkers' Court. Hopefully you'll know what to do when you meet Mekgineer Thermaplugg . Our leader, Commando Hann Ibal waits somewhere in there. He'll reward you handsomely for all your work. Probably....", ["objectivesText"] = "Kill Mekgineer Thermaplugg .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 65913, 65939, 65963, 65987, 66004, 131624, 131625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 721 } }, ["questType"] = "dungeon" },
[50337] = { ["id"] = 50337, ["name"] = "The G-Team", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 721, ["storyline"] = { 50337 }, ["series"] = { 26939, 26941, 26942, 26943, 26944, 50338 }, ["description"] = "That Murd Doc is crazy, <class>. Never, ever, let you find yourself in an aircraft with that gnome. Stealth usually isn't my thing, and it's certainly not going to be yours. Go down this hallway to the Launch Bay and dispose of the Electrocutioner 6000 . The Electrocutioner is in charge of the aircraft... ...and I hate aircraft. I'm not getting in any sort of aircraft! Use this parachute to drop down afterwards and speak with Commando Face for your next job.", ["objectivesText"] = "Kill the Electrocutioner 6000 . Progress: Woah! How did you see me!?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 60680, 65913, 65939, 65963, 65987, 66004, 131624, 131625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 721 } }, ["questType"] = "dungeon" },
[50338] = { ["id"] = 50338, ["name"] = "The G-Team", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 6, ["zoneID"] = 721, ["storyline"] = { 50338 }, ["series"] = { 26939, 26941, 26942, 26943, 26944, 50337 }, ["description"] = "How did you get in here, <name>? I'm Murd Doc of the G-Team and we could use the help of a <race> like you. Help us defeat the irradiated inhabatants that now call Gnomeregan home, and I'll make you an honorary G-Team Commando! Take this parachute, jump down into the Hall of Gears, and take out the Viscous Fallout . After you're done, report to Commando B.E Barechus by the west hallway. You two will get along great, I'm sure.", ["objectivesText"] = "Kill the Viscous Fallout .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 60680, 65913, 65939, 65963, 65987, 66004, 131624, 131625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 721 } }, ["questType"] = "dungeon" },
[50420] = { ["id"] = 50420, ["name"] = "A Gently Shaken Gift", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Feast of Winter Veil", ["expansion"] = 6, ["storyline"] = { 50420 }, ["rewardItems"] = { 21270, 21271, 116762, 128652, 128768, 139337, 139343, 151343, 151345, 162974, 172225, 178529, 187520, 192093, 210657, 218309, 244906 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
